// Data snapshot: 2026-09-18.
const PERK_DETAILS = {"assets/perks/iconPerks_Agitation.png":{"englishName":"Agitation","owner":"Trapper","role":"killer","descriptionEn":"While carrying a Survivor, Agitation activates:\nIncreases your Carrying speed by 14/16/18 %.\nIncreases your Terror Radius\nby +12 metres.","descriptionRu":"При переноске Выжившего активируется Возбуждение:\nУвеличивает скорость переноски на 14/16/18%.\nУвеличивает ваш радиус террора\nна +12 метров.","shortDescriptionRu":"При переноске Выжившего активируется Возбуждение: Увеличивает скорость переноски на 18%. Увеличивает ваш радиус террора на 12 метров.","upcomingPatch":true},"assets/perks/iconPerks_AlienInstinct.png":{"englishName":"Alien Instinct","owner":"Xenomorph","role":"killer","descriptionEn":"Whenever you hook a Survivor, Alien Instinct activates:\nThe Aura\nof the farthest Survivor from your current location who is in the Injured State\nis revealed to you for 8 seconds.\nCauses that Survivor to suffer from the Oblivious\nStatus Effect for 40/50/60 seconds.","descriptionRu":"Каждый раз, когда вы ловите Выжившего, активируется Чужой Инстинкт:\nАура\nсамого дальнего от вашего текущего местоположения выжившего, находящегося в состоянии ранения\nоткрывается вам на 8 секунд.\nПричины, по которым Выживший страдает от Невнимательности\nСтатусный эффект на 40/50/60 секунд.","shortDescriptionRu":"Каждый раз, когда вы ловите Выжившего, активируется Чужой Инстинкт: Аура самого дальнего от вашего текущего местоположения выжившего, находящегося в состоянии ранения открывается вам на 8 секунд. Причины, по которым Выживший страдает от Невнимательности Статусный эффект на 60 секунд.","upcomingPatch":false},"assets/perks/iconPerks_ANursesCalling.png":{"englishName":"A Nurse's Calling","owner":"Nurse","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof Survivors being healed or healing themselves are revealed to you within 28/30/32 metres.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nколичество выживших, исцеляющихся или исцеляющихся самостоятельно, отображается в радиусе 28/30/32 метров.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры количество выживших, исцеляющихся или исцеляющихся самостоятельно, отображается в радиусе 32 метров.","upcomingPatch":false},"assets/perks/iconPerks_AwakenedAwarenesss.png":{"englishName":"Awakened Awareness","owner":"Mastermind","role":"killer","descriptionEn":"While carrying a Survivor, you benefit from the following effect:\nThe Auras\nof other Survivors within 16/18/20 metres of your location are revealed to you.","descriptionRu":"Когда вы несете Выжившего, вы получаете следующий эффект:\nАуры\nВам будут показаны данные других Выживших в радиусе 16/18/20 метров от вашего местоположения.","shortDescriptionRu":"Когда вы несете Выжившего, вы получаете следующий эффект: Ауры Вам будут показаны данные других Выживших в радиусе 20 метров от вашего местоположения.","upcomingPatch":false},"assets/perks/iconPerks_Bamboozle.png":{"englishName":"Bamboozle","owner":"Kenneth Chase","role":"killer","descriptionEn":"You benefit from the following permanent effect:\nIncreases your Vaulting speed by 5/10/15 %.\nWhenever you vault a Window\n, Bamboozle calls upon The Entity\nfor the following effect:\nBlocks it to all Survivors for 8/12/16 seconds.\nVaulting it again within that time resets the timer.\nVaulting a different one transfers the effect to it instead.\nBamboozle does not extend its effects to vaulting a dropped Pallet.","descriptionRu":"Вы получаете следующий постоянный эффект:\nУвеличивает скорость прыжков на 5/10/15%.\nВсякий раз, когда вы сводите окно\n, Bamboozle призывает Сущность\nдля следующего эффекта:\nБлокирует его для всех выживших на 8/12/16 секунд.\nПовторный прыжок в течение этого времени сбрасывает таймер.\nВместо этого при прыжке с другого объекта эффект переносится на него.\nBamboozle не распространяется на подбрасывание упавшего поддона.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Увеличивает скорость прыжков на 15%. Всякий раз, когда вы сводите окно, Bamboozle призывает Сущность для следующего эффекта: Блокирует его для всех выживших на 16 секунд. Повторный прыжок в течение этого времени сбрасывает таймер.","upcomingPatch":false},"assets/perks/iconPerks_batteriesIncluded.png":{"englishName":"Batteries Included","owner":"Charles Lee Ray","role":"killer","descriptionEn":"While within 16 metres of a completed Generator\n, you benefit from the following effect:\nGrants a +5 % Haste\nStatus Effect.\nThis effect lingers for 1/3/5 second(s).","descriptionRu":"Находясь в пределах 16 метров от завершенного Генератора\n, вы получаете следующий эффект:\nДает +5 % скорости.\nЭффект статуса.\nЭтот эффект сохраняется в течение 1/3/5 секунды.","shortDescriptionRu":"Находясь в пределах 16 метров от завершенного Генератора, вы получаете следующий эффект: Дает +5% скорости. Эффект статуса. Этот эффект сохраняется в течение 5 секунды.","upcomingPatch":false},"assets/perks/iconPerks_BBQAndChili.png":{"englishName":"Barbecue & Chilli","owner":"Cannibal","role":"killer","descriptionEn":"A deep bond with The Entity\nunlocks potential in one's Aura-reading ability.\nAfter hooking a Survivor, all Survivors who are at least 60/50/40 metres away from that Hook have their Aura\nrevealed to you for 5 seconds.","descriptionRu":"Глубокая связь с Сущностью\nраскрывает потенциал способности чтения ауры.\nПосле зацепления Выжившего все Выжившие, находящиеся на расстоянии не менее 60/50/40 метров от этого Крюка, получают свою Ауру.\nраскрывается вам в течение 5 секунд.","shortDescriptionRu":"Глубокая связь с Сущностью раскрывает потенциал способности чтения ауры. После зацепления Выжившего все Выжившие, находящиеся на расстоянии не менее 40 метров от этого Крюка, получают свою Ауру. раскрывается вам в течение 5 секунд.","upcomingPatch":false},"assets/perks/iconPerks_BeastOfPrey.png":{"englishName":"Beast of Prey","owner":"Huntress","role":"killer","descriptionEn":"Whenever you trigger the Bloodlust\nStatus Effect, Beast of Prey activates for 30/35/40 seconds:\nGrants the Undetectable\nStatus Effect.","descriptionRu":"Каждый раз, когда вы активируете Жажда крови\nСтатусный эффект «Хищный зверь» активируется на 30/35/40 секунд:\nДарует необнаружимое\nЭффект статуса.","shortDescriptionRu":"Каждый раз, когда вы активируете Жажда крови Статусный эффект «Хищный зверь» активируется на 40 секунд: Дарует необнаружимое Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_BitterMurmur.png":{"englishName":"Bitter Murmur","owner":"Общий","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever a Generator\nis completed, Bitter Murmur triggers its primary effect:\nThe Auras\nof any Survivors within 20 metres of that Generator are revealed to you for 8 seconds.\nOnce the last Generator is completed, Bitter Murmur triggers its secondary effect:\nThe Auras of all Survivors are revealed to you for 10/12/14 seconds.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nВсякий раз, когда генератор\nзавершено, Горький ропот активирует свой основной эффект:\nАуры\nвсех Выживших в радиусе 20 метров от Генератора открываются вам на 8 секунд.\nКак только последний Генератор будет завершен, Горький Ропот активирует свой дополнительный эффект:\nАуры всех Выживших открываются вам на 10/12/14 секунд.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Всякий раз, когда генератор завершено, Горький ропот активирует свой основной эффект: Ауры всех Выживших в радиусе 20 метров от Генератора открываются вам на 8 секунд. Как только последний Генератор будет завершен, Горький Ропот активирует свой дополнительный эффект: Ауры всех Выживших открываются вам на 14 секунд.","upcomingPatch":true},"assets/perks/iconPerks_BloodEcho.png":{"englishName":"Blood Echo","owner":"Oni","role":"killer","descriptionEn":"Whenever you hook a Survivor, Blood Echo triggers its effect:\nCauses all Survivors in the Injured State\nto suffer from the Exhausted\nand Haemorrhage\nStatus Effects for 20/25/30 seconds.","descriptionRu":"Каждый раз, когда вы цепляете Выжившего, «Эхо крови» срабатывает свой эффект:\nПриводит всех выживших в раненое состояние.\nстрадать от истощения\nи кровотечение\nСтатусные эффекты на 20/25/30 секунд.","shortDescriptionRu":"Каждый раз, когда вы цепляете Выжившего, «Эхо крови» срабатывает свой эффект: Приводит всех выживших в раненое состояние. страдать от истощения и кровотечение Статусные эффекты на 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Bloodhound.png":{"englishName":"Bloodhound","owner":"Wraith","role":"killer","descriptionEn":"Bloodhound causes the following effects:\nPools of Blood\nleft by injured Survivors appear in bright red.\nExtends their lifetime by 2/3/4 seconds.","descriptionRu":"Бладхаунд вызывает следующие эффекты:\nЛужи крови\nоставленные ранеными. Выжившие отображаются ярко-красным цветом.\nПродлевает их время жизни на 2/3/4 секунды.","shortDescriptionRu":"Бладхаунд вызывает следующие эффекты: Лужи крови оставленные ранеными. Выжившие отображаются ярко-красным цветом. Продлевает их время жизни на 4 секунды.","upcomingPatch":false},"assets/perks/iconPerks_BloodWarden.png":{"englishName":"Blood Warden","owner":"Nightmare","role":"killer","descriptionEn":"As soon as at least one Exit Gate\nis opened, Blood Warden activates:\nThe Auras\nof Survivors\nare revealed to you, whenever they are inside the Exit Gate.\nOnce per Trial, hooking a Survivor while Blood Warden is active calls upon The Entity\nto trigger the following effect:\nBlocks all opened Exit Gates for 40/50/60 seconds, preventing any remaining Survivor from leaving the Trial through them.","descriptionRu":"Как только хотя бы один выход из ворот\nоткрывается, Кровавый Страж активируется:\nАуры\nвыживших\nоткрываются вам всякий раз, когда они находятся внутри Выходных Врат.\nОдин раз за испытание, если зацепить Выжившего, пока активен Кровавый Страж, он призывает Сущность.\nчтобы вызвать следующий эффект:\nБлокирует все открытые Выходные Врата на 40/50/60 секунд, не позволяя оставшимся Выжившим покинуть Испытание через них.","shortDescriptionRu":"Как только хотя бы один выход из ворот открывается, Кровавый Страж активируется: Ауры выживших открываются вам всякий раз, когда они находятся внутри Выходных Врат. Один раз за испытание, если зацепить Выжившего, пока активен Кровавый Страж, он призывает Сущность. чтобы вызвать следующий эффект: Блокирует все открытые Выходные Врата на 60 секунд, не позволяя оставшимся Выжившим покинуть Испытание через них.","upcomingPatch":false},"assets/perks/iconPerks_BoonDestroyer.png":{"englishName":"Shattered Hope","owner":"Общий","role":"killer","descriptionEn":"To capture your prey, you must first extinguish their hope.\nInstead of snuffing Boon Totems\nyou destroy them.\nDestroying a Boon Totem this way reveals the Auras\nof all Survivors that were within its range at that moment for 6/7/8 seconds.","descriptionRu":"Чтобы поймать свою добычу, вы должны сначала уничтожить ее надежду.\nВместо того, чтобы уничтожать Благотворные Тотемы\nты их уничтожаешь.\nУничтожение Тотема благ таким образом открывает ауры.\nвсех Выживших, находившихся в пределах его досягаемости в этот момент в течение 6/7/8 секунд.","shortDescriptionRu":"Чтобы поймать свою добычу, вы должны сначала уничтожить ее надежду. Вместо того, чтобы уничтожать Благотворные Тотемы ты их уничтожаешь. Уничтожение Тотема благ таким образом открывает ауры.","upcomingPatch":false},"assets/perks/iconPerks_BrutalStrength.png":{"englishName":"Brutal Strength","owner":"Trapper","role":"killer","descriptionEn":"While performing the Break or Damage action on Breakable Walls\n, Pallets\n, or Generators\n, Brutal Strength triggers its effect:\nIncreases the Action speed by 10/15/20 %.","descriptionRu":"При выполнении действия «Разломать или повредить разрушаемые стены»\n, Поддоны\n, или Генераторы\n, «Жестокая сила» активирует свой эффект:\nУвеличивает скорость действий на 10/15/20 %.","shortDescriptionRu":"При выполнении действия «Разломать или повредить разрушаемые стены», Поддоны, или Генераторы, «Жестокая сила» активирует свой эффект: Увеличивает скорость действий на 20%.","upcomingPatch":false},"assets/perks/iconPerks_CallOfBrine.png":{"englishName":"Call of Brine","owner":"Onry%C5%8D","role":"killer","descriptionEn":"After performing the Damage Generator action on a Generator\n, Call of Brine applies its effects to it for 90 seconds:\nIncreases its Regression speed to 130/140/150 % of the default value.\nHighlights its Aura\nto you in yellow.\nTriggers a Loud Noise Notification whenever a Survivor succeeds a Good Skill Check while repairing it.","descriptionRu":"После выполнения действия «Генератор урона» на Генераторе\n, Зов рассола накладывает на него свои эффекты на 90 секунд:\nУвеличивает скорость регрессии до 130/140/150 % от значения по умолчанию.\nПодчеркивает свою ауру\nтебе в желтом.\nВызывает громкий шум всякий раз, когда Выживший успешно проходит проверку навыков во время ремонта.","shortDescriptionRu":"После выполнения действия «Генератор урона» на Генераторе, Зов рассола накладывает на него свои эффекты на 90 секунд: Увеличивает скорость регрессии до 150% от значения по умолчанию. Подчеркивает свою ауру тебе в желтом. Вызывает громкий шум всякий раз, когда Выживший успешно проходит проверку навыков во время ремонта.","upcomingPatch":false},"assets/perks/iconPerks_CorruptIntervention.png":{"englishName":"Corrupt Intervention","owner":"Plague","role":"killer","descriptionEn":"Your prayers invoke a dark power that meddles with the Survivors' chances of survival.\nAt the start of the Trial, the 3 Generators located farthest from you are blocked by The Entity\nfor 80/100/120 seconds.\nCorrupt Intervention deactivates prematurely once the first Survivor is put into the Dying State\n.","descriptionRu":"Ваши молитвы призывают темную силу, которая снижает шансы Выживших на выживание.\nВ начале испытания 3 генератора, расположенные дальше всего от вас, блокируются Сущностью.\nна 80/100/120 секунд.\nКоррупционное вмешательство отключается преждевременно, как только первый выживший переходит в состояние умирания.\n.","shortDescriptionRu":"Ваши молитвы призывают темную силу, которая снижает шансы Выживших на выживание. В начале испытания 3 генератора, расположенные дальше всего от вас, блокируются Сущностью. на 120 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Coulrophobia.png":{"englishName":"Coulrophobia","owner":"Kenneth Chase","role":"killer","descriptionEn":"Survivors inside your Terror Radius\nsuffer from the following effects:\nReduces all Healing speeds by 20/25/30 %.\nIncreases the Pointer-Rotation speed of Healing Skill Checks by +50 %.","descriptionRu":"Выжившие внутри вашего радиуса террора\nстрадают от следующих последствий:\nСнижает скорость лечения на 20/25/30%.\nУвеличивает скорость вращения указателя при проверках навыков исцеления на +50 %.","shortDescriptionRu":"Выжившие внутри вашего радиуса террора страдают от следующих последствий: Снижает скорость лечения на 30%. Увеличивает скорость вращения указателя при проверках навыков исцеления на 50%.","upcomingPatch":false},"assets/perks/iconPerks_CoupDeGrace.png":{"englishName":"Coup de Grâce","owner":"Twins","role":"killer","descriptionEn":"As the end nears, you go in for the kill.\nWhenever a Generator\nis completed, Coup de Grâce gains +2 Tokens, up to a maximum of 10 Tokens per Trial:\nIncreases the range of your next Lunge Attack by 70/75/80 %, while consuming -1 Token.\nCoup de Grâce can only hold a maximum of 5 Tokens at a time.","descriptionRu":"Когда конец приближается, вы готовы убить.\nВсякий раз, когда генератор\nзавершается, Coup de Grace получает +2 жетона, максимум до 10 жетонов за испытание:\nУвеличивает дальность вашей следующей атаки с выпадом на 70/75/80 %, потребляя при этом -1 жетон.\nCoup de Grâce может хранить не более 5 жетонов одновременно.","shortDescriptionRu":"Когда конец приближается, вы готовы убить. Всякий раз, когда генератор завершается, Coup de Grace получает +2 жетона, максимум до 10 жетонов за испытание: Увеличивает дальность вашей следующей атаки с выпадом на 80%, потребляя при этом -1 жетон. Coup de Grâce может хранить не более 5 жетонов одновременно.","upcomingPatch":false},"assets/perks/iconPerks_CruelConfinement.png":{"englishName":"Cruel Limits","owner":"Demogorgon","role":"killer","descriptionEn":"Whenever a Generator\nis completed, Cruel Limits triggers its effect for 20/25/30 seconds:\nBlocks all Windows\nfor all Survivors.\nThe Auras\nof the Blocked Windows are revealed to you and highlighted in yellow.","descriptionRu":"Всякий раз, когда генератор\nзавершено, эффект «Жестоких пределов» срабатывает на 20/25/30 секунд:\nБлокирует все окна\nдля всех выживших.\nАуры\nзаблокированных окон отображаются и выделяются желтым цветом.","shortDescriptionRu":"Всякий раз, когда генератор завершено, эффект «Жестоких пределов» срабатывает на 30 секунд: Блокирует все окна для всех выживших. Ауры заблокированных окон отображаются и выделяются желтым цветом.","upcomingPatch":false},"assets/perks/iconPerks_DarkArrogance.png":{"englishName":"Dark Arrogance","owner":"Lich","role":"killer","descriptionEn":"Whenever you are vaulting a Window\n, you benefit from the following effect:\nIncreases the Vaulting speed by 15/20/25 %.\nWhenever you are stunned with a Pallet\nor blinded by any means, you suffer from the following effects:\nReduces the Recovery speed from Pallet Stuns by -15 %.\nIncreases the duration of Killer Blinds by +15 %.","descriptionRu":"Всякий раз, когда вы сводите окно\n, вы получаете следующий эффект:\nУвеличивает скорость прыжков на 15/20/25%.\nВсякий раз, когда вы оглушены Паллетой\nили ослеплен каким-либо образом, вы страдаете от следующих эффектов:\nСнижает скорость восстановления после оглушения поддонов на -15 %.\nУвеличивает продолжительность действия Killer Blinds на +15 %.","shortDescriptionRu":"Всякий раз, когда вы сводите окно, вы получаете следующий эффект: Увеличивает скорость прыжков на 25%. Всякий раз, когда вы оглушены Паллетой или ослеплен каким-либо образом, вы страдаете от следующих эффектов: Снижает скорость восстановления после оглушения поддонов на -15%. Увеличивает продолжительность действия Killer Blinds на 15%.","upcomingPatch":false},"assets/perks/iconPerks_DarkDevotion.png":{"englishName":"Dark Devotion","owner":"Plague","role":"killer","descriptionEn":"Whenever the Obsession\nbecomes injured by any means, Dark Devotion activates for 35/40/45 seconds:\nTransfers your Terror Radius\nto the Obsession.\nThis Terror Radius is set to 40 metres.\nGrants the Undetectable\nStatus Effect.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Всякий раз, когда одержимость\nполучает травму любым способом, Dark Devotion активируется на 35/40/45 секунд:\nПереносит ваш радиус террора\nк Одержимости.\nЭтот радиус террора установлен на 40 метров.\nДарует необнаружимое\nЭффект статуса.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Всякий раз, когда одержимость получает травму любым способом, Dark Devotion активируется на 45 секунд: Переносит ваш радиус террора к Одержимости. Этот радиус террора установлен на 40 метров. Дарует необнаружимое Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_DarknessRevelated.png":{"englishName":"Darkness Revealed","owner":"Dredge","role":"killer","descriptionEn":"Searching a Locker\nhas the following effect:\nThe Auras\nof Survivors within 8 metres of any Locker are revealed to you for 6/7/8 seconds.\nDarkness Revealed has a cool-down of 30 seconds.","descriptionRu":"Поиск шкафчика\nимеет следующий эффект:\nАуры\nВыживших в радиусе 8 метров от любого шкафчика открываются вам на 6/7/8 секунд.\nВремя восстановления Darkness Revealed составляет 30 секунд.","shortDescriptionRu":"Поиск шкафчика имеет следующий эффект: Ауры Выживших в радиусе 8 метров от любого шкафчика открываются вам на 8 секунд. Время восстановления Darkness Revealed составляет 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Deadlock.png":{"englishName":"Deadlock","owner":"Cenobite","role":"killer","descriptionEn":"Identical to No Holds Barred\n.","descriptionRu":"Идентичен «Без запретов»\n.","shortDescriptionRu":"Идентичен «Без запретов».","upcomingPatch":false},"assets/perks/iconPerks_DeadManSwitch.png":{"englishName":"Dead Man's Switch","owner":"Deathslinger","role":"killer","descriptionEn":"After hooking a Survivor, Dead Man's Switch triggers its effect:\nBlocks the first Generator\nany Survivor stops repairing for 25/30/35 seconds.\nThe Blocked Generator is highlighted to you in white.\nDead Man's Switch cannot activate if its effect is still active from a previous activation.","descriptionRu":"После захвата Выжившего срабатывает эффект Dead Man's Switch:\nБлокирует первый генератор\nлюбой Выживший прекращает ремонт на 25/30/35 секунд.\nЗаблокированный генератор выделен белым цветом.\n«Выключатель мертвеца» не может активироваться, если его эффект все еще активен после предыдущей активации.","shortDescriptionRu":"После захвата Выжившего срабатывает эффект Dead Man's Switch: Блокирует первый генератор любой Выживший прекращает ремонт на 35 секунд. Заблокированный генератор выделен белым цветом. «Выключатель мертвеца» не может активироваться, если его эффект все еще активен после предыдущей активации.","upcomingPatch":false},"assets/perks/iconPerks_Deathbound.png":{"englishName":"Deathbound","owner":"Executioner","role":"killer","descriptionEn":"Whenever a Survivor finishes healing another Survivor for the equivalent of 1 Health State\n, Deathbound activates:\nCauses the Healer to scream and reveal their location.\nCauses the Healer to suffer from the Oblivious\nStatus Effect whenever they are farther than 12/8/4 metres from the other Survivor.\nThe Healer sees the Aura\nof the Healed Survivor while Deathbound is active.\nDeathbound deactivates after the Healer loses a Health State.","descriptionRu":"Каждый раз, когда Выживший завершает лечение другого Выжившего на сумму, эквивалентную 1 состоянию здоровья.\n, Deathbound активируется:\nЗаставляет Целителя кричать и раскрывать свое местонахождение.\nЗаставляет Целителя страдать от Невнимательности\nЭффект статуса всякий раз, когда они находятся дальше, чем 12/8/4 метра от другого Выжившего.\nЦелитель видит ауру\nисцеленного выжившего, пока активен Deathbound.\nDeathbound деактивируется после того, как Целитель теряет состояние здоровья.","shortDescriptionRu":"Каждый раз, когда Выживший завершает лечение другого Выжившего на сумму, эквивалентную 1 состоянию здоровья., Deathbound активируется: Заставляет Целителя кричать и раскрывать свое местонахождение. Заставляет Целителя страдать от Невнимательности Эффект статуса всякий раз, когда они находятся дальше, чем 4 метра от другого Выжившего. Целитель видит ауру исцеленного выжившего, пока активен Deathbound.","upcomingPatch":false},"assets/perks/iconPerks_Deerstalker.png":{"englishName":"Deerstalker","owner":"Общий","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever a Survivor reads your Aura\n, Deerstalker activates for the same duration as their Aura-reading action:\nThe Aura of that Survivor is revealed to you.\nFurthermore, the following effect triggers automatically every 40/35/30 seconds:\nYour Aura is revealed for 4 seconds to the Survivor with currently the lowest cumulative Chase time.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nКаждый раз, когда Выживший читает вашу ауру\n, Deerstalker активируется на ту же длительность, что и действие чтения ауры:\nВам открывается аура этого Выжившего.\nКроме того, следующий эффект срабатывает автоматически каждые 40/35/30 секунд:\nВаша аура открывается на 4 секунды Выжившему с наименьшим совокупным временем преследования на данный момент.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Каждый раз, когда Выживший читает вашу ауру, Deerstalker активируется на ту же длительность, что и действие чтения ауры: Вам открывается аура этого Выжившего. Кроме того, следующий эффект срабатывает автоматически каждые 30 секунд: Ваша аура открывается на 4 секунды Выжившему с наименьшим совокупным временем преследования на данный момент.","upcomingPatch":true},"assets/perks/iconPerks_DevourHope.png":{"englishName":"Hex: Devour Hope","owner":"Hag","role":"killer","descriptionEn":"The false hope of Survivors ignites your hunger.\"\nHex: Devour Hope lights a Hex Totem\nat the start of the Trial, cursing Survivors with its Hex Effects.\nWhenever a Survivor is unhooked at least 24 metres from your location, Hex: Devour Hope gains +1 Token, up to a maximum of 5 Tokens:\nAt 2 Tokens: 10 seconds after hooking a Survivor, you are granted a 3/4/5 % Haste\nStatus Effect for 10 seconds.\nAt 3 Tokens: Afflicts all Survivors with the Exposed\nStatus Effect.\nAt 5 Tokens: Unlocks the Kill ability, allowing you to kill dying Survivors by your own hands.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Ложная надежда Выживших разжигает ваш голод».\nСглаз: Пожирание Надежды зажигает тотем сглаза.\nв начале Испытания, проклиная Выживших своими проклятиями.\nКаждый раз, когда Выживший отцепляется на расстоянии не менее 24 метров от вашего местоположения, Hex: Devour Hope получает +1 жетон, максимум до 5 жетонов:\nПри наличии 2 жетонов: через 10 секунд после того, как вы зацепили выжившего, вам предоставляется скорость 3/4/5%.\nСтатусный эффект на 10 секунд.\nПри 3 жетонах: поражает всех выживших уязвимостью.\nЭффект статуса.\nПри 5 жетонах: открывает способность «Убийство», позволяющую убивать умирающих выживших собственными руками.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Ложная надежда Выживших разжигает ваш голод». Сглаз: Пожирание Надежды зажигает тотем сглаза. в начале Испытания, проклиная Выживших своими проклятиями.","upcomingPatch":false},"assets/perks/iconPerks_Discordance.png":{"englishName":"Discordance","owner":"Frank, Julie, Susie, Joey","role":"killer","descriptionEn":"Any Generator\nwithin a range of 64/96/128 metres that is being repaired by 2 or more Survivors is marked by a yellow Aura\n.\nWhen the Generator is first highlighted, Discordance triggers a Loud Noise Notification on the Generator.\nAfter the Generator is no longer within range or is being repaired by just 1 Survivor, the highlighted Aura will linger for another 4 seconds.","descriptionRu":"Любой генератор\nв радиусе 64/96/128 метров, ремонтируемый 2 или более Выжившими, отмечен желтой Аурой\n.\nКогда Генератор впервые подсвечивается, Discordance запускает уведомление о громком шуме на Генераторе.\nПосле того, как Генератор больше не находится в пределах досягаемости или его ремонтирует только 1 Выживший, подсвеченная Аура будет сохраняться еще на 4 секунды.","shortDescriptionRu":"Любой генератор в радиусе 128 метров, ремонтируемый 2 или более Выжившими, отмечен желтой Аурой. Когда Генератор впервые подсвечивается, Discordance запускает уведомление о громком шуме на Генераторе. После того, как Генератор больше не находится в пределах досягаемости или его ремонтирует только 1 Выживший, подсвеченная Аура будет сохраняться еще на 4 секунды.","upcomingPatch":false},"assets/perks/iconPerks_Dissolution.png":{"englishName":"Dissolution","owner":"Dredge","role":"killer","descriptionEn":"After 3 seconds of injuring a Survivor by any means, Dissolution activates for 12/16/20 seconds:\nInstantly breaks the next Pallet\nthat Survivor performs a Fast Vault across while inside your Terror Radius\n.","descriptionRu":"После 3 секунд ранения Выжившего любым способом Растворение активируется на 12/16/20 секунд:\nМгновенно ломает следующий поддон\nчто Выживший выполняет быстрый прыжок, находясь внутри вашего радиуса террора\n.","shortDescriptionRu":"После 3 секунд ранения Выжившего любым способом Растворение активируется на 20 секунд: Мгновенно ломает следующий поддон что Выживший выполняет быстрый прыжок, находясь внутри вашего радиуса террора.","upcomingPatch":false},"assets/perks/iconPerks_Distressing.png":{"englishName":"Distressing","owner":"Общий","role":"killer","descriptionEn":"You benefit from the following permanent effect:\nIncreases your Terror Radius\nby 20/25/30 %.","descriptionRu":"Вы получаете следующий постоянный эффект:\nУвеличивает ваш радиус террора\nна 20/25/30 %.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Увеличивает ваш радиус террора на 30%.","upcomingPatch":false},"assets/perks/iconPerks_Dominance.png":{"englishName":"Dominance","owner":"Dark Lord","role":"killer","descriptionEn":"The power you wield over the land strikes terror in the hearts of all who cross your path.\nThe first time each Chest\nand each Totem\nare interacted with by a Survivor, Dominance triggers its effect:\nCalls upon The Entity\nto block it for 8/12/16 seconds.\nThe Aura\nof the blocked Prop is revealed to you in white.","descriptionRu":"Власть, которой вы обладаете над этой землей, вселяет ужас в сердца всех, кто встречается на вашем пути.\nПервый раз каждый сундук\nи каждый тотем\nвзаимодействуют с Выжившим, эффект Доминирования срабатывает:\nПризывает Сущность\nчтобы заблокировать его на 8/12/16 секунд.\nАура\nзаблокированного объекта отображается белым цветом.","shortDescriptionRu":"Власть, которой вы обладаете над этой землей, вселяет ужас в сердца всех, кто встречается на вашем пути. Первый раз каждый сундук и каждый тотем взаимодействуют с Выжившим, эффект Доминирования срабатывает: Призывает Сущность чтобы заблокировать его на 16 секунд. Аура заблокированного объекта отображается белым цветом.","upcomingPatch":false},"assets/perks/iconPerks_DragonsGrip.png":{"englishName":"Dragon's Grip","owner":"Blight","role":"killer","descriptionEn":"After performing the Damage Generator action on a Generator\n, Dragon's Grip activates for 30 seconds.\nWhile active, the first Survivor interacting with that Generator suffers from the following effects:\nCauses them to scream and reveal their location for 4 seconds.\nInflicts the Exposed\nStatus Effect for 60 seconds.\nDragon's Grip has a cool-down of 60/45/30 seconds.","descriptionRu":"После выполнения действия «Генератор урона» на Генераторе\n, «Хватка дракона» активируется на 30 секунд.\nПока он активен, первый Выживший, взаимодействующий с этим Генератором, страдает от следующих эффектов:\nЗаставляет их кричать и раскрывать свое местоположение в течение 4 секунд.\nНаносит уязвимость\nСтатусный эффект на 60 секунд.\nВремя восстановления «Хватки дракона» составляет 60/45/30 секунд.","shortDescriptionRu":"После выполнения действия «Генератор урона» на Генераторе, «Хватка дракона» активируется на 30 секунд. Пока он активен, первый Выживший, взаимодействующий с этим Генератором, страдает от следующих эффектов: Заставляет их кричать и раскрывать свое местоположение в течение 4 секунд. Наносит уязвимость Статусный эффект на 60 секунд.","upcomingPatch":false},"assets/perks/iconPerks_DyingLight.png":{"englishName":"Dying Light","owner":"Shape","role":"killer","descriptionEn":"Identical to Cull the Weak\n.","descriptionRu":"Идентичен «Отбраковке слабых»\n.","shortDescriptionRu":"Идентичен «Отбраковке слабых».","upcomingPatch":false},"assets/perks/iconPerks_Enduring.png":{"englishName":"Enduring","owner":"Hillbilly","role":"killer","descriptionEn":"You benefit from the following effect:\nReduces the duration of Pallet Stuns by 40/45/50 %.\nThis effect does not apply when stunned while carrying a Survivor.","descriptionRu":"Вы получаете следующий эффект:\nУменьшает длительность оглушения поддонов на 40/45/50%.\nЭтот эффект не применяется при оглушении, когда вы несете выжившего.","shortDescriptionRu":"Вы получаете следующий эффект: Уменьшает длительность оглушения поддонов на 50%. Этот эффект не применяется при оглушении, когда вы несете выжившего.","upcomingPatch":false},"assets/perks/iconPerks_Eruption.png":{"englishName":"Eruption","owner":"Nemesis T-Type","role":"killer","descriptionEn":"Performing the Damage Generator action on Generators\nhighlights their Auras\nin yellow.\nWhenever a Survivor enters the Dying State\nby any means, Eruption triggers the following effects on all highlighted Generators:\nCauses them to explode, damaging them.\nInstantly regresses them by -10 % of their total Progression.\nCauses them to start regressing afterwards.\nCauses all Survivors currently repairing them to suffer from the following effects:\nCauses them to scream.\nTheir Auras are revealed to you for 8/10/12 seconds.\nEruption has a cool-down of 30 seconds after triggering its effects, which also resets the highlighted Auras.","descriptionRu":"Выполнение действия «Генератор урона» на генераторах\nподчеркивает их ауру\nв желтом цвете.\nВсякий раз, когда Выживший входит в Состояние Умирания\nлюбым способом Извержение вызывает следующие эффекты на всех выделенных Генераторах:\nЗаставляет их взрываться, нанося им урон.\nМгновенно регрессирует их на -10 % от их общего прогресса.\nЗаставляет их впоследствии начать регрессировать.\nЗаставляет всех Выживших, которые в данный момент их ремонтируют, страдать от следующих эффектов:\nЗаставляет их кричать.\nИх ауры открываются вам на 8/10/12 секунд.\nВремя восстановления «Извержения» составляет 30 секунд после срабатывания его эффектов, что также сбрасывает выделенные ауры.","shortDescriptionRu":"Выполнение действия «Генератор урона» на генераторах подчеркивает их ауру в желтом цвете. Всякий раз, когда Выживший входит в Состояние Умирания любым способом Извержение вызывает следующие эффекты на всех выделенных Генераторах: Заставляет их взрываться, нанося им урон. Мгновенно регрессирует их на -10% от их общего прогресса.","upcomingPatch":false},"assets/perks/iconPerks_FireUp.png":{"englishName":"Fire Up","owner":"Nightmare","role":"killer","descriptionEn":"The increased pressure of losing your preys fills you with anger and gives you unsuspected motivation.\nFor each completed Generator, Fire Up gains +1 Token, up to a maximum of 5 Tokens:\nIncreases the Action speeds for the following interactions by a stack-able 6/7/8 % per Token, up to a maximum of 30/35/40 %:\nPicking up and dropping Survivors.\nBreaking Breakable Walls\nand dropped Pallets\n.\nDamaging Generators\n.\nVaulting Windows\n.","descriptionRu":"Повышенное давление потери жертв наполняет вас гневом и дает неожиданную мотивацию.\nЗа каждый завершенный Генератор Fire Up получает +1 жетон, максимум до 5 жетонов:\nУвеличивает скорость действий для следующих взаимодействий на суммируемую 6/7/8 % за каждый жетон, максимум до 30/35/40 %:\nПодбор и сброс выживших.\nРазрушение хрупких стен\nи бросил поддоны\n.\nПовреждающие генераторы\n.\nСводчатые окна\n.","shortDescriptionRu":"Повышенное давление потери жертв наполняет вас гневом и дает неожиданную мотивацию. За каждый завершенный Генератор Fire Up получает +1 жетон, максимум до 5 жетонов: Увеличивает скорость действий для следующих взаимодействий на суммируемую 8% за каждый жетон, максимум до 40%: Подбор и сброс выживших. Разрушение хрупких стен и бросил поддоны.","upcomingPatch":true},"assets/perks/iconPerks_FloodOfRage.png":{"englishName":"Scourge Hook: Floods of Rage","owner":"Onry%C5%8D","role":"killer","descriptionEn":"At the start of the Trial, 4 Hooks in the environment are changed into Scourge Hooks:\nThe Auras\nof these Scourge Hooks are highlighted in white.\nEach time a Survivor is unhooked from a Scourge Hook, the following effects apply:\nThe Auras of all other Survivors are revealed for 5/6/7 seconds.","descriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети:\nАуры\nиз этих Крюков Плети выделены белым цветом.\nКаждый раз, когда Выжившего отцепляют от Крюка Плети, применяются следующие эффекты:\nАуры всех остальных Выживших раскрываются на 5/6/7 секунд.","shortDescriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети: Ауры из этих Крюков Плети выделены белым цветом. Каждый раз, когда Выжившего отцепляют от Крюка Плети, применяются следующие эффекты: Ауры всех остальных Выживших раскрываются на 7 секунд.","upcomingPatch":false},"assets/perks/IconPerks_ForcedHesitation.png":{"englishName":"Forced Hesitation","owner":"Singularity","role":"killer","descriptionEn":"Whenever a Survivor is put into the Dying State\nby any means, Forced Hesitation triggers its effect:\nCauses all other Survivors within 16 metres of them suffer from a -20 % Hindered\nStatus Effect for 10 seconds.\nForced Hesitation has a cool-down of 40/35/30 seconds.","descriptionRu":"Всякий раз, когда Выживший попадает в состояние умирания\nлюбым способом Вынужденное Колебание срабатывает:\nВсе остальные Выжившие в радиусе 16 метров от них получают -20 % затруднений.\nСтатусный эффект на 10 секунд.\nПринудительное колебание имеет время восстановления 40/35/30 секунд.","shortDescriptionRu":"Всякий раз, когда Выживший попадает в состояние умирания любым способом Вынужденное Колебание срабатывает: Все остальные Выжившие в радиусе 16 метров от них получают -20% затруднений. Статусный эффект на 10 секунд. Принудительное колебание имеет время восстановления 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_ForcedPenance.png":{"englishName":"Forced Penance","owner":"Executioner","role":"killer","descriptionEn":"Whenever a Survivor triggers a Protection Hit, they suffer from the following effect:\nInflicts the Broken\nStatus Effect for 60/70/80 seconds.","descriptionRu":"Каждый раз, когда Выживший активирует Защитный удар, он страдает от следующего эффекта:\nНаносит сломанный\nСтатусный эффект на 60/70/80 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший активирует Защитный удар, он страдает от следующего эффекта: Наносит сломанный Статусный эффект на 80 секунд.","upcomingPatch":false},"assets/perks/iconPerks_FranklinsLoss.png":{"englishName":"Franklin's Demise","owner":"Cannibal","role":"killer","descriptionEn":"Survivors hit with your vicious Basic Attack drop any equipped Item\non impact:\nThe Auras\nof lost Items are revealed to within 32/48/64 metres.","descriptionRu":"Выжившие, пораженные вашей жестокой базовой атакой, бросают любой экипированный предмет.\nпо воздействию:\nАуры\nпотерянных предметов обнаруживаются с точностью до 32/48/64 метров.","shortDescriptionRu":"Выжившие, пораженные вашей жестокой базовой атакой, бросают любой экипированный предмет. по воздействию: Ауры потерянных предметов обнаруживаются с точностью до 64 метров.","upcomingPatch":false},"assets/perks/iconPerks_friendsTillTheEnd.png":{"englishName":"Friends 'til the End","owner":"Charles Lee Ray","role":"killer","descriptionEn":"When you hook any Survivors that is not the Obsession\n, the following effects apply to the Obsession:\nTheir Aura\nis revealed for 6/8/10 seconds.\nThey suffer from the Exposed\nStatus Effect for 20 seconds.\nWhen you hook the Obsession, the following effects apply to a random Survivor:\nCauses the Survivor to scream and reveal their location to the Killer.\nThey become the new Obsession.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Когда вы цепляете любого Выжившего, кроме Одержимости\n, к Одержимости применяются следующие эффекты:\nИх аура\nраскрывается на 6/8/10 секунд.\nОни страдают от воздействия\nСтатусный эффект на 20 секунд.\nКогда вы подключаете Одержимость, к случайному Выжившему применяются следующие эффекты:\nЗаставляет Выжившего кричать и раскрывать Убийце свое местонахождение.\nОни становятся новой одержимостью.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Когда вы цепляете любого Выжившего, кроме Одержимости, к Одержимости применяются следующие эффекты: Их аура раскрывается на 10 секунд. Они страдают от воздействия Статусный эффект на 20 секунд. Когда вы подключаете Одержимость, к случайному Выжившему применяются следующие эффекты: Заставляет Выжившего кричать и раскрывать Убийце свое местонахождение.","upcomingPatch":false},"assets/perks/iconPerks_FurtiveChase.png":{"englishName":"Furtive Chase","owner":"Danny Johnson","role":"killer","descriptionEn":"After hooking the Obsession\n, you benefit from the following effects for 14/16/18 seconds:\nGrants the Undetectable\nStatus Effect.\nGrants a +10 % Haste\nStatus Effect.\nWhenever the Obsession is unhooked by another Survivor, the Obsession Status transfers to their Rescuer.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"После подключения Obsession\n, вы получаете следующие эффекты в течение 14/16/18 секунд:\nДарует необнаружимое\nЭффект статуса.\nДает +10 % скорости.\nЭффект статуса.\nКаждый раз, когда другой Выживший отцепляет Одержимость, статус Одержимости передается его Спасателю.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"После подключения Obsession, вы получаете следующие эффекты в течение 18 секунд: Дарует необнаружимое Эффект статуса. Дает +10% скорости. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_GameAfoot.png":{"englishName":"Game Afoot","owner":"Skull Merchant","role":"killer","descriptionEn":"Whenever you hit the Survivor with currently the highest cumulative Chase time with a Basic Attack, Game Afoot triggers its primary effect:\nCauses the Obsession Status to transfer to that Survivor.\nWhile chasing the Obsession\n, performing the Break or Damage action causes Game Afoot to trigger its secondary effect:\nGrants a +10 % Haste\nStatus Effect for 8/9/10 seconds.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Каждый раз, когда вы поражаете Выжившего с самым высоким на данный момент совокупным временем преследования базовой атакой, Game Afoot активирует свой основной эффект:\nЗаставляет Статус Одержимости передаваться этому Выжившему.\nВ погоне за одержимостью\n, выполнение действия «Разрушение» или «Повреждение» приводит к срабатыванию дополнительного эффекта Game Afoot:\nДает +10 % скорости.\nСтатусный эффект на 8/9/10 секунд.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Каждый раз, когда вы поражаете Выжившего с самым высоким на данный момент совокупным временем преследования базовой атакой, Game Afoot активирует свой основной эффект: Заставляет Статус Одержимости передаваться этому Выжившему. В погоне за одержимостью, выполнение действия «Разрушение» или «Повреждение» приводит к срабатыванию дополнительного эффекта Game Afoot: Дает +10% скорости.","upcomingPatch":true},"assets/perks/iconPerks_GearHead.png":{"englishName":"Gearhead","owner":"Deathslinger","role":"killer","descriptionEn":"After a Survivor loses a Health State\n, Gearhead activates for 30 seconds:\nWhile Gearhead is active, a Survivor\nsucceeding a Good Skill Check\nwhile repairing reveals their Aura\nto you for 6/7/8 seconds.","descriptionRu":"После того, как Выживший теряет состояние здоровья\n, Gearhead активируется на 30 секунд:\nПока Gearhead активен, Выживший\nуспешная проверка хороших навыков\nво время ремонта раскрывается их аура\nвам на 6/7/8 секунд.","shortDescriptionRu":"После того, как Выживший теряет состояние здоровья, Gearhead активируется на 30 секунд: Пока Gearhead активен, Выживший успешная проверка хороших навыков во время ремонта раскрывается их аура вам на 8 секунд.","upcomingPatch":false},"assets/perks/iconPerks_GeneratorOvercharge.png":{"englishName":"Overcharge","owner":"Doctor","role":"killer","descriptionEn":"Performing the Damage Generator action on a Generator\napplies Overcharge:\nThe next Survivor interacting with that Generator is faced with a difficult Skill Check\n.\nInstantly regresses that Generator by 2/3/4 % of its maximum possible Progression in addition to the default Progression penalty.\nAfter Overcharge is applied to a Generator, the following effect also applies:\nIncreases the Regression speed from 85 % to 130 % of its default value over the next 30 seconds.","descriptionRu":"Выполнение действия «Генератор урона» на генераторе\nприменяет переплату:\nСледующий выживший, взаимодействующий с этим генератором, сталкивается с трудной проверкой навыков.\n.\nМгновенно регрессирует этот Генератор на 2/3/4 % от его максимально возможного прогресса в дополнение к стандартному штрафу за прогресс.\nПосле применения Перезаряда к Генератору также применяется следующий эффект:\nУвеличивает скорость регрессии с 85 % до 130 % от значения по умолчанию в течение следующих 30 секунд.","shortDescriptionRu":"Выполнение действия «Генератор урона» на генераторе применяет переплату: Следующий выживший, взаимодействующий с этим генератором, сталкивается с трудной проверкой навыков.. Мгновенно регрессирует этот Генератор на 4% от его максимально возможного прогресса в дополнение к стандартному штрафу за прогресс.","upcomingPatch":false},"assets/perks/IconPerks_GeneticLimits.png":{"englishName":"Genetic Limits","owner":"Singularity","role":"killer","descriptionEn":"Whenever a Survivor loses a Health State by any means, Genetic Limits triggers its effect:\nCauses them to suffer from the Exhausted\nStatus Effect for 6/7/8 seconds.","descriptionRu":"Всякий раз, когда Выживший каким-либо образом теряет состояние здоровья, Генетические пределы срабатывают:\nЗаставляет их страдать от истощения\nСтатусный эффект на 6/7/8 секунд.","shortDescriptionRu":"Всякий раз, когда Выживший каким-либо образом теряет состояние здоровья, Генетические пределы срабатывают: Заставляет их страдать от истощения Статусный эффект на 8 секунд.","upcomingPatch":false},"assets/perks/iconPerks_HangmansTrick.png":{"englishName":"Scourge Hook: Hangman's Trick","owner":"Pig","role":"killer","descriptionEn":"At the start of the Trial, 4 Hooks in the environment are changed into Scourge Hooks:\nThe Auras\nof these Scourge Hooks are highlighted in white.\nWhile carrying a Survivor, Scourge Hook: Hangman's Trick triggers its primary effect:\nThe Auras of all Survivors within 12/14/16 metres of a Scourge Hook are revealed to you.\nWhenever a Survivor starts the Sabotage action on any Hook\n, Scourge Hook: Hangman's Trick triggers its secondary effect:\nTriggers a Loud Noise Notification at the location of that Hook.","descriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети:\nАуры\nиз этих Крюков Плети выделены белым цветом.\nКогда вы несете выжившего, «Крюк Плети: Уловка палача» активирует свой основной эффект:\nВам откроются ауры всех выживших в радиусе 12/14/16 метров от Крюка Плети.\nКаждый раз, когда Выживший начинает действие Диверсии на любом Крюке.\n, Крюк Плети: Уловка Палача вызывает дополнительный эффект:\nЗапускает уведомление о громком шуме в месте расположения этого крючка.","shortDescriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети: Ауры из этих Крюков Плети выделены белым цветом. Когда вы несете выжившего, «Крюк Плети: Уловка палача» активирует свой основной эффект: Вам откроются ауры всех выживших в радиусе 16 метров от Крюка Плети.","upcomingPatch":false},"assets/perks/iconPerks_Hatred.png":{"englishName":"Rancor","owner":"Spirit","role":"killer","descriptionEn":"Whenever a Generator\nis completed, Rancor triggers its primary effects:\nCauses all Survivors to scream and trigger a Loud Noise Notification at their current location.\nThis effect lingers for 3 seconds.\nYour Aura\nis revealed to the Obsession\nfor 5/4/3 seconds.\nOnce the Exit Gates\nare powered, Rancor additionally triggers its secondary effects on the Obsession:\nInflicts the Exposed\nStatus Effect for the remainder of the Trial.\nGrants the ability to kill them when in close proximity.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Всякий раз, когда генератор\nзавершено, Злоба активирует свои основные эффекты:\nЗаставляет всех Выживших кричать и вызывать громкий шум в их текущем местоположении.\nЭтот эффект сохраняется в течение 3 секунд.\nВаша аура\nраскрывается Одержимости\nна 5/4/3 секунды.\nОднажды Выходные Ворота\nактивны, Злоба дополнительно активирует свои вторичные эффекты на Одержимости:\nНаносит уязвимость\nЭффект статуса на оставшуюся часть Испытания.\nПредоставляет возможность убивать их, когда они находятся в непосредственной близости.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Всякий раз, когда генератор завершено, Злоба активирует свои основные эффекты: Заставляет всех Выживших кричать и вызывать громкий шум в их текущем местоположении. Этот эффект сохраняется в течение 3 секунд. Ваша аура раскрывается Одержимости на 3 секунды.","upcomingPatch":false},"assets/perks/iconPerks_HauntedGround.png":{"englishName":"Hex: Haunted Ground","owner":"Spirit","role":"killer","descriptionEn":"Hex: Haunted Ground lights 2 Hex Totems\nat the start of the Trial, laying a trap for Survivors.\nBlessing or cleansing either Hex Totem trips the trap and triggers the following effect:\nCauses all Survivors to suffer from the Exposed\nStatus Effect for 40/50/60 seconds.\nHex: Haunted Ground extinguishes the second Hex Totem after tripping its trap.\nHex: Haunted Ground is disabled for the remainder of the Trial after triggering its effect.","descriptionRu":"Hex: Призрачная земля освещает 2 Hex тотема\nв начале Испытания, устраивая ловушку для Выживших.\nБлагословение или очищение любого Hex Тотема отключит ловушку и активирует следующий эффект:\nЗаставляет всех выживших страдать от воздействия\nСтатусный эффект на 40/50/60 секунд.\nHex: Haunted Ground гасит второй Hex Тотем после срабатывания его ловушки.\n«Сглаз: Земля с привидениями» отключается до конца испытания после срабатывания его эффекта.","shortDescriptionRu":"Hex: Призрачная земля освещает 2 Hex тотема в начале Испытания, устраивая ловушку для Выживших. Благословение или очищение любого Hex Тотема отключит ловушку и активирует следующий эффект: Заставляет всех выживших страдать от воздействия Статусный эффект на 60 секунд. Hex: Haunted Ground гасит второй Hex Тотем после срабатывания его ловушки.","upcomingPatch":false},"assets/perks/iconPerks_HexBloodFavor.png":{"englishName":"Hex: Blood Favour","owner":"Blight","role":"killer","descriptionEn":"Hex: Blood Favour lights a Hex Totem\nat the start of the Trial, cursing Survivors with its Hex Effects.\nWhenever a Survivor loses a Health State\nby any means, Hex: Blood Favour triggers its effect for 15 seconds:\nBlocks all upright Pallets\nwithin 24/28/32 metres of that Survivor.\nBlocked Pallets cannot be dropped by any Survivor.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Сглаз: Благосклонность крови зажигает тотем сглаза.\nв начале Испытания, проклиная Выживших своими проклятиями.\nКаждый раз, когда Выживший теряет состояние здоровья\nлюбым способом, Hex: Blood Favor срабатывает на 15 секунд:\nБлокирует все вертикальные поддоны\nв пределах 24/28/32 метров от Выжившего.\nЗаблокированные поддоны не может сбросить ни один Выживший.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Сглаз: Благосклонность крови зажигает тотем сглаза. в начале Испытания, проклиная Выживших своими проклятиями. Каждый раз, когда Выживший теряет состояние здоровья любым способом, Hex: Blood Favor срабатывает на 15 секунд: Блокирует все вертикальные поддоны в пределах 32 метров от Выжившего.","upcomingPatch":false},"assets/perks/iconPerks_HexCrowdControl.png":{"englishName":"Hex: Crowd Control","owner":"Trickster","role":"killer","descriptionEn":"Whenever a Survivors performs a Rushed Vault action at a Window\n, Hex: Crowd Control activates on a random Totem and triggers its effect:\nBlocks that Window for all Survivors.\nIncreases basic-vault speed of blocked Windows by 15 %\nReveals auras of blocked Windows within 24 metres\nHex: Crowd Control has a limit of 4/5/6 Windows it can affect at a time.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Каждый раз, когда Выживший выполняет действие «Срочное хранилище» у окна.\n, Hex: Контроль толпы активируется на случайном тотеме и вызывает его эффект:\nБлокирует это окно для всех выживших.\nУвеличивает скорость работы заблокированного Windows в базовом хранилище на 15 %.\nОбнаруживает ауры заблокированных окон в радиусе 24 метров.\nHex: Crowd Control имеет ограничение в 4/5/6 Windows, на которое он может повлиять одновременно.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Каждый раз, когда Выживший выполняет действие «Срочное хранилище» у окна., Hex: Контроль толпы активируется на случайном тотеме и вызывает его эффект: Блокирует это окно для всех выживших. Увеличивает скорость работы заблокированного Windows в базовом хранилище на 15%. Обнаруживает ауры заблокированных окон в радиусе 24 метров.","upcomingPatch":false},"assets/perks/iconPerks_HexFaceTheDarkness.png":{"englishName":"Hex: Face the Darkness","owner":"Knight","role":"killer","descriptionEn":"If there is still a Dull Totem\nin the environment, Hex: Face the Darkness lights a Hex Totem\nafter injuring a Survivor by any means, cursing them with its Hex Effects.\nWhile cursed, the following effects trigger once every 35/30/25 seconds on all other Survivors outside of the Terror Radius\n:\nCauses them to scream.\nTheir Auras\nare revealed to you for 2 seconds.\nHex: Face the Darkness is deactivated once the Cursed Survivor either returns to Healthy\nor enters the Dying State\nby any means, extinguishing the Hex Totem.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Если еще есть Тусклый Тотем\nв окружающей среде Hex: Face the Darkness зажигает Hex Тотем\nпосле того, как каким-либо образом ранил Выжившего, проклял его своими порчей.\nВо время проклятия следующие эффекты срабатывают раз в 35/30/25 секунд на всех остальных Выживших за пределами Радиуса Ужаса.\n:\nЗаставляет их кричать.\nИх ауры\nоткрываются вам на 2 секунды.\nПорча: Лицом к тьме деактивируется, как только проклятый выживший возвращается в состояние здоровья.\nили входит в состояние умирания\nлюбыми способами погасить Проклятый Тотем.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Если еще есть Тусклый Тотем в окружающей среде Hex: Face the Darkness зажигает Hex Тотем после того, как каким-либо образом ранил Выжившего, проклял его своими порчей. Во время проклятия следующие эффекты срабатывают раз в 25 секунд на всех остальных Выживших за пределами Радиуса Ужаса.: Заставляет их кричать. Их ауры открываются вам на 2 секунды.","upcomingPatch":false},"assets/perks/iconPerks_HexPlaything.png":{"englishName":"Hex: Plaything","owner":"Cenobite","role":"killer","descriptionEn":"Identical to Hex: Fortune's Fool\n.","descriptionRu":"Идентичен Hex: Дурак Фортуны\n.","shortDescriptionRu":"Идентичен Hex: Дурак Фортуны.","upcomingPatch":false},"assets/perks/iconPerks_HexRetribution.png":{"englishName":"Hex: Retribution","owner":"Deathslinger","role":"killer","descriptionEn":"Those who cross you will be punished.\"\nWhenever a Survivor blesses or cleanses a Totem\n, Hex: Retribution triggers its primary effect:\nCauses that Survivor to suffer from the Oblivious\nStatus Effect for 40/50/60 seconds.\nWhenever a Hex Totem is removed by any means, including its own, Hex: Retribution triggers its secondary effect:\nThe Auras\nof all Survivors are revealed to you for 20 seconds.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Те, кто перейдет вам дорогу, будут наказаны».\nКаждый раз, когда Выживший благословляет или очищает Тотем\n, Hex: Возмездие активирует свой основной эффект:\nПричины, по которым Выживший страдает от Невнимательности\nСтатусный эффект на 40/50/60 секунд.\nКаждый раз, когда Проклятый тотем удаляется любым способом, в том числе и собственным, «Сглаз: Возмездие» активирует свой вторичный эффект:\nАуры\nвсех Выживших открываются вам в течение 20 секунд.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Те, кто перейдет вам дорогу, будут наказаны». Каждый раз, когда Выживший благословляет или очищает Тотем, Hex: Возмездие активирует свой основной эффект: Причины, по которым Выживший страдает от Невнимательности Статусный эффект на 60 секунд.","upcomingPatch":false},"assets/perks/iconPerks_HexUndying.png":{"englishName":"Hex: Undying","owner":"Blight","role":"killer","descriptionEn":"Whenever a Survivor is within 2/3/4 metres of a Dull Totem\n, Hex: Undying triggers its primary effect:\nTheir Aura\nis revealed to you for as long as they remain in that range.\nWhenever a Hex Totem\nis cleansed, Hex: Undying triggers its secondary effect:\nTransfers the cleansed Hex to the Hex Totem associated with Hex: Undying instead, replacing it.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Каждый раз, когда Выживший находится в пределах 2/3/4 метров от Тусклого Тотема.\n, Hex: Бессмертие активирует свой основной эффект:\nИх аура\nоткрывается вам до тех пор, пока они остаются в этом диапазоне.\nВсякий раз, когда Шестигранный тотем\nочищается, Hex: Undying активирует свой вторичный эффект:\nВместо этого переносит очищенное порчу в тотем порчи, связанный с \"Сглазом: Бессмертие\", заменяя его.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Каждый раз, когда Выживший находится в пределах 4 метров от Тусклого Тотема., Hex: Бессмертие активирует свой основной эффект: Их аура открывается вам до тех пор, пока они остаются в этом диапазоне. Всякий раз, когда Шестигранный тотем очищается, Hex: Undying активирует свой вторичный эффект: Вместо этого переносит очищенное порчу в тотем порчи, связанный с \"Сглазом: Бессмертие\", заменяя его.","upcomingPatch":false},"assets/perks/iconPerks_HexWretchedFate.png":{"englishName":"Hex: Wretched Fate","owner":"Dark Lord","role":"killer","descriptionEn":"You see your victim from afar and resolve to prolong their suffering.\nAfter a Generator\nis completed, Hex: Wretched Fate activates and lights a random Dull Totem\n, cursing the Obsession\n:\nReduces their Repair speed by 27/30/33 %.\nThe Aura\nof the Hex Totem is revealed to them within 12 metres.","descriptionRu":"Вы видите свою жертву издалека и решаете продлить ее страдания.\nПосле генератора\nзавершено, активируется Hex: Wretched Fate и зажигается случайный Тусклый тотем.\n, проклиная Одержимость\n:\nСнижает скорость ремонта на 27/30/33%.\nАура\nШестнадцатеричного Тотема открывается им в радиусе 12 метров.","shortDescriptionRu":"Вы видите свою жертву издалека и решаете продлить ее страдания. После генератора завершено, активируется Hex: Wretched Fate и зажигается случайный Тусклый тотем., проклиная Одержимость: Снижает скорость ремонта на 33%. Аура Шестнадцатеричного Тотема открывается им в радиусе 12 метров.","upcomingPatch":false},"assets/perks/iconPerks_Hoarder.png":{"englishName":"Hoarder","owner":"Twins","role":"killer","descriptionEn":"You protect what little you have and are perceptive to those rummaging through your stockpiles.\nHoarder triggers a Loud Noise Notification for 4 seconds, whenever a Survivor performs any of the following actions within 32/48/64 metres of your location:\nUnlocks a Chest\n.\nPicks up any Item\n.\nHoarder spawns 2 additional Chests in the Trial.","descriptionRu":"Вы защищаете то немногое, что у вас есть, и восприимчивы к тем, кто роется в ваших запасах.\nХоардер активирует громкое уведомление на 4 секунды каждый раз, когда Выживший выполняет любое из следующих действий в пределах 32/48/64 метров от вашего местоположения:\nОткрывает сундук\n.\nБерет любой предмет\n.\nВ Испытании Хоардер создает 2 дополнительных сундука.","shortDescriptionRu":"Вы защищаете то немногое, что у вас есть, и восприимчивы к тем, кто роется в ваших запасах. Хоардер активирует громкое уведомление на 4 секунды каждый раз, когда Выживший выполняет любое из следующих действий в пределах 64 метров от вашего местоположения: Открывает сундук. Берет любой предмет.","upcomingPatch":false},"assets/perks/iconPerks_Hubris.png":{"englishName":"Hubris","owner":"Knight","role":"killer","descriptionEn":"Whenever a Survivor stuns you by any means, Hubris triggers its effect:\nCauses them to suffer from the Exposed\nStatus Effect for 20/25/30 seconds.\nHubris has a cool-down of 20 seconds.","descriptionRu":"Каждый раз, когда Выживший каким-либо образом оглушает вас, Гордыня активирует свой эффект:\nЗаставляет их страдать от воздействия\nСтатусный эффект на 20/25/30 секунд.\nУ высокомерия время восстановления составляет 20 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший каким-либо образом оглушает вас, Гордыня активирует свой эффект: Заставляет их страдать от воздействия Статусный эффект на 30 секунд. У высокомерия время восстановления составляет 20 секунд.","upcomingPatch":false},"assets/perks/iconPerks_HumanGreed.png":{"englishName":"Human Greed","owner":"Dark Lord","role":"killer","descriptionEn":"One can always rely on the avarice of the living and use it to one's advantage.\nGrants the ability to kick opened Chests\nand close them.\nThe Auras\nof unopened Chests are revealed to you at all times.\nThe Auras of Survivors coming within 8 metres of unopened or closed Chests are revealed to you for 3/4/5 seconds.\nHuman Greed has a cool-down of 10 seconds on the ability to kick Chests.","descriptionRu":"Всегда можно положиться на алчность живых и использовать ее в своих целях.\nПредоставляет возможность пинать открытые сундуки.\nи закройте их.\nАуры\nнеоткрытых сундуков вам постоянно открываются.\nАуры Выживших, оказавшихся в радиусе 8 метров от неоткрытых или закрытых Сундуков, открываются вам на 3/4/5 секунды.\nЧеловеческая жадность имеет время восстановления 10 секунд для способности пинать сундуки.","shortDescriptionRu":"Всегда можно положиться на алчность живых и использовать ее в своих целях. Предоставляет возможность пинать открытые сундуки. и закройте их.","upcomingPatch":false},"assets/perks/iconPerks_HuntressLullaby.png":{"englishName":"Hex: Huntress Lullaby","owner":"Huntress","role":"killer","descriptionEn":"Your hunt is an irresistible song of dread which muddles your prey's attention.\"\nSurvivors performing Healing or Repairing actions suffer from the following effect:\nIncreases the Progression penalty for Failed Skill Checks by 2/4/6 %.\nEach time a Survivor is hooked, Hex: Huntress Lullaby grows in power and gains +1 Token, up to a maximum of 5 Tokens.\nSurvivors performing Healing or Repairing actions suffer from the following additional effect:\nReduces the time between the audio cue announcing an imminent Skill Check and it appearing, depending on the number of accumulated Tokens:\n1 Token: -14 %\n2 Tokens: -28 %\n3 Tokens: -42 %\n4 Tokens: -56 %\n5 Tokens: Suppresses the audio cue altogether.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Ваша охота — это непреодолимая песня страха, которая сбивает с толку внимание вашей жертвы».\nВыжившие, выполняющие действия Исцеления или Ремонта, страдают от следующего эффекта:\nУвеличивает штраф за прогресс при неудачных проверках навыков на 2/4/6%.\nКаждый раз, когда Выживший попадает на крючок, сила «Сглаза: Колыбельная Охотницы» увеличивается и он получает +1 жетон, максимум до 5 жетонов.\nВыжившие, выполняющие действия «Исцеление» или «Ремонт», страдают от следующего дополнительного эффекта:\nСокращает время между звуковым сигналом, объявляющим о предстоящей проверке навыков, и ее появлением, в зависимости от количества накопленных жетонов:\n1 жетон: -14 %\n2 жетона: -28 %\n3 жетона: -42 %\n4 жетона: -56 %\n5 жетонов: полностью подавляет звуковой сигнал.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Ваша охота — это непреодолимая песня страха, которая сбивает с толку внимание вашей жертвы». Выжившие, выполняющие действия Исцеления или Ремонта, страдают от следующего эффекта: Увеличивает штраф за прогресс при неудачных проверках навыков на 6%. Каждый раз, когда Выживший попадает на крючок, сила «Сглаза: Колыбельная Охотницы» увеличивается и он получает +1 жетон, максимум до 5 жетонов.","upcomingPatch":false},"assets/perks/iconPerks_Hysteria.png":{"englishName":"Hysteria","owner":"Nemesis T-Type","role":"killer","descriptionEn":"Whenever you injure a healthy Survivor, Hysteria triggers its effect:\nCauses all Survivors currently in the Injured State\nto suffer from the Oblivious\nStatus Effect for 30/35/40 seconds.\nThis effect also applies the Survivor triggering it.\nHysteria has a cool-down of 20 seconds.","descriptionRu":"Каждый раз, когда вы раните здорового Выжившего, Истерия срабатывает:\nВызывает у всех выживших, находящихся в настоящее время в раненом состоянии.\nстрадать от невнимательности\nСтатусный эффект на 30/35/40 секунд.\nЭтот эффект также применяется к Выжившему, вызвавшему его.\nИстерия имеет время восстановления 20 секунд.","shortDescriptionRu":"Каждый раз, когда вы раните здорового Выжившего, Истерия срабатывает: Вызывает у всех выживших, находящихся в настоящее время в раненом состоянии. страдать от невнимательности Статусный эффект на 40 секунд. Этот эффект также применяется к Выжившему, вызвавшему его.","upcomingPatch":false},"assets/perks/iconPerks_ImAllEars.png":{"englishName":"I'm All Ears","owner":"Danny Johnson","role":"killer","descriptionEn":".\"\nWhenever a Survivor performs a Rushed Vault action within 48 metres of your location, you benefit from the following effect:\nThe Aura\nof the Survivor is revealed to you for 8 seconds.\nI'm All Ears has a cool-down of 60/45/30 seconds.","descriptionRu":".\"\nКаждый раз, когда Выживший выполняет действие «Быстрое хранилище» в пределах 48 метров от вашего местоположения, вы получаете следующий эффект:\nАура\nВыжившего открывается вам на 8 секунд.\nВремя восстановления способности «Я весь в ушах» составляет 60/45/30 секунд.","shortDescriptionRu":".\" Каждый раз, когда Выживший выполняет действие «Быстрое хранилище» в пределах 48 метров от вашего местоположения, вы получаете следующий эффект: Аура Выжившего открывается вам на 8 секунд. Время восстановления способности «Я весь в ушах» составляет 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_InfectiousFright.png":{"englishName":"Infectious Fright","owner":"Plague","role":"killer","descriptionEn":"Whenever a Survivor is put into the Dying State\nby any means, all other Survivors within your Terror Radius\nwill scream and reveal their current location to you for 4/5/6 seconds.","descriptionRu":"Всякий раз, когда Выживший попадает в состояние умирания\nлюбыми способами, всем остальным Выжившим в пределах вашего Радиуса Террора.\nбудет кричать и показывать вам свое текущее местоположение на 4/5/6 секунд.","shortDescriptionRu":"Всякий раз, когда Выживший попадает в состояние умирания любыми способами, всем остальным Выжившим в пределах вашего Радиуса Террора. будет кричать и показывать вам свое текущее местоположение на 6 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Insidious.png":{"englishName":"Insidious","owner":"Общий","role":"killer","descriptionEn":"Unlocks the stealth ability.\nAfter standing still for 3/2/1 second(s), Insidious activates for as long as you remain stationary:\nGrants the Undetectable\nStatus Effect.\nInsidious deactivates once you start moving again.","descriptionRu":"Открывает способность скрытности.\nПосле простоя на месте в течение 3/2/1 секунды Коварство активируется до тех пор, пока вы остаетесь неподвижным:\nДарует необнаружимое\nЭффект статуса.\nКоварство деактивируется, как только вы снова начинаете двигаться.","shortDescriptionRu":"Открывает способность скрытности. После простоя на месте в течение 1 секунды Коварство активируется до тех пор, пока вы остаетесь неподвижным: Дарует необнаружимое Эффект статуса. Коварство деактивируется, как только вы снова начинаете двигаться.","upcomingPatch":false},"assets/perks/iconPerks_IronGrasp.png":{"englishName":"Iron Grasp","owner":"Общий","role":"killer","descriptionEn":"While carrying a Survivor, they suffer from the following effects:\nReduces the strength of the Involuntary Strafing caused by their wiggling by -75 %.\nIncreases the time required to break free from your grasp by 10/11/12 %.","descriptionRu":"При переноске Выжившего на него воздействуют следующие эффекты:\nСнижает силу непроизвольного обстрела, вызванного их покачиванием, на -75 %.\nУвеличивает время, необходимое для того, чтобы вырваться из вашей хватки, на 10/11/12%.","shortDescriptionRu":"При переноске Выжившего на него воздействуют следующие эффекты: Снижает силу непроизвольного обстрела, вызванного их покачиванием, на -75%. Увеличивает время, необходимое для того, чтобы вырваться из вашей хватки, на 12%.","upcomingPatch":true},"assets/perks/iconPerks_IronMaiden.png":{"englishName":"Iron Maiden","owner":"Frank, Julie, Susie, Joey","role":"killer","descriptionEn":"While interacting with an empty Locker\n, Iron Maiden applies its primary effect:\nIncreases your Search speed by 30/40/50 %.\nWhenever a Survivor exits a Locker, Iron Maiden triggers its secondary effects:\nCauses them to scream and trigger a Loud Noise Notification at their current location.\nThis effect lingers for 4 seconds.\nCauses them to suffer from the Exposed\nStatus Effect for 30 seconds.","descriptionRu":"При взаимодействии с пустым шкафчиком\n, Iron Maiden применяет свой основной эффект:\nУвеличивает скорость поиска на 30/40/50%.\nКаждый раз, когда Выживший выходит из шкафчика, Iron Maiden активирует свои вторичные эффекты:\nЗаставляет их кричать и вызывать громкое уведомление в их текущем местоположении.\nЭтот эффект сохраняется в течение 4 секунд.\nЗаставляет их страдать от воздействия\nСтатусный эффект на 30 секунд.","shortDescriptionRu":"При взаимодействии с пустым шкафчиком, Iron Maiden применяет свой основной эффект: Увеличивает скорость поиска на 50%. Каждый раз, когда Выживший выходит из шкафчика, Iron Maiden активирует свои вторичные эффекты: Заставляет их кричать и вызывать громкое уведомление в их текущем местоположении. Этот эффект сохраняется в течение 4 секунд.","upcomingPatch":false},"assets/perks/iconPerks_KnockOut.png":{"englishName":"Knock Out","owner":"Cannibal","role":"killer","descriptionEn":"Whenever a Survivor moves farther than 6 metres from a Pallet\nwithin 6 seconds of dropping it, Knock Out triggers its effect:\nCauses them to suffer from a -5 % Hindered\nStatus Effect for 3/4/5 seconds.","descriptionRu":"Каждый раз, когда Выживший отходит дальше, чем на 6 метров от поддона.\nв течение 6 секунд после его падения Knock Out активирует свой эффект:\nЗаставляет их страдать от -5 % затруднений.\nСтатусный эффект на 3/4/5 секунды.","shortDescriptionRu":"Каждый раз, когда Выживший отходит дальше, чем на 6 метров от поддона. в течение 6 секунд после его падения Knock Out активирует свой эффект: Заставляет их страдать от -5% затруднений. Статусный эффект на 5 секунды.","upcomingPatch":false},"assets/perks/iconPerks_LanguidTouch.png":{"englishName":"Languid Touch","owner":"Lich","role":"killer","descriptionEn":"When a Survivor scares off a Crow\nwithin 36 metres of your location, Languid Touch activates:\nCauses that Survivor to suffer from the Exhausted\nStatus Effect for 6/8/10 seconds.\nLanguid Touch has a cool-down of 5 seconds.","descriptionRu":"Когда Выживший отпугивает Ворону\nВ пределах 36 метров от вашего местоположения Languid Touch активирует:\nВызывает, что Выживший страдает от истощения\nСтатусный эффект на 6/8/10 секунд.\nВремя восстановления Languid Touch составляет 5 секунд.","shortDescriptionRu":"Когда Выживший отпугивает Ворону В пределах 36 метров от вашего местоположения Languid Touch активирует: Вызывает, что Выживший страдает от истощения Статусный эффект на 10 секунд. Время восстановления Languid Touch составляет 5 секунд.","upcomingPatch":false},"assets/perks/iconPerks_LethalPursuer.png":{"englishName":"Lethal Pursuer","owner":"Nemesis T-Type","role":"killer","descriptionEn":"At the start of the Trial, the Auras\nof all Survivors\nare revealed to you for 7/8/9 seconds.\nExtends the duration of all instances of a Survivor Aura being revealed to you by +2 seconds.\nLethal Pursuer benefits from its own effect.","descriptionRu":"В начале Испытания Ауры\nвсех выживших\nоткрываются вам на 7/8/9 секунд.\nУвеличивает продолжительность всех случаев раскрытия вам ауры выжившего на +2 секунды.\nLethal Pursuer получает выгоду от своего собственного эффекта.","shortDescriptionRu":"В начале Испытания Ауры всех выживших открываются вам на 9 секунд. Увеличивает продолжительность всех случаев раскрытия вам ауры выжившего на 2 секунды. Lethal Pursuer получает выгоду от своего собственного эффекта.","upcomingPatch":false},"assets/perks/iconPerks_Leverage.png":{"englishName":"Leverage","owner":"Skull Merchant","role":"killer","descriptionEn":"Whenever a Survivor performs an Unhook action, they suffer from the following effect for 60 seconds:\nReduces their Healing speeds by 20/25/30 %.","descriptionRu":"Каждый раз, когда Выживший выполняет действие «Отцепиться», на него в течение 60 секунд действует следующий эффект:\nСнижает скорость их лечения на 20/25/30%.","shortDescriptionRu":"Каждый раз, когда Выживший выполняет действие «Отцепиться», на него в течение 60 секунд действует следующий эффект: Снижает скорость их лечения на 30%.","upcomingPatch":false},"assets/perks/iconPerks_Lightborn.png":{"englishName":"Lightborn","owner":"Hillbilly","role":"killer","descriptionEn":"Unlike other beasts of The Fog, you have adapted to light.\nThe Auras\nof Survivors attempting to blind you by any means are revealed to you for 6/8/10 seconds.\nGrants immunity from being blinded from Flashlights\n, Firecrackers\n, Flash Grenades\n, and Blast Mine\n.","descriptionRu":"В отличие от других зверей Тумана, вы приспособились к свету.\nАуры\nВыживших, пытающихся ослепить вас любыми способами, открываются перед вами на 6/8/10 секунд.\nДает иммунитет от ослепления фонариками.\n, Петарды\n, Световые гранаты\nи Взрывная мина\n.","shortDescriptionRu":"В отличие от других зверей Тумана, вы приспособились к свету. Ауры Выживших, пытающихся ослепить вас любыми способами, открываются перед вами на 10 секунд. Дает иммунитет от ослепления фонариками., Петарды, Световые гранаты и Взрывная мина.","upcomingPatch":false},"assets/perks/iconPerks_MadGrit.png":{"englishName":"Mad Grit","owner":"Frank, Julie, Susie, Joey","role":"killer","descriptionEn":"Whenever you are carrying a Survivor, Mad Grit activates:\nRemoves the Cool-down of missed Basic Attacks.\nPauses the Wiggle Progression of the carried Survivor for 2/3/4 seconds each time you successfully hit another Survivor.","descriptionRu":"Каждый раз, когда вы несете Выжившего, активируется Безумная выдержка:\nУдаляет время восстановления пропущенных базовых атак.\nПриостанавливает движение выжившего на 2/3/4 секунды каждый раз, когда вы успешно ударяете другого выжившего.","shortDescriptionRu":"Каждый раз, когда вы несете Выжившего, активируется Безумная выдержка: Удаляет время восстановления пропущенных базовых атак. Приостанавливает движение выжившего на 4 секунды каждый раз, когда вы успешно ударяете другого выжившего.","upcomingPatch":false},"assets/perks/iconPerks_MakeYourChoice.png":{"englishName":"Make Your Choice","owner":"Pig","role":"killer","descriptionEn":"Whenever a Survivor is rescued from a Hook\n, while you are farther than 32 metres away, Make Your Choice activates:\nCauses the unhooking Survivor to scream and reveal their location to you.\nCauses them to suffer from the Exposed\nStatus Effect for 40/50/60 seconds.\nMake Your Choice has a cooldown of 40/50/60 seconds.","descriptionRu":"Каждый раз, когда Выжившего спасают от Крюка\n, когда вы находитесь на расстоянии более 32 метров, активируется функция «Сделай свой выбор»:\nЗаставляет выжившего, отцепившегося от крюка, кричать и раскрывать вам свое местонахождение.\nЗаставляет их страдать от воздействия\nСтатусный эффект на 40/50/60 секунд.\n«Сделай свой выбор» имеет время восстановления 40/50/60 секунд.","shortDescriptionRu":"Каждый раз, когда Выжившего спасают от Крюка, когда вы находитесь на расстоянии более 32 метров, активируется функция «Сделай свой выбор»: Заставляет выжившего, отцепившегося от крюка, кричать и раскрывать вам свое местонахождение. Заставляет их страдать от воздействия Статусный эффект на 60 секунд. «Сделай свой выбор» имеет время восстановления 60 секунд.","upcomingPatch":false},"assets/perks/iconPerks_MercilessStorm.png":{"englishName":"Merciless Storm","owner":"Onry%C5%8D","role":"killer","descriptionEn":"Whenever a Generator\nreaches 90 % of Repair progression, Merciless Storm triggers its effect:\nAll Survivors repairing that Generator are faced with a continuous stream of Skill Checks\nuntil the Generator is completed.\nIf any contributing Survivor fails a Skill Check or interrupts the action by any means, The Entity\nblocks the Generator for 16/18/20 seconds.\nMerciless Storm can only trigger once per Generator per Trial.","descriptionRu":"Всякий раз, когда генератор\nдостигает 90 % прогресса ремонта, срабатывает эффект «Безжалостной бури»:\nВсе выжившие, ремонтирующие этот генератор, сталкиваются с непрерывным потоком проверок навыков.\nпока Генератор не будет завершен.\nЕсли какой-либо из Выживших, внесший свой вклад, проваливает проверку навыков или каким-либо образом прерывает действие, Сущность\nблокирует Генератор на 16/18/20 секунд.\n«Безжалостный шторм» может сработать только один раз для каждого генератора за испытание.","shortDescriptionRu":"Всякий раз, когда генератор достигает 90% прогресса ремонта, срабатывает эффект «Безжалостной бури»: Все выжившие, ремонтирующие этот генератор, сталкиваются с непрерывным потоком проверок навыков. пока Генератор не будет завершен. Если какой-либо из Выживших, внесший свой вклад, проваливает проверку навыков или каким-либо образом прерывает действие, Сущность блокирует Генератор на 20 секунд.","upcomingPatch":false},"assets/perks/iconPerks_MindBreaker.png":{"englishName":"Mindbreaker","owner":"Demogorgon","role":"killer","descriptionEn":"While repairing a Generator\n, Survivors suffer from the following effects:\nIncurs the Blindness\nand Exhausted\nStatus Effects.\nBoth Status Effects linger for 3/4/5 seconds after ending the interaction.\nMindbreaker cannot be used to override an existing Exhausted Status Effect, but pauses its timer instead.","descriptionRu":"Во время ремонта генератора\n, Выжившие страдают от следующих эффектов:\nНавлекает слепоту\nи измученный\nЭффекты статуса.\nОба эффекта статуса сохраняются в течение 3/4/5 секунд после завершения взаимодействия.\nРазрушитель разума нельзя использовать для отмены существующего эффекта состояния «Усталость», вместо этого он приостанавливает его таймер.","shortDescriptionRu":"Во время ремонта генератора, Выжившие страдают от следующих эффектов: Навлекает слепоту и измученный Эффекты статуса. Оба эффекта статуса сохраняются в течение 5 секунд после завершения взаимодействия. Разрушитель разума нельзя использовать для отмены существующего эффекта состояния «Усталость», вместо этого он приостанавливает его таймер.","upcomingPatch":false},"assets/perks/iconPerks_MonitorAndAbuse.png":{"englishName":"Monitor & Abuse","owner":"Doctor","role":"killer","descriptionEn":"While actively chasing a Survivor, Monitor & Abuse applies its primary effect:\nIncreases your Terror Radius\nby 5/10/15 %.\nWhile not actively chasing a Survivor, Monitor & Abuse applies its secondary effect:\nReduces your Terror Radius by 15/20/25 %.","descriptionRu":"Во время активной погони за Выжившим «Наблюдение и насилие» применяет свой основной эффект:\nУвеличивает ваш радиус террора\nна 5/10/15 %.\nЕсли вы не преследуете выжившего активно, «Наблюдение и насилие» применяет свой дополнительный эффект:\nУменьшает радиус террора на 15/20/25%.","shortDescriptionRu":"Во время активной погони за Выжившим «Наблюдение и насилие» применяет свой основной эффект: Увеличивает ваш радиус террора на 15%. Если вы не преследуете выжившего активно, «Наблюдение и насилие» применяет свой дополнительный эффект: Уменьшает радиус террора на 25%.","upcomingPatch":false},"assets/perks/iconPerks_MonstrousShrine.png":{"englishName":"Scourge Hook: Monstrous Shrine","owner":"Общий","role":"killer","descriptionEn":"At the start of the Trial, the 4 Hooks located inside the Basement\nand an additional 4 Hooks located throughout the Trial Grounds are all changed into Scourge Hooks:\nThe Auras\nof Scourge Hooks are highlighted to you in white.\nWhenever you are farther than 24 metres from a Survivor hooked onto a Scourge Hook, the following effect applies:\nAccelerates their Sacrifice Process by 10/15/20 %.","descriptionRu":"В начале испытания 4 крючка, расположенные внутри подвала.\nи еще 4 Крюка, расположенные по всему Испытательному Полю, превращаются в Крюки Плети:\nАуры\nКрюков Плети выделены белым цветом.\nВсякий раз, когда вы находитесь дальше, чем 24 метра от Выжившего, зацепившегося за Крюк Плети, применяется следующий эффект:\nУскоряет процесс жертвоприношения на 10/15/20%.","shortDescriptionRu":"В начале испытания 4 крючка, расположенные внутри подвала. и еще 4 Крюка, расположенные по всему Испытательному Полю, превращаются в Крюки Плети: Ауры Крюков Плети выделены белым цветом. Всякий раз, когда вы находитесь дальше, чем 24 метра от Выжившего, зацепившегося за Крюк Плети, применяется следующий эффект: Ускоряет процесс жертвоприношения на 20%.","upcomingPatch":false},"assets/perks/iconPerks_Nemesis.png":{"englishName":"Nemesis","owner":"Oni","role":"killer","descriptionEn":"Whenever a Survivor other than your Obsession\nblinds you by any means or stuns you with a Pallet\nor a Locker\n, Nemesis triggers its primary effect:\nCauses that Survivor to become your current Obsession.\nWhenever your Obsession switches to a different Survivor by any means, Nemesis triggers its secondary effects:\nCauses that Survivor to suffer from the Oblivious\nStatus Effect for 40/50/60 seconds.\nTheir Aura\nis revealed to you for 8 seconds.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Всякий раз, когда Выживший, кроме вашей Одержимости\nослепляет вас любым способом или оглушает паллетой\nили шкафчик\n, Немезида активирует свой основной эффект:\nДелает этого Выжившего вашей текущей навязчивой идеей.\nВсякий раз, когда ваша Одержимость каким-либо образом переключается на другого Выжившего, Немезида активирует свои вторичные эффекты:\nПричины, по которым Выживший страдает от Невнимательности\nСтатусный эффект на 40/50/60 секунд.\nИх аура\nоткрывается вам на 8 секунд.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Всякий раз, когда Выживший, кроме вашей Одержимости ослепляет вас любым способом или оглушает паллетой или шкафчик, Немезида активирует свой основной эффект: Делает этого Выжившего вашей текущей навязчивой идеей.","upcomingPatch":false},"assets/perks/iconPerks_NoOneEscapesDeath.png":{"englishName":"Hex: No One Escapes Death","owner":"Общий","role":"killer","descriptionEn":"You are animated by the power of your Hex Totem when the Survivors are on the verge of escaping.\"\nOnce the Exit Gates\nare powered, if there is still a Dull Totem\nremaining in the environment, Hex: No One Escapes Death activates and lights it:\nGrants a 2/3/4 % Haste\nStatus Effect.\nCauses all Survivors to suffer from the Exposed\nStatus Effect.\nOnce the Status Effect is revealed to Survivors, Hex: No One Escapes Death triggers the following effect:\nThe Aura of its Hex Totem is revealed to all Survivors within 4 metres.\nThis range gradually expands to 24 metres over the course of 30 seconds.\nHex: No One Escapes Death remains inactive if no Dull Totems are available.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Вы оживляетесь силой своего Проклятого Тотема, когда Выжившие находятся на грани побега».\nОднажды Выходные Ворота\nвключены, если еще есть Тусклый Тотем\nоставаясь в окружающей среде, Hex: No One Escapes Death активируется и зажигает его:\nДает 2/3/4% скорости.\nЭффект статуса.\nЗаставляет всех выживших страдать от воздействия\nЭффект статуса.\nКак только выжившим становится доступен эффект статуса, «Сглаз: Никто не избежит смерти» активирует следующий эффект:\nАура его проклятого тотема видна всем выжившим в радиусе 4 метров.\nЭтот диапазон постепенно расширяется до 24 метров в течение 30 секунд.\nСглаз: «Никто не избежит смерти» остается неактивным, если нет доступных тусклых тотемов.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Вы оживляетесь силой своего Проклятого Тотема, когда Выжившие находятся на грани побега». Однажды Выходные Ворота включены, если еще есть Тусклый Тотем оставаясь в окружающей среде, Hex: No One Escapes Death активируется и зажигает его: Дает 4% скорости. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_NoWayOut.png":{"englishName":"No Way Out","owner":"Trickster","role":"killer","descriptionEn":"Whenever you hook a Survivor for the first time, No Way Out gains +1 Token.\nOnce the Exit Gates\nare powered, No Way Out activates:\nCauses the first Survivor to interact with either Exit Gate Switch to trigger a Loud Noise Notification at their location.\nUpon triggering the Loud Noise Notification, No Way Out calls upon The Entity\nfor the following effect:\nBlocks both Exit Gate Switches for 12 seconds.\nThis time is extended by an additional 6/9/12 seconds per accumulated Token, up to a combined maximum of 36/48/60 seconds.","descriptionRu":"Каждый раз, когда вы впервые цепляете Выжившего, No Way Out получает +1 жетон.\nОднажды Выходные Ворота\nвключены, активируется No Way Out:\nЗаставляет первого Выжившего взаимодействовать с любым переключателем выходных ворот, чтобы вызвать громкое шумовое уведомление в его местоположении.\nПри срабатывании уведомления о громком шуме No Way Out обращается к Сущности.\nдля следующего эффекта:\nБлокирует оба переключателя выходных ворот на 12 секунд.\nЭто время продлевается дополнительно на 6/9/12 секунд за каждый накопленный жетон, до общего максимума в 36/48/60 секунд.","shortDescriptionRu":"Каждый раз, когда вы впервые цепляете Выжившего, No Way Out получает +1 жетон. Однажды Выходные Ворота включены, активируется No Way Out: Заставляет первого Выжившего взаимодействовать с любым переключателем выходных ворот, чтобы вызвать громкое шумовое уведомление в его местоположении. При срабатывании уведомления о громком шуме No Way Out обращается к Сущности.","upcomingPatch":false},"assets/perks/iconPerks_NowhereToHide.png":{"englishName":"Nowhere to Hide","owner":"Knight","role":"killer","descriptionEn":"Your anger forces Survivors to reveal themselves.\"\nPerforming the Damage Generator action on a Generator\ntriggers Nowhere to Hide:\nThe Auras\nof all Survivors within 24 metres of the Generator's location are revealed to you for 3/4/5 seconds.","descriptionRu":"Ваш гнев заставляет Выживших раскрыться».\nВыполнение действия «Генератор урона» на генераторе\nвызывает срабатывание «Негде спрятаться»:\nАуры\nвсех Выживших в радиусе 24 метров от Генератора открываются вам на 3/4/5 секунды.","shortDescriptionRu":"Ваш гнев заставляет Выживших раскрыться». Выполнение действия «Генератор урона» на генераторе вызывает срабатывание «Негде спрятаться»: Ауры всех Выживших в радиусе 24 метров от Генератора открываются вам на 5 секунды.","upcomingPatch":false},"assets/perks/iconPerks_Oppression.png":{"englishName":"Oppression","owner":"Twins","role":"killer","descriptionEn":"Performing the Damage Generator action on a Generator\ntriggers the following effects:\nRandomly selects up to 4 additional Generators that will also start regressing.\nTriggers a difficult Skill Check\nfor all Survivors currently repairing them.\nOppression has a cool-down of 45/40/35 seconds.","descriptionRu":"Выполнение действия «Генератор урона» на генераторе\nвызывает следующие эффекты:\nСлучайным образом выбирает до 4 дополнительных генераторов, которые также начнут регрессировать.\nЗапускает сложную проверку навыков\nдля всех Выживших, которые в данный момент их ремонтируют.\nУ подавления время восстановления составляет 45/40/35 секунд.","shortDescriptionRu":"Выполнение действия «Генератор урона» на генераторе вызывает следующие эффекты: Случайным образом выбирает до 4 дополнительных генераторов, которые также начнут регрессировать. Запускает сложную проверку навыков для всех Выживших, которые в данный момент их ремонтируют. У подавления время восстановления составляет 35 секунд.","upcomingPatch":false},"assets/perks/iconPerks_OverwhelmingPresence.png":{"englishName":"Overwhelming Presence","owner":"Doctor","role":"killer","descriptionEn":"Whenever a Survivor starts using an Item\nwithin 32 metres of your location, Overwhelming Presence triggers its primary effect:\nInflicts the Exhausted\nStatus Effect for 15 seconds.\nWhenever a Survivor within 32 metres of your location becomes Exhausted by any means, Overwhelming Presence triggers its secondary effect:\nThe Aura\nof whichever Exhausted Survivor is closest to your location is revealed to you for 2/3/4 seconds.\nOverwhelming Presence has a cool-down of 25 seconds.","descriptionRu":"Каждый раз, когда Выживший начинает использовать Предмет\nВ радиусе 32 метров от вашего местоположения «Подавляющее присутствие» активирует свой основной эффект:\nНаносит истощение\nСтатусный эффект на 15 секунд.\nКаждый раз, когда Выживший в радиусе 32 метров от вашего местоположения каким-либо образом истощается, «Подавляющее присутствие» активирует свой вторичный эффект:\nАура\nинформация о том, какой Измученный Выживший находится ближе всего к вашему местоположению, открывается вам на 2/3/4 секунды.\nВремя восстановления «Подавляющего присутствия» составляет 25 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший начинает использовать Предмет В радиусе 32 метров от вашего местоположения «Подавляющее присутствие» активирует свой основной эффект: Наносит истощение Статусный эффект на 15 секунд.","upcomingPatch":false},"assets/perks/iconPerks_PlayWithYourFood.png":{"englishName":"Play with Your Food","owner":"Shape","role":"killer","descriptionEn":"Identical to See How They Run\n.","descriptionRu":"Идентичны, чтобы увидеть, как они работают\n.","shortDescriptionRu":"Идентичны, чтобы увидеть, как они работают.","upcomingPatch":false},"assets/perks/iconPerks_PopGoesTheWeasel.png":{"englishName":"Pop Goes the Weasel","owner":"Kenneth Chase","role":"killer","descriptionEn":"After hooking a Survivor, Pop Goes the Weasel activates for 35/40/45 seconds.\nWhile active, manually damaging a Generator\ntriggers the following effect:\nIncreases the regression amount by +15 % resulting in 20 % regression.\nPop Goes the Weasel deactivates after use or once its timer elapses.","descriptionRu":"После того, как вы подцепите выжившего, Pop Goes the Weasel активируется на 35/40/45 секунд.\nПока активно, повреждение генератора вручную.\nвызывает следующий эффект:\nУвеличивает сумму регрессии на +15 %, что приводит к регрессии 20 %.\nPop Goes the Weasel деактивируется после использования или по истечении таймера.","shortDescriptionRu":"После того, как вы подцепите выжившего, Pop Goes the Weasel активируется на 45 секунд. Пока активно, повреждение генератора вручную. вызывает следующий эффект: Увеличивает сумму регрессии на 15%, что приводит к регрессии 20%.","upcomingPatch":false},"assets/perks/iconPerks_Predator.png":{"englishName":"Predator","owner":"Wraith","role":"killer","descriptionEn":"Whenever you lose a Survivor in a Chase, Predator triggers its effect:\nTheir Aura\nis revealed to you for 4 seconds.\nPredator has a cool-down of 60/50/40 seconds.","descriptionRu":"Каждый раз, когда вы теряете Выжившего в погоне, Хищник срабатывает свой эффект:\nИх аура\nоткрывается вам на 4 секунды.\nХищник имеет время восстановления 60/50/40 секунд.","shortDescriptionRu":"Каждый раз, когда вы теряете Выжившего в погоне, Хищник срабатывает свой эффект: Их аура открывается вам на 4 секунды. Хищник имеет время восстановления 40 секунд.","upcomingPatch":false},"assets/perks/iconPerks_RapidBrutality.png":{"englishName":"Rapid Brutality","owner":"Xenomorph","role":"killer","descriptionEn":"You move with a speed and fury that makes blood run cold.\nYou can no longer gain the Bloodlust\nStatus Effect.\nSuccessfully hitting a Survivor with a Basic Attack grants you a +5 % Haste\nStatus Effect for 8/9/10 seconds.","descriptionRu":"Вы двигаетесь со скоростью и яростью, от которой кровь стынет в жилах.\nВы больше не можете получить Жажда крови.\nЭффект статуса.\nУспешное попадание по Выжившему базовой атакой дает вам +5 % к скорости.\nСтатусный эффект на 8/9/10 секунд.","shortDescriptionRu":"Вы двигаетесь со скоростью и яростью, от которой кровь стынет в жилах. Вы больше не можете получить Жажда крови. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_RememberMe.png":{"englishName":"Remember Me","owner":"Nightmare","role":"killer","descriptionEn":"Whenever the Obsession\nloses a Health State\nby any means, Remember Me gains +1 Token, up to a maximum of 3/4/5 Tokens:\nIncreases the Opening time of both Exit Gates\nby a stack-able 6 seconds per Token, up to a maximum additional Opening time of 18/24/30 seconds.\nThis results in a maximum possible Opening time of 38/44/50 seconds for both Exit Gates.\nRemember Me does not apply its penalty to the Obsession, allowing them to open both Exit Gates in the default time of 20 seconds.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Всякий раз, когда одержимость\nтеряет состояние здоровья\nлюбым способом «Помни меня» получает +1 жетон, максимум до 3/4/5 жетонов:\nУвеличивает время открытия обоих выходных ворот.\nна 6 секунд с возможностью суммирования на каждый жетон, вплоть до максимального дополнительного времени открытия 18/24/30 секунд.\nВ результате максимально возможное время открытия для обоих выходных ворот составляет 38/44/50 секунд.\n«Помни меня» не применяет штраф к Одержимости, позволяя им открыть оба выхода за время по умолчанию 20 секунд.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Всякий раз, когда одержимость теряет состояние здоровья любым способом «Помни меня» получает +1 жетон, максимум до 5 жетонов: Увеличивает время открытия обоих выходных ворот. на 6 секунд с возможностью суммирования на каждый жетон, вплоть до максимального дополнительного времени открытия 30 секунд. В результате максимально возможное время открытия для обоих выходных ворот составляет 50 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Ruin.png":{"englishName":"Hex: Ruin","owner":"Hag","role":"killer","descriptionEn":"All Generators\nnot currently being repaired experience the following effect:\nCauses them to automatically regress at 100/125/150 % of the default Regression rate.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Все генераторы\nв настоящее время не ремонтируется, испытывают следующий эффект:\nЗаставляет их автоматически регрессировать со скоростью 100/125/150 % от скорости регрессии по умолчанию.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Все генераторы в настоящее время не ремонтируется, испытывают следующий эффект: Заставляет их автоматически регрессировать со скоростью 150% от скорости регрессии по умолчанию. Эффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","upcomingPatch":false},"assets/perks/iconPerks_SaveTheBestForLast.png":{"englishName":"Save the Best for Last","owner":"Shape","role":"killer","descriptionEn":"Identical to Keep Them Waiting\n.","descriptionRu":"Идентичен, чтобы заставить их ждать\n.","shortDescriptionRu":"Идентичен, чтобы заставить их ждать.","upcomingPatch":false},"assets/perks/iconPerks_ScourgeHookGiftOfPain.png":{"englishName":"Scourge Hook: Gift of Pain","owner":"Cenobite","role":"killer","descriptionEn":"Identical to Scourge Hook: Weeping Wounds\n.","descriptionRu":"Идентичен Scourge Hook: Мокнущие раны.\n.","shortDescriptionRu":"Идентичен Scourge Hook: Мокнущие раны..","upcomingPatch":false},"assets/perks/iconPerks_SepticTouch.png":{"englishName":"Septic Touch","owner":"Dredge","role":"killer","descriptionEn":"Healing only delays the inevitable.\"\nWhenever a Survivor performs a Healing action while inside the Terror Radius\n, they suffer from the following effects:\nInflicts the Blindness\nand Exhausted\nStatus Effects.\nThese effects linger for 20/25/30 seconds after the Healing action is interrupted by any means.","descriptionRu":"Исцеление лишь отсрочивает неизбежное».\nКаждый раз, когда Выживший выполняет действие Исцеления, находясь внутри Радиуса Ужаса.\n, они страдают от следующих эффектов:\nНакладывает слепоту\nи измученный\nЭффекты статуса.\nЭти эффекты сохраняются в течение 20/25/30 секунд после того, как действие исцеления прерывается любым способом.","shortDescriptionRu":"Исцеление лишь отсрочивает неизбежное». Каждый раз, когда Выживший выполняет действие Исцеления, находясь внутри Радиуса Ужаса., они страдают от следующих эффектов: Накладывает слепоту и измученный Эффекты статуса. Эти эффекты сохраняются в течение 30 секунд после того, как действие исцеления прерывается любым способом.","upcomingPatch":false},"assets/perks/iconPerks_Shadowborn.png":{"englishName":"Shadowborn","owner":"Wraith","role":"killer","descriptionEn":"Whenever you are blinded by any means, Shadowborn triggers its effect:\nGrants a 6/8/10 % Haste\nStatus Effect for 10 seconds.","descriptionRu":"Каждый раз, когда вы каким-либо образом ослеплены, Shadowborn срабатывает свой эффект:\nДает 6/8/10% скорости.\nСтатусный эффект на 10 секунд.","shortDescriptionRu":"Каждый раз, когда вы каким-либо образом ослеплены, Shadowborn срабатывает свой эффект: Дает 10% скорости. Статусный эффект на 10 секунд.","upcomingPatch":false},"assets/perks/iconPerks_SloppyButcher.png":{"englishName":"Sloppy Butcher","owner":"Общий","role":"killer","descriptionEn":"Survivors hit with your vicious Basic Attack suffer from the following effects for 70/80/90 seconds:\nInflicts the Haemorrhage\nand Mangled\nStatus Effects.\nModifies the potency of Haemorrhage:\nIncreases the Spawn frequency of Pools of Blood\nby 50/75/100 %.\nIncreases the Regression rate of partial Healing progression by +25 %.","descriptionRu":"Выжившие, пораженные вашей жестокой базовой атакой, страдают от следующих эффектов в течение 70/80/90 секунд:\nВызывает кровотечение\nи искалеченный\nЭффекты статуса.\nИзменяет эффективность Кровотечения:\nУвеличивает частоту появления Луж Крови.\nна 50/75/100 %.\nУвеличивает скорость регрессии частичного исцеления на +25 %.","shortDescriptionRu":"Выжившие, пораженные вашей жестокой базовой атакой, страдают от следующих эффектов в течение 90 секунд: Вызывает кровотечение и искалеченный Эффекты статуса. Изменяет эффективность Кровотечения: Увеличивает частоту появления Луж Крови. на 100%.","upcomingPatch":false},"assets/perks/iconPerks_SpiesFromTheShadows.png":{"englishName":"Spies from the Shadows","owner":"Общий","role":"killer","descriptionEn":"Whenever a Survivor startles a Crow\nwithin 36/38/40 metres of your location, Spies from the Shadows triggers its effect:\nAlerts you with a unique Loud Noise Notification in the shape of a Crow.\nSpies from the Shadows has a cool-down of 3 seconds between alerts.","descriptionRu":"Каждый раз, когда Выживший пугает Ворону\nв пределах 36/38/40 метров от вашего местоположения «Шпионы из тени» активируют свой эффект:\nПредупреждает вас уникальным громким шумовым уведомлением в форме вороны.\nВремя восстановления способности «Шпионы из тени» между оповещениями составляет 3 секунды.","shortDescriptionRu":"Каждый раз, когда Выживший пугает Ворону в пределах 40 метров от вашего местоположения «Шпионы из тени» активируют свой эффект: Предупреждает вас уникальным громким шумовым уведомлением в форме вороны. Время восстановления способности «Шпионы из тени» между оповещениями составляет 3 секунды.","upcomingPatch":true},"assets/perks/iconPerks_SpiritFury.png":{"englishName":"Spirit Fury","owner":"Spirit","role":"killer","descriptionEn":"After manually breaking a total of 4/3/2 dropped Pallets\nby any means, Spirit Fury activates:\nInstantly breaks the next Pallet used by a Survivor to stun you.\nSpirit Fury deactivates after use and does not affect the duration of the Pallet Stun.","descriptionRu":"После ручного разрушения всего 4/3/2 выпавших поддонов.\nлюбым способом активируется Spirit Fury:\nМгновенно ломает следующую паллету, использованную Выжившим, чтобы оглушить вас.\nSpirit Fury деактивируется после использования и не влияет на продолжительность оглушения Pallet.","shortDescriptionRu":"После ручного разрушения всего 2 выпавших поддонов. любым способом активируется Spirit Fury: Мгновенно ломает следующую паллету, использованную Выжившим, чтобы оглушить вас. Spirit Fury деактивируется после использования и не влияет на продолжительность оглушения Pallet.","upcomingPatch":false},"assets/perks/iconPerks_Starstruck.png":{"englishName":"Starstruck","owner":"Trickster","role":"killer","descriptionEn":"Whenever you are carrying a Survivor, Starstruck activates:\nCauses all other Survivors in your Terror Radius\nto suffer from the Exposed\nStatus Effect.\nThis effect lingers for 26/28/30 seconds after affected Survivors leave the Terror Radius or Starstruck deactivates.\nStarstruck deactivates after hooking or dropping the carried Survivor and has a cool-down of 60 seconds.","descriptionRu":"Каждый раз, когда вы несете Выжившего, активируется Starstruck:\nНаносит урон всем остальным выжившим в вашем радиусе ужаса.\nстрадать от разоблачения\nЭффект статуса.\nЭтот эффект сохраняется в течение 26/28/30 секунд после того, как затронутые Выжившие покидают Радиус Террора или деактивируется Звездный удар.\nStarstruck деактивируется после того, как вы зацепите или уроните выжившего, и его время восстановления составляет 60 секунд.","shortDescriptionRu":"Каждый раз, когда вы несете Выжившего, активируется Starstruck: Наносит урон всем остальным выжившим в вашем радиусе ужаса. страдать от разоблачения Эффект статуса. Этот эффект сохраняется в течение 30 секунд после того, как затронутые Выжившие покидают Радиус Террора или деактивируется Звездный удар.","upcomingPatch":false},"assets/perks/iconPerks_Stridor.png":{"englishName":"Stridor","owner":"Nurse","role":"killer","descriptionEn":"You are acutely sensitive to the breathing of your prey.\nIncreases the volume of Grunts of Pain of injured Survivors by 30/40/50 %.\nIncreases the volume of regular breathing of Survivors by 15/20/25 %.","descriptionRu":"Вы очень чувствительны к дыханию жертвы.\nУвеличивает громкость звуков боли раненых выживших на 30/40/50%.\nУвеличивает объем регулярного дыхания Выживших на 15/20/25 %.","shortDescriptionRu":"Вы очень чувствительны к дыханию жертвы. Увеличивает громкость звуков боли раненых выживших на 50%. Увеличивает объем регулярного дыхания Выживших на 25%.","upcomingPatch":false},"assets/perks/iconPerks_SuperiorAnatomy.png":{"englishName":"Superior Anatomy","owner":"Mastermind","role":"killer","descriptionEn":"Whenever a Survivor performs a Rush Vault action within 12 metres of your location, Superior Anatomy activates:\nIncreases your Vaulting speed by 30/35/40 %.\nSuperior Anatomy deactivates after vaulting.\nSuperior Anatomy has a cool-down of 25 seconds.","descriptionRu":"Каждый раз, когда Выживший выполняет действие Rush Vault в пределах 12 метров от вашего местоположения, активируется Superior Anatomy:\nУвеличивает скорость прыжков на 30/35/40%.\nУлучшенная анатомия деактивируется после прыжка.\nВремя восстановления Superior Anatomy составляет 25 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший выполняет действие Rush Vault в пределах 12 метров от вашего местоположения, активируется Superior Anatomy: Увеличивает скорость прыжков на 40%. Улучшенная анатомия деактивируется после прыжка. Время восстановления Superior Anatomy составляет 25 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Surge.png":{"englishName":"Surge","owner":"Demogorgon","role":"killer","descriptionEn":"Whenever you put a Survivor into the Dying State\nwith your Basic Attack, Surge triggers its effect:\nCauses all Generators\nwithin 32 metres of your location to instantly explode and start regressing.\nInstantly regresses all affected Generators by 6/7/8 %.","descriptionRu":"Всякий раз, когда вы переводите Выжившего в состояние умирания\nс вашей базовой атакой «Всплеск» активирует свой эффект:\nВызывает все генераторы\nв пределах 32 метров от вашего местоположения, чтобы мгновенно взорваться и начать регрессировать.\nМгновенно регрессирует все задействованные генераторы на 6/7/8%.","shortDescriptionRu":"Всякий раз, когда вы переводите Выжившего в состояние умирания с вашей базовой атакой «Всплеск» активирует свой эффект: Вызывает все генераторы в пределах 32 метров от вашего местоположения, чтобы мгновенно взорваться и начать регрессировать. Мгновенно регрессирует все задействованные генераторы на 8%.","upcomingPatch":false},"assets/perks/iconPerks_Surveillance.png":{"englishName":"Surveillance","owner":"Pig","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof damaged Generators\nare highlighted based on their current state:\nWhite Aura: The Generator is currently regressing.\nYellow Aura: The Generator stopped regressing due to Survivor-intervention.\nThis effect lasts for 8/12/16 seconds, after which the Generator Aura returns to its default colour.\nWhile Survivors are repairing Generators, they suffer from the following effect:\nIncreases the audible range of all noises related to the Repair interaction by +8 metres.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nповрежденных генераторов\nвыделяются в зависимости от их текущего состояния:\nБелая Аура: Генератор в настоящее время регрессирует.\nЖелтая аура: Генератор прекратил регрессию из-за вмешательства Выжившего.\nЭтот эффект длится 8/12/16 секунд, после чего Аура Генератора возвращается к цвету по умолчанию.\nПока Выжившие ремонтируют Генераторы, на них действует следующий эффект:\nУвеличивает диапазон слышимости всех шумов, связанных с ремонтом, на +8 метров.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры поврежденных генераторов выделяются в зависимости от их текущего состояния: Белая Аура: Генератор в настоящее время регрессирует. Желтая аура: Генератор прекратил регрессию из-за вмешательства Выжившего. Этот эффект длится 16 секунд, после чего Аура Генератора возвращается к цвету по умолчанию.","upcomingPatch":false},"assets/perks/iconPerks_Terminus.png":{"englishName":"Terminus","owner":"Mastermind","role":"killer","descriptionEn":"Once the Exit Gates\nare powered, Terminus activates:\nCauses all injured, dying, or hooked Survivors to suffer from the Broken\nStatus Effect.\nThis effect last until one of the Exit Gates is opened, after which it lingers for another 35/40/45 seconds.","descriptionRu":"Однажды Выходные Ворота\nвключены, Терминус активируется:\nЗаставляет всех раненых, умирающих или попавших на крючок Выживших страдать от Сломанного.\nЭффект статуса.\nЭтот эффект длится до тех пор, пока не откроется один из Выходных врат, после чего он сохраняется еще 35/40/45 секунд.","shortDescriptionRu":"Однажды Выходные Ворота включены, Терминус активируется: Заставляет всех раненых, умирающих или попавших на крючок Выживших страдать от Сломанного. Эффект статуса. Этот эффект длится до тех пор, пока не откроется один из Выходных врат, после чего он сохраняется еще 45 секунд.","upcomingPatch":false},"assets/perks/iconPerks_TerritorialImperative.png":{"englishName":"Territorial Imperative","owner":"Huntress","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever a Survivor enters the Basement\nwhile you are farther than 24 metres from its entrance, Territorial Imperative activates:\nThe Aura\nof that Survivor is revealed to you for 4/5/6 seconds.\nTerritorial Imperative has a cool-down of 45 seconds.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nКаждый раз, когда Выживший входит в Подвал\nесли вы находитесь на расстоянии более 24 метров от входа, активируется Территориальный императив:\nАура\nэтого Выжившего открывается вам на 4/5/6 секунд.\n«Территориальный императив» имеет время восстановления 45 секунд.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Каждый раз, когда Выживший входит в Подвал если вы находитесь на расстоянии более 24 метров от входа, активируется Территориальный императив: Аура этого Выжившего открывается вам на 6 секунд. «Территориальный императив» имеет время восстановления 45 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Thatanophobia.png":{"englishName":"Thanatophobia","owner":"Nurse","role":"killer","descriptionEn":"Whenever at least one Survivor is either injured, dying, or hooked, Thanatophobia activates.\nWhile active, all Survivors suffer from the following primary effect:\nIncurs a stack-able 1/1.5/2 % Action-Speed penalty per injured, dying, or hooked Survivor for Cleansing, Repairing, and Sabotaging, up to a maximum of 4/6/8 %.\nIf all four Survivors are either injured, dying, or hooked, they suffer from the following secondary effect:\nIncreases the penalty by an additional +12 % to a total of 16/18/20 %.","descriptionRu":"Каждый раз, когда хотя бы один Выживший ранен, умирает или попадает на крючок, активируется танатофобия.\nПока активно, все Выжившие страдают от следующего основного эффекта:\nНакладывает суммируемый штраф к скорости действия в размере 1/1,5/2 % за каждого раненого, умирающего или попавшего на крючок Выжившего за чистку, ремонт и саботаж, вплоть до максимума 4/6/8 %.\nЕсли все четверо Выживших ранены, умирают или попали на крючок, они страдают от следующего вторичного эффекта:\nУвеличивает штраф еще на +12 % до общей суммы 16/18/20 %.","shortDescriptionRu":"Каждый раз, когда хотя бы один Выживший ранен, умирает или попадает на крючок, активируется танатофобия. Пока активно, все Выжившие страдают от следующего основного эффекта: Накладывает суммируемый штраф к скорости действия в размере 2% за каждого раненого, умирающего или попавшего на крючок Выжившего за чистку, ремонт и саботаж, вплоть до максимума 8%.","upcomingPatch":false},"assets/perks/iconPerks_TheThirdSeal.png":{"englishName":"Hex: The Third Seal","owner":"Hag","role":"killer","descriptionEn":"The last 2/3/4 Survivors you hit with a Basic or Special Attack suffer permanently from the Blindness\nStatus Effect.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Последние 2/3/4 выживших, которых вы поразили базовой или специальной атакой, навсегда страдают от слепоты.\nЭффект статуса.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Последние 4 выживших, которых вы поразили базовой или специальной атакой, навсегда страдают от слепоты. Эффект статуса. Эффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","upcomingPatch":false},"assets/perks/iconPerks_ThrillingTremors.png":{"englishName":"Thrilling Tremors","owner":"Danny Johnson","role":"killer","descriptionEn":".\"\nAfter picking up a Survivor, Thrilling Tremors triggers its effects:\nBlocks all Generators\nnot currently being repaired by any Survivors for 16 seconds.\nThe Auras\nof Blocked Generators are highlighted to you in white.\nThrilling Tremors has a cool-down of 40/35/30 seconds.","descriptionRu":".\"\nПосле того, как вы подберете выжившего, сработает эффект «Тревожная дрожь»:\nБлокирует все генераторы\nв настоящее время не ремонтируется никем из Выживших в течение 16 секунд.\nАуры\nзаблокированных генераторов выделены белым цветом.\nВремя восстановления Thrilling Tremors составляет 40/35/30 секунд.","shortDescriptionRu":".\" После того, как вы подберете выжившего, сработает эффект «Тревожная дрожь»: Блокирует все генераторы в настоящее время не ремонтируется никем из Выживших в течение 16 секунд. Ауры заблокированных генераторов выделены белым цветом. Время восстановления Thrilling Tremors составляет 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_ThrillOfTheHunt.png":{"englishName":"Hex: Thrill of the Hunt","owner":"Общий","role":"killer","descriptionEn":"The false hope of Survivors fills you with excitement and strengthens your Totems.\"\nStart the Trial with 5 Tokens, one for each Totem located in the environment:\nReduces the Action speeds for Blessing and Cleansing by a stack-able 8/9/10 % per Token, up to a maximum of 40/45/50 %.\nHex: Thrill of the Hunt loses -1 Token whenever a Totem is cleansed.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Ложная надежда Выживших наполняет вас волнением и укрепляет ваши тотемы».\nНачните испытание с 5 жетонами, по одному на каждый тотем, расположенный в окружающей среде:\nСнижает скорость действий для Благословения и Очищения на суммируемую 8/9/10 % за каждый жетон, максимум до 40/45/50 %.\nПорча: «Азарт охоты» теряет -1 жетон при очистке тотема.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Ложная надежда Выживших наполняет вас волнением и укрепляет ваши тотемы». Начните испытание с 5 жетонами, по одному на каждый тотем, расположенный в окружающей среде: Снижает скорость действий для Благословения и Очищения на суммируемую 10% за каждый жетон, максимум до 50%. Порча: «Азарт охоты» теряет -1 жетон при очистке тотема.","upcomingPatch":false},"assets/perks/iconPerks_Thwack.png":{"englishName":"THWACK!","owner":"Skull Merchant","role":"killer","descriptionEn":"Start the Trial with 3 Tokens.\nWhenever you break a Breakable Wall\nor a dropped Pallet\n, THWACK! consumes -1 Token and applies the following effect:\nCauses all Survivors within 36 metres of your location to scream and reveal their Aura\nfor 4/5/6 seconds.\nWhenever you hook a Survivor, THWACK! is granted +1 Token.","descriptionRu":"Начните пробную версию с 3 жетонами.\nВсякий раз, когда вы ломаете разрушаемую стену\nили упавший поддон\n, ТУАК! потребляет -1 жетон и применяет следующий эффект:\nЗаставляет всех Выживших в радиусе 36 метров от вас кричать и раскрывать свою ауру.\nна 4/5/6 секунд.\nВсякий раз, когда вы цепляете Выжившего, УДАРИТЕ! получает +1 жетон.","shortDescriptionRu":"Начните пробную версию с 3 жетонами. Всякий раз, когда вы ломаете разрушаемую стену или упавший поддон, ТУАК! потребляет -1 жетон и применяет следующий эффект: Заставляет всех Выживших в радиусе 36 метров от вас кричать и раскрывать свою ауру.","upcomingPatch":false},"assets/perks/iconPerks_Tinkerer.png":{"englishName":"Tinkerer","owner":"Hillbilly","role":"killer","descriptionEn":"Whenever a Generator\nis repaired to 70 %, you benefit from the following effects:\nTriggers a Loud Noise Notification for that Generator, revealing its location.\nGrants the Undetectable\nStatus Effect for the next 12/14/16 seconds.\nTinkerer can only trigger once per Generator per Trial.","descriptionRu":"Всякий раз, когда генератор\nвосстанавливается на 70 %, вы получаете следующие эффекты:\nЗапускает уведомление о громком шуме для этого генератора, раскрывая его местоположение.\nДарует необнаружимое\nЭффект статуса на следующие 12/14/16 секунд.\nTinkerer может сработать только один раз для каждого генератора за испытание.","shortDescriptionRu":"Всякий раз, когда генератор восстанавливается на 70%, вы получаете следующие эффекты: Запускает уведомление о громком шуме для этого генератора, раскрывая его местоположение. Дарует необнаружимое Эффект статуса на следующие 16 секунд. Tinkerer может сработать только один раз для каждого генератора за испытание.","upcomingPatch":false},"assets/perks/iconPerks_TrailOfTorment.png":{"englishName":"Trail of Torment","owner":"Executioner","role":"killer","descriptionEn":"Performing the Damage Generator action on a Generator\nactivates Trail of Torment:\nGrants the Undetectable\nStatus Effect.\nThe Aura\nof the Damaged Generator is revealed to all Survivors and highlighted in yellow.\nTrail of Torment deactivates after the Damaged Generator stops regressing by any means and has a cool-down of 60/45/30 seconds between activations.","descriptionRu":"Выполнение действия «Генератор урона» на генераторе\nактивирует След Мучений:\nДарует необнаружимое\nЭффект статуса.\nАура\nИнформация о поврежденном генераторе видна всем выжившим и выделена желтым цветом.\nСлед Мучений деактивируется после того, как Поврежденный Генератор перестает регрессировать любым способом, и время восстановления между активациями составляет 60/45/30 секунд.","shortDescriptionRu":"Выполнение действия «Генератор урона» на генераторе активирует След Мучений: Дарует необнаружимое Эффект статуса. Аура Информация о поврежденном генераторе видна всем выжившим и выделена желтым цветом. След Мучений деактивируется после того, как Поврежденный Генератор перестает регрессировать любым способом, и время восстановления между активациями составляет 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_twoCanPlay.png":{"englishName":"Hex: Two Can Play","owner":"Charles Lee Ray","role":"killer","descriptionEn":"Anytime you are stunned or blinded by any Survivor a total of 4/3/2 times, and if there is not yet a Hex Totem\nalready associated with Hex: Two Can Play and there is at least one Dull Totem\nremaining in the Trial Grounds, Hex: Two Can Play activates on a random Totem:\nBlinds all Survivors who stun or blind you for 1.5 seconds.\nThis does not affect carried Survivors.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Каждый раз, когда вы оглушены или ослеплены любым Выжившим в общей сложности 4/3/2 раза, и если еще нет Hex Totem\nуже связан с Hex: Two Can Play и есть хотя бы один Тупой Тотем\nОставаясь на Испытательной площадке, на случайном тотеме активируется Hex: Two Can Play:\nОслепляет всех выживших, которые вас оглушают или ослепляют, на 1,5 секунды.\nЭто не влияет на переносимых Выживших.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Каждый раз, когда вы оглушены или ослеплены любым Выжившим в общей сложности 2 раза, и если еще нет Hex Totem уже связан с Hex: Two Can Play и есть хотя бы один Тупой Тотем Оставаясь на Испытательной площадке, на случайном тотеме активируется Hex: Two Can Play: Ослепляет всех выживших, которые вас оглушают или ослепляют, на 1,5 секунды. Это не влияет на переносимых Выживших.","upcomingPatch":false},"assets/perks/iconPerks_UltimateWeapon.png":{"englishName":"Ultimate Weapon","owner":"Xenomorph","role":"killer","descriptionEn":"Whenever you search a Locker\n, Ultimate Weapon triggers its effects on all Survivors within 40 metres of its location:\nCauses them to scream and reveal their location to you.\nInflicts the Blindness\nStatus Effect for 30 seconds.\nUltimate Weapon has a cool-down of 55/50/45 seconds.","descriptionRu":"Всякий раз, когда вы обыскиваете шкафчик\n, Абсолютное оружие срабатывает на всех Выживших в радиусе 40 метров от своего местоположения:\nЗаставляет их кричать и раскрывать вам свое местонахождение.\nНакладывает слепоту\nСтатусный эффект на 30 секунд.\nВремя восстановления Ultimate Weapon составляет 55/50/45 секунд.","shortDescriptionRu":"Всякий раз, когда вы обыскиваете шкафчик, Абсолютное оружие срабатывает на всех Выживших в радиусе 40 метров от своего местоположения: Заставляет их кричать и раскрывать вам свое местонахождение. Накладывает слепоту Статусный эффект на 30 секунд. Время восстановления Ultimate Weapon составляет 45 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Unbound.png":{"englishName":"Unbound","owner":"Unknown","role":"killer","descriptionEn":"When a Survivor becomes injured by any means, Unbound activates for 26/28/30 seconds:\nVaulting a Window\nwhile Unbound is active grants a +5 % Haste\nStatus Effect for 25 seconds.\nThis effect cannot stack with itself.","descriptionRu":"Когда Выживший получает травму каким-либо образом, Unbound активируется на 26/28/30 секунд:\nСводка окна\nпока действует Unbound, скорость увеличивается на 5 %.\nСтатусный эффект на 25 секунд.\nЭтот эффект не может суммироваться сам с собой.","shortDescriptionRu":"Когда Выживший получает травму каким-либо образом, Unbound активируется на 30 секунд: Сводка окна пока действует Unbound, скорость увеличивается на 5%. Статусный эффект на 25 секунд. Этот эффект не может суммироваться сам с собой.","upcomingPatch":true},"assets/perks/iconPerks_Undone.png":{"englishName":"Undone","owner":"Unknown","role":"killer","descriptionEn":"For every Repair or Healing Skill Check\nfailed by a Survivor, Undone gains +3 Tokens, up to a maximum of 18/24/30 Tokens.\nPerforming the Damage Generator action on a Generator\nconsumes all accumulated Tokens and applies the following effects:\nInstantly regresses the Damaged Generator by a stack-able -1 % of its total Progression per Token, up to a maximum of 18/24/30 %.\nBlocks the Damaged Generator for 1 second per Token, up to a maximum of 18/24/30 seconds.\nCauses the Damaged Generator to start regressing once it becomes unblocked.\nUndone has a cool-down of 60 seconds.","descriptionRu":"За каждую проверку навыка ремонта или лечения.\nпровалено Выжившим, Отмена получает +3 жетона, максимум до 18/24/30 жетонов.\nВыполнение действия «Генератор урона» на генераторе\nпотребляет все накопленные жетоны и применяет следующие эффекты:\nМгновенно регрессирует поврежденный генератор на суммируемый -1 % от его общего прогресса за каждый жетон, вплоть до максимального значения 18/24/30 %.\nБлокирует поврежденный генератор на 1 секунду за каждый жетон, максимум до 18/24/30 секунд.\nЗаставляет поврежденный генератор начать регрессировать, как только он разблокируется.\nВремя восстановления Undone составляет 60 секунд.","shortDescriptionRu":"За каждую проверку навыка ремонта или лечения. провалено Выжившим, Отмена получает +3 жетона, максимум до 30 жетонов. Выполнение действия «Генератор урона» на генераторе потребляет все накопленные жетоны и применяет следующие эффекты: Мгновенно регрессирует поврежденный генератор на суммируемый -1% от его общего прогресса за каждый жетон, вплоть до максимального значения 30%.","upcomingPatch":false},"assets/perks/iconPerks_Unforeseen.png":{"englishName":"Unforeseen","owner":"Unknown","role":"killer","descriptionEn":"After performing the Damage Generator action on a Generator\n, you benefit from the following effects for 22/26/30 seconds:\nTransfers your Terror Radius\nto the damaged Generator.\nThis Terror Radius is set to 32 metres.\nGrants the Undetectable\nStatus Effect.\nUnforeseen has a cool-down of 30 seconds.","descriptionRu":"После выполнения действия «Генератор урона» на Генераторе\n, вы получаете следующие эффекты в течение 22/26/30 секунд:\nПереносит ваш радиус террора\nк поврежденному генератору.\nЭтот радиус террора установлен на 32 метра.\nДарует необнаружимое\nЭффект статуса.\nНепредвиденное имеет время восстановления 30 секунд.","shortDescriptionRu":"После выполнения действия «Генератор урона» на Генераторе, вы получаете следующие эффекты в течение 30 секунд: Переносит ваш радиус террора к поврежденному генератору. Этот радиус террора установлен на 32 метра. Дарует необнаружимое Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_UnnervingPresence.png":{"englishName":"Unnerving Presence","owner":"Trapper","role":"killer","descriptionEn":"While inside your Terror Radius\n, Survivors performing Repairing or Healing actions suffer from the following effects:\nIncreases the chances of triggering a Skill Check by +10 %.\nReduces the Success zone of those Skill Checks\nby 40/50/60 %.","descriptionRu":"Находясь внутри радиуса террора\n, Выжившие, выполняющие действия «Ремонт» или «Исцеление», страдают от следующих эффектов:\nУвеличивает вероятность запуска проверки навыков на +10 %.\nУменьшает зону успеха этих проверок навыков.\nна 40/50/60 %.","shortDescriptionRu":"Находясь внутри радиуса террора, Выжившие, выполняющие действия «Ремонт» или «Исцеление», страдают от следующих эффектов: Увеличивает вероятность запуска проверки навыков на 10%. Уменьшает зону успеха этих проверок навыков. на 60%.","upcomingPatch":false},"assets/perks/iconPerks_Unrelenting.png":{"englishName":"Unrelenting","owner":"Общий","role":"killer","descriptionEn":"Basic Attacks benefit from the following effect:\nReduces the Cool-down time of missed attacks by 20/25/30 %.","descriptionRu":"Базовые атаки получают следующий эффект:\nУменьшает время восстановления пропущенных атак на 20/25/30 %.","shortDescriptionRu":"Базовые атаки получают следующий эффект: Уменьшает время восстановления пропущенных атак на 30%.","upcomingPatch":false},"assets/perks/iconPerks_Whispers.png":{"englishName":"Whispers","owner":"Общий","role":"killer","descriptionEn":"Whenever any Survivor is within 48/40/32 metres of your location, Whispers triggers its effect:\nCauses you to hear the sporadic whispers of The Entity\n, indicating a Survivor's presence.","descriptionRu":"Каждый раз, когда какой-либо Выживший находится в пределах 48/40/32 метров от вашего местоположения, «Шепот» активирует свой эффект:\nЗаставляет вас слышать спорадический шепот Сущности.\n, указывая на присутствие Выжившего.","shortDescriptionRu":"Каждый раз, когда какой-либо Выживший находится в пределах 32 метров от вашего местоположения, «Шепот» активирует свой эффект: Заставляет вас слышать спорадический шепот Сущности., указывая на присутствие Выжившего.","upcomingPatch":false},"assets/perks/iconPerks_ZanshinTactics.png":{"englishName":"Zanshin Tactics","owner":"Oni","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof Pallets\nand Windows\nare revealed to you within 32 metres.\nWhenever a Survivor drops a Pallet, Zanshin Tactics triggers the following effect:\nTheir Aura is revealed to you for 3/4/5 seconds.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nподдонов\nи Windows\nоткрываются вам в радиусе 32 метров.\nКаждый раз, когда Выживший роняет поддон, Тактика Заншин вызывает следующий эффект:\nИх аура открывается вам на 3/4/5 секунды.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры поддонов и Windows открываются вам в радиусе 32 метров. Каждый раз, когда Выживший роняет поддон, Тактика Заншин вызывает следующий эффект: Их аура открывается вам на 5 секунды.","upcomingPatch":false},"assets/perks/T_iconPerks_GrimEmbrace.png":{"englishName":"Grim Embrace","owner":"Artist","role":"killer","descriptionEn":"Your act of servitude to The Entity has not gone unnoticed.\nEach time a Survivor is hooked for the first time, Grim Embrace gains +1 Token and activates once you are at least 16 metres away from the Hook\n:\n1-3 Tokens: Blocks all Generators\nfor 6/8/10 seconds.\n4 Tokens: Blocks all Generators for 40 seconds and the Aura\nof the Obsession\nis revealed to you for 6 seconds.","descriptionRu":"Ваш акт служения Сущности не остался незамеченным.\nКаждый раз, когда Выживший впервые попадает на крюк, Grim Embrace получает +1 жетон и активируется, когда вы находитесь на расстоянии не менее 16 метров от Крюка.\n:\n1–3 жетона: блокирует все генераторы.\nна 6/8/10 секунд.\n4 жетона: блокирует все генераторы на 40 секунд и ауру.\nОдержимости\nоткрывается вам на 6 секунд.","shortDescriptionRu":"Ваш акт служения Сущности не остался незамеченным. Каждый раз, когда Выживший впервые попадает на крюк, Grim Embrace получает +1 жетон и активируется, когда вы находитесь на расстоянии не менее 16 метров от Крюка.: 1–3 жетона: блокирует все генераторы. на 10 секунд.","upcomingPatch":false},"assets/perks/T_iconPerks_HexPentimento.png":{"englishName":"Hex: Pentimento","owner":"Artist","role":"killer","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof cleansed Totems are revealed to you in white.\nPress the Interaction button over the remains of a cleansed Totem\nto resurrect it as a Rekindled Totem.\nFor each Rekindled Totem, Hex: Pentimento gains +1 Token, up to a maximum of 5 Tokens:\n1 Token: Reduces the Action speeds for Healing and Repairing by -20 %.\n2 to 5 Tokens: Increase the strength of the Action Speed penalty by a stackable 1/2/3 % per Token, up to a maximum of 24/28/32 %.\nSurvivors cursed by Hex: Pentimento see the Auras of Rekindled Totems within 16 metres.\nOnce Hex: Pentimento has reached its limit of 5 Tokens, it calls upon The Entity for the following effect:\nBlocks all Rekindled Totems for the remainder of the Trial.\nTotems may only be rekindled once per Trial, with The Entity consuming the remains of Rekindled Totems once they are cleansed.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nочищенных Тотемов предстанут перед вами в белом цвете.\nНажмите кнопку «Взаимодействие» над остатками очищенного Тотема.\nчтобы воскресить его как Возрожденный Тотем.\nЗа каждый возрожденный тотем Hex: Pentimento получает +1 жетон, максимум до 5 жетонов:\n1 жетон: снижает скорость действий при лечении и ремонте на -20 %.\nОт 2 до 5 жетонов: увеличьте силу штрафа к скорости действия на суммируемый 1/2/3 % за каждый жетон, вплоть до максимального значения 24/28/32 %.\nВыжившие, проклятые проклятием: Пентименто, видят ауры возрожденных тотемов в радиусе 16 метров.\nКак только Hex: Pentimento достигает предела в 5 жетонов, он призывает Сущность для следующего эффекта:\nБлокирует все возрожденные тотемы до конца испытания.\nТотемы можно возродить заново только один раз за Испытание, при этом Сущность поглощает остатки Возрожденных Тотемов после их очищения.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры очищенных Тотемов предстанут перед вами в белом цвете. Нажмите кнопку «Взаимодействие» над остатками очищенного Тотема. чтобы воскресить его как Возрожденный Тотем.","upcomingPatch":false},"assets/perks/T_iconPerks_PainResonance.png":{"englishName":"Scourge Hook: Pain Resonance","owner":"Artist","role":"killer","descriptionEn":"Overwhelming pain reverberates outwards.\nAt the start of the Trial, 4 Hooks in the environment are changed into Scourge Hooks:\nThe Auras\nof these Scourge Hooks are highlighted in white.\nStart the Trial with 4 Token.\nWhenever a Survivor is hooked onto a Scourge Hook for the first time, Scourge Hook: Pain Resonance consumes -1 Token and applies the following effects:\nCauses the Generator\nwith the most progression to explode, damaging it.\nInstantly regresses the Damaged Generator by 10/15/20 % of its total Progression.\nCauses the Damaged Generator to start regressing afterwards.\nCauses all Survivors repairing the Damaged Generator to scream.\nThis does not trigger a Loud Noise Notification.\nScourge Hook: Pain Resonance is disabled for the remainder of the Trial once all Tokens are consumed.","descriptionRu":"Невыносимая боль отражается наружу.\nВ начале испытания 4 крючка в окружающей среде превращаются в крючки Плети:\nАуры\nиз этих Крюков Плети выделены белым цветом.\nНачните пробную версию с 4 жетонами.\nКаждый раз, когда Выживший впервые цепляется за Крюк Плети, Крюк Плети: Резонанс боли потребляет -1 жетон и применяет следующие эффекты:\nВызывает Генератор\nс наибольшим прогрессом взорваться, повредив его.\nМгновенно регрессирует поврежденный генератор на 10/15/20 % от его общего прогресса.\nЗаставляет поврежденный генератор впоследствии начать регрессировать.\nЗаставляет кричать всех выживших, ремонтирующих поврежденный генератор.\nЭто не вызывает уведомление о громком шуме.\nКрюк Плети: Резонанс боли отключается до конца испытания, как только все жетоны будут израсходованы.","shortDescriptionRu":"Невыносимая боль отражается наружу. В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети: Ауры из этих Крюков Плети выделены белым цветом. Начните пробную версию с 4 жетонами.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_AllShakingThunder.png":{"englishName":"All-Shaking Thunder","owner":"Houndmaster","role":"killer","descriptionEn":"After falling from a height, All-Shaking Thunder activates for 15/20/25 seconds:\nIncreases the range of your Lunge Attack by +75 %.\nAll-Shaking Thunder has a cool-down of 5 seconds.","descriptionRu":"После падения с высоты активируется Всетрясающий Гром на 15/20/25 секунд:\nУвеличивает дальность вашей атаки с выпадом на +75%.\nВремя восстановления «Всетрясающего грома» составляет 5 секунд.","shortDescriptionRu":"После падения с высоты активируется Всетрясающий Гром на 25 секунд: Увеличивает дальность вашей атаки с выпадом на 75%. Время восстановления «Всетрясающего грома» составляет 5 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_ForeverEntwined.png":{"englishName":"Forever Entwined","owner":"Ghoul","role":"killer","descriptionEn":"Whenever a Survivors takes damage, Forever Entwined gains +1 Token, up to a maximum of 6/7/8 Tokens:\nIncreases the Action speeds for Dropping, Hooking, and Picking up a Survivor by a stack-able +4 % per Token, up to a maximum of 24/28/32 %.","descriptionRu":"Каждый раз, когда Выживший получает урон, Forever Entwined получает +1 жетон, максимум до 6/7/8 жетонов:\nУвеличивает скорость действий при падении, подхвате и подхвате выжившего на суммируемую +4 % за каждый жетон, вплоть до максимального значения 24/28/32 %.","shortDescriptionRu":"Каждый раз, когда Выживший получает урон, Forever Entwined получает +1 жетон, максимум до 8 жетонов: Увеличивает скорость действий при падении, подхвате и подхвате выжившего на суммируемую +4% за каждый жетон, вплоть до максимального значения 32%.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_Haywire.png":{"englishName":"Haywire","owner":"Animatronic","role":"killer","descriptionEn":"Whenever a Survivor stops opening an Exit Gate\nafter accumulating at least 80 % Progression towards being opened, Haywire causes it to regress:\nRegresses at a rate of 80/90/100 % of the normal Gate-Opening speed.\nCauses Survivors to see the lights atop the switch flickering randomly while it regresses.","descriptionRu":"Каждый раз, когда Выживший перестает открывать Выходные ворота\nпосле накопления не менее 80 % прогресса к открытию Haywire заставляет его регрессировать:\nРегрессирует со скоростью 80/90/100 % от нормальной скорости открытия врат.\nЗаставляет Выживших видеть, как огни на переключателе беспорядочно мигают, пока он регрессирует.","shortDescriptionRu":"Каждый раз, когда Выживший перестает открывать Выходные ворота после накопления не менее 80% прогресса к открытию Haywire заставляет его регрессировать: Регрессирует со скоростью 100% от нормальной скорости открытия врат. Заставляет Выживших видеть, как огни на переключателе беспорядочно мигают, пока он регрессирует.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_HelpWanted.png":{"englishName":"Help Wanted","owner":"Animatronic","role":"killer","descriptionEn":"After performing the Damage Generator action, Help Wanted activates:\nCauses that Generator\nto become a Compromised Generator.\nUp to 3 Generators can be Compromised at a time.\nThe Auras\nof all Compromised Generators are highlighted to you in yellow.\nOnce a Compromised Generator is completed, Help Wanted triggers its effects for 100/110/120 seconds:\nIncreases the Recovery speed of successful Basic Attacks by +25 %.\nAll Generators not being repaired will automatically regress at 150 % of the default Regression rate.\nAdditionally, all other Generators are no longer Compromised.","descriptionRu":"После выполнения действия «Генератор урона» активируется функция «Требуется помощь»:\nВызывает, что Генератор\nстать Компромиссным Генератором.\nОдновременно можно взломать до 3 генераторов.\nАуры\nвсех скомпрометированных генераторов выделены желтым цветом.\nКак только взломанный генератор будет завершен, эффект «Требуется помощь» активирует свои эффекты на 100/110/120 секунд:\nУвеличивает скорость восстановления после успешных базовых атак на +25 %.\nВсе генераторы, не подлежащие ремонту, автоматически регрессируют со скоростью 150 % от скорости регрессии по умолчанию.\nКроме того, все остальные генераторы больше не подвергаются риску.","shortDescriptionRu":"После выполнения действия «Генератор урона» активируется функция «Требуется помощь»: Вызывает, что Генератор стать Компромиссным Генератором. Одновременно можно взломать до 3 генераторов. Ауры всех скомпрометированных генераторов выделены желтым цветом.","upcomingPatch":true},"assets/perks/T_UI_iconPerks_HexOvertureOfDoom.png":{"englishName":"Hex: Overture of Doom","owner":"Krasue","role":"killer","descriptionEn":"Creates a Hex Totem that curses the farthest Generator\nfrom its location:\nThe Aura\nof the Cursed Generator is highlighted in yellow.\nWhen a Survivor repairs the Cursed Generator for at least 5 seconds, Hex: Overture of Doom triggers the following effects for 20/25/30 seconds:\nTransfers your Terror Radius\nto the Cursed Generator.\nThis Terror Radius is set to 32 metres.\nGrants the Undetectable\nStatus Effect.\nOnce the Cursed Generator is repaired, the next farthest Generator becomes cursed.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Создает тотем порчи, который проклинает самый дальний генератор.\nот его местоположения:\nАура\nПроклятого Генератора выделен желтым цветом.\nКогда Выживший ремонтирует Проклятый Генератор в течение как минимум 5 секунд, «Сглаз: Увертюра Рока» вызывает следующие эффекты на 20/25/30 секунд:\nПереносит ваш радиус террора\nк Проклятому генератору.\nЭтот радиус террора установлен на 32 метра.\nДарует необнаружимое\nЭффект статуса.\nКак только проклятый генератор будет отремонтирован, следующий самый дальний генератор станет проклятым.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Создает тотем порчи, который проклинает самый дальний генератор. от его местоположения: Аура Проклятого Генератора выделен желтым цветом. Когда Выживший ремонтирует Проклятый Генератор в течение как минимум 5 секунд, «Сглаз: Увертюра Рока» вызывает следующие эффекты на 30 секунд: Переносит ваш радиус террора к Проклятому генератору.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_NoHoldsBarred.png":{"englishName":"No Holds Barred","owner":"Общий","role":"killer","descriptionEn":"Each time a Generator\nis completed, No Holds Barred calls upon The Entity\nfor the following effects:\nBlocks the Generator with the most Progression for 15/20/25 seconds.\nThe Aura\nof the Blocked Generator is highlighted to you in white.","descriptionRu":"Каждый раз, когда Генератор\nзавершено, No Holds Barred призывает Сущность\nдля следующих эффектов:\nБлокирует Генератор с наибольшим прогрессом на 15/20/25 секунд.\nАура\nБлокированного Генератора выделен для вас белым цветом.","shortDescriptionRu":"Каждый раз, когда Генератор завершено, No Holds Barred призывает Сущность для следующих эффектов: Блокирует Генератор с наибольшим прогрессом на 25 секунд. Аура Блокированного Генератора выделен для вас белым цветом.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_NoneAreFree.png":{"englishName":"None Are Free","owner":"Ghoul","role":"killer","descriptionEn":"Whenever you hook a Survivor for the first time, None Are Free gains +1 Token, up to a maximum of 4 Tokens.\nOnce all Generators\nare completed, None Are Free calls upon The Entity\nto trigger the following effect:\nBlocks all Windows\nand upright Pallets\nfor a stack-able 12/14/16 seconds per Token, up to a maximum of 48/56/64 seconds.","descriptionRu":"Каждый раз, когда вы впервые цепляете Выжившего, «Никто не свободен» получает +1 жетон, максимум до 4 жетонов.\nКогда все генераторы\nзавершены, ни один из них не является бесплатным обращением к Сущности\nчтобы вызвать следующий эффект:\nБлокирует все окна\nи вертикальные поддоны\nдля суммируемых 12/14/16 секунд на каждый токен, максимум до 48/56/64 секунд.","shortDescriptionRu":"Каждый раз, когда вы впервые цепляете Выжившего, «Никто не свободен» получает +1 жетон, максимум до 4 жетонов. Когда все генераторы завершены, ни один из них не является бесплатным обращением к Сущности чтобы вызвать следующий эффект: Блокирует все окна и вертикальные поддоны для суммируемых 16 секунд на каждый токен, максимум до 64 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_NoQuarter.png":{"englishName":"No Quarter","owner":"Houndmaster","role":"killer","descriptionEn":"Whenever a Survivor healing themselves by any means reaches 75 % Healing Progress, No Quarter triggers its effect:\nThe Survivor is faced with a continuous stream of Skill Checks\nuntil the Self-Heal is completed.\nIf they fail a Skill Check or interrupt the action by any means, they suffer from the Broken\nStatus Effect for 20/25/30 seconds.","descriptionRu":"Каждый раз, когда Выживший, исцеляющий себя любым способом, достигает 75 % прогресса исцеления, эффект «Нет четверти» срабатывает:\nВыжившему предстоит пройти непрерывный поток проверок навыков.\nпока самоисцеление не завершится.\nЕсли они проваливают проверку навыков или каким-либо образом прерывают действие, они страдают от Сломанного состояния.\nСтатусный эффект на 20/25/30 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший, исцеляющий себя любым способом, достигает 75% прогресса исцеления, эффект «Нет четверти» срабатывает: Выжившему предстоит пройти непрерывный поток проверок навыков. пока самоисцеление не завершится. Если они проваливают проверку навыков или каким-либо образом прерывают действие, они страдают от Сломанного состояния.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_NothingButMisery.png":{"englishName":"Hex: Nothing but Misery","owner":"Ghoul","role":"killer","descriptionEn":"After damaging Survivors a total of 8 times with Basic Attacks, a random Dull Totem\nbecomes a Hex Totem\n, cursing all Survivors:\nSurvivors damaged by a Basic Attack suffer from a -5 % Hindered\nStatus Effect for 10/12.5/15 seconds.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"После того, как выжившие нанесут 8 повреждений базовыми атаками, случайный тусклый тотем\nстановится шестнадцатеричным тотемом\n, проклиная всех Выживших:\nВыжившие, получившие урон от базовой атаки, получают -5 % замедления.\nСтатусный эффект на 10/12,5/15 секунд.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"После того, как выжившие нанесут 8 повреждений базовыми атаками, случайный тусклый тотем становится шестнадцатеричным тотемом, проклиная всех Выживших: Выжившие, получившие урон от базовой атаки, получают -5% замедления. Статусный эффект на 15 секунд. Эффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_PhantomFear.png":{"englishName":"Phantom Fear","owner":"Animatronic","role":"killer","descriptionEn":"Whenever a Survivor within your Terror Radius\nlooks at you, they suffer from the following effects:\nCauses them to scream and reveal their Aura\nto you for 2 seconds.\nPhantom Fear has a cool-down of 80/70/60 seconds.","descriptionRu":"Каждый раз, когда Выживший в радиусе вашего террора\nсмотрит на вас, они страдают от следующих эффектов:\nЗаставляет их кричать и раскрывать свою ауру.\nтебе на 2 секунды.\nВремя восстановления Phantom Fear составляет 80/70/60 секунд.","shortDescriptionRu":"Каждый раз, когда Выживший в радиусе вашего террора смотрит на вас, они страдают от следующих эффектов: Заставляет их кричать и раскрывать свою ауру. тебе на 2 секунды. Время восстановления Phantom Fear составляет 60 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_Ravenous.png":{"englishName":"Ravenous","owner":"Krasue","role":"killer","descriptionEn":"Time to feast.\"\nWhenever you hook a Survivor for the first time, Ravenous gains +1 Token, up to a maximum of 4 Tokens.\nOnce you accumulate 4 Tokens, all Survivors suffer from the following effects:\nCauses them to scream.\nInflicts the Exposed\nStatus Effect for 40/50/60 seconds.","descriptionRu":"Время пиршествовать».\nКаждый раз, когда вы впервые цепляете Выжившего, Рэвенус получает +1 жетон, максимум до 4 жетонов.\nКак только вы накопите 4 жетона, все выжившие пострадают от следующих эффектов:\nЗаставляет их кричать.\nНаносит уязвимость\nСтатусный эффект на 40/50/60 секунд.","shortDescriptionRu":"Время пиршествовать». Каждый раз, когда вы впервые цепляете Выжившего, Рэвенус получает +1 жетон, максимум до 4 жетонов. Как только вы накопите 4 жетона, все выжившие пострадают от следующих эффектов: Заставляет их кричать.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_ScourgeHookJaggedCompass.png":{"englishName":"Scourge Hook: Jagged Compass","owner":"Houndmaster","role":"killer","descriptionEn":"At the start of the Trial, 4 Hooks in the environment are changed into Scourge Hooks:\nThe Auras\nof these Scourge Hooks are highlighted in white.\nWhenever a Survivor is unhooked from a normal Hook, the following effect applies:\nThe Hook\nis converted into a Scourge Hook.\nWhenever you hook a Survivor onto a Scourge Hook, the following effect applies:\nThe Aura\nof the Generator\nwith the most progression is highlighted in yellow for 6/8/10 seconds.","descriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети:\nАуры\nиз этих Крюков Плети выделены белым цветом.\nКаждый раз, когда Выжившего отцепляют от обычного Крюка, применяется следующий эффект:\nКрюк\nпревращается в Крюк Плети.\nКаждый раз, когда вы цепляете Выжившего на Крюк Плети, применяется следующий эффект:\nАура\nГенератора\nс наибольшим прогрессом, выделяется желтым цветом на 6/8/10 секунд.","shortDescriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети: Ауры из этих Крюков Плети выделены белым цветом. Каждый раз, когда Выжившего отцепляют от обычного Крюка, применяется следующий эффект: Крюк превращается в Крюк Плети. Каждый раз, когда вы цепляете Выжившего на Крюк Плети, применяется следующий эффект: Аура Генератора с наибольшим прогрессом, выделяется желтым цветом на 10 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_WanderingEye.png":{"englishName":"Wandering Eye","owner":"Krasue","role":"killer","descriptionEn":"Whenever you start chasing a Survivor, Wandering Eye triggers the following effect:\nThe Auras\nof all other injured Survivors within 20 metres of your location are revealed to you for 5 seconds.\nWandering Eye has a cool-down of 40/35/30 seconds.","descriptionRu":"Каждый раз, когда вы начинаете преследовать Выжившего, «Блуждающий глаз» вызывает следующий эффект:\nАуры\nвсех других раненых Выживших в радиусе 20 метров от вас отображаются на 5 секунд.\nБлуждающий глаз имеет время восстановления 40/35/30 секунд.","shortDescriptionRu":"Каждый раз, когда вы начинаете преследовать Выжившего, «Блуждающий глаз» вызывает следующий эффект: Ауры всех других раненых Выживших в радиусе 20 метров от вас отображаются на 5 секунд. Блуждающий глаз имеет время восстановления 30 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_WeepingWounds.png":{"englishName":"Scourge Hook: Weeping Wounds","owner":"Общий","role":"killer","descriptionEn":"At the start of the Trial, 4 Hooks in the environment are changed into Scourge Hooks:\nThe Auras\nof these Scourge Hooks are highlighted in white.\nEach time a Survivor is unhooked from a Scourge Hook, the following effects apply:\nCauses that Survivor to suffer from the Haemorrhage\nStatus Effect for 90 seconds.\nAfter the first time that Survivor is healed back to full health, they suffer from the following effect until they are injured again by any means:\nReduces their Action speeds for Healing and Repairing by 10/13/16 %.","descriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети:\nАуры\nиз этих Крюков Плети выделены белым цветом.\nКаждый раз, когда Выжившего отцепляют от Крюка Плети, применяются следующие эффекты:\nПричины, по которым у Выжившего возникает кровотечение\nСтатусный эффект на 90 секунд.\nПосле первого восстановления полного здоровья Выжившего он страдает от следующего эффекта до тех пор, пока не получит новую травму каким-либо образом:\nСнижает скорость действий при лечении и ремонте на 10/13/16%.","shortDescriptionRu":"В начале испытания 4 крючка в окружающей среде превращаются в крючки Плети: Ауры из этих Крюков Плети выделены белым цветом. Каждый раз, когда Выжившего отцепляют от Крюка Плети, применяются следующие эффекты: Причины, по которым у Выжившего возникает кровотечение Статусный эффект на 90 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_CelestialWitness.png":{"englishName":"Celestial Witness","owner":"Judgment","role":"killer","descriptionEn":"Every 30 seconds, if the Obsession\nis 40 metres away from you, you see their aura for 2/2.5/3 seconds. Otherwise, the farthest Survivor becomes the Obsession.","descriptionRu":"Каждые 30 секунд, если Одержимость\nнаходится в 40 метрах от вас, вы видите их ауру в течение 2/2,5/3 секунд. В противном случае самый дальний Выживший становится Одержимостью.","shortDescriptionRu":"Каждые 30 секунд, если Одержимость находится в 40 метрах от вас, вы видите их ауру в течение 3 секунд. В противном случае самый дальний Выживший становится Одержимостью.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_HexHiveMind.png":{"englishName":"Hex: Hive Mind","owner":"First","role":"killer","descriptionEn":"The first time you hook any Survivor\n, a random Dull Totem\nbecomes a Hex Totem\n, provided that a Dull Totem\nremains in the Trial Grounds.\nGenerators\nare highlighted; the intensity of the generator's Auras\nreveals their repair progress.\nAs soon as a total of 4 generators have been completed in the Trial:\nAll remaining generators explode, lose 6/8/10 % progess, and start regressing.\nThe associated Hex Totem\nbecomes dull, and this perk becomes disabled for the remainder of the trial.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Первый раз, когда вы подцепляете любого Выжившего\n, случайный Тусклый тотем\nстановится шестнадцатеричным тотемом\n, при условии, что Тусклый Тотем\nостается на испытательном полигоне.\nГенераторы\nвыделены; интенсивность аур генератора\nпоказывает ход их ремонта.\nКак только в Испытании будет собрано 4 генератора:\nВсе оставшиеся генераторы взрываются, теряют 6/8/10% прогресса и начинают регрессировать.\nСоответствующий шестигранный тотем\nстановится скучным, и этот перк отключается до конца пробного периода.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Первый раз, когда вы подцепляете любого Выжившего, случайный Тусклый тотем становится шестнадцатеричным тотемом, при условии, что Тусклый Тотем остается на испытательном полигоне. Генераторы выделены; интенсивность аур генератора показывает ход их ремонта. Как только в Испытании будет собрано 4 генератора: Все оставшиеся генераторы взрываются, теряют 10% прогресса и начинают регрессировать.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_HexUnderYourThumb.png":{"englishName":"Hex: Under Your Thumb","owner":"Judgment","role":"killer","descriptionEn":"When a Survivor gains a Hook State, Hex: Under Your Thumb activates on a random Dull Totem\n:\nRunning Survivors cannot gain more than 25/20/15 % Haste\nat once.\nWhenever a running Survivor within 32 metres gains Haste, the Survivor's location is revealed to you for 4 seconds.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Когда Выживший получает состояние «Крюк», «Сглаз: Под большим пальцем» активируется на случайном Тусклом тотеме.\n:\nБегущие выжившие не могут получить более 25/20/15% скорости.\nсразу.\nКаждый раз, когда бегущий Выживший в радиусе 32 метров получает Ускорение, его местоположение открывается вам на 4 секунды.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Когда Выживший получает состояние «Крюк», «Сглаз: Под большим пальцем» активируется на случайном Тусклом тотеме.: Бегущие выжившие не могут получить более 15% скорости. сразу. Каждый раз, когда бегущий Выживший в радиусе 32 метров получает Ускорение, его местоположение открывается вам на 4 секунды.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_LayWaste.png":{"englishName":"Lay Waste","owner":"Judgment","role":"killer","descriptionEn":"Damaging a Generator\nmakes it regress +2 % faster for each Charge it has.\nThis perk has a cool-down of 55/50/45 seconds after damaging a Generator.","descriptionRu":"Повреждение генератора\nзаставляет его регрессировать на +2 % быстрее за каждый имеющийся у него заряд.\nВремя восстановления этого перка составляет 55/50/45 секунд после повреждения Генератора.","shortDescriptionRu":"Повреждение генератора заставляет его регрессировать на 2% быстрее за каждый имеющийся у него заряд. Время восстановления этого перка составляет 45 секунд после повреждения Генератора.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_Rampage.png":{"englishName":"Rampage","owner":"Slasher","role":"killer","descriptionEn":"Whenever you basic-break a Pallet\nor a Breakable Wall\n, gain a token, up to 13.\nWhenever you are blinded or Pallet-stunned, you are granted +1 % Haste\nStatus Effect for each Token this perk has for 13 seconds.\nThis perk has a cool-down of 30/25/20 seconds after being blinded or Pallet-stunned while this perk has at least 1 token.","descriptionRu":"Всякий раз, когда вы ломаете поддон\nили разрушаемая стена\n, получите жетон до 13.\nКаждый раз, когда вы ослеплены или оглушены поддоном, вы получаете +1 % к скорости.\nСтатусный эффект для каждого жетона этого перка длится 13 секунд.\nВремя восстановления этого перка составляет 30/25/20 секунд после ослепления или оглушения поддоном, пока у этого перка есть хотя бы 1 жетон.","shortDescriptionRu":"Всякий раз, когда вы ломаете поддон или разрушаемая стена, получите жетон до 13. Каждый раз, когда вы ослеплены или оглушены поддоном, вы получаете +1% к скорости. Статусный эффект для каждого жетона этого перка длится 13 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_ScaredToDeath.png":{"englishName":"Hex: Scared to Death","owner":"Slasher","role":"killer","descriptionEn":"When you Hook 3 different Survivors, Hex: Scared to Death activates on a random Dull Totem\nand triggers its effect:\nBasic-breaking a Pallet\nduring a chase causes all Survivors within 13 metres to scream and gain -11/-12/-13 % Hindered\nStatus Effect for 3 seconds.\nThe Hex Effects persist until the Hex Totem is either blessed or cleansed by a Survivor, disabling it for the remainder of the Trial.","descriptionRu":"Когда вы ловите на крючок 3 разных выживших, на случайном унылом тотеме активируется «Сглаз: напуган до смерти».\nи вызывает его эффект:\nБазовое разрушение поддона\nво время погони заставляет всех Выживших в радиусе 13 метров кричать и получать -11/-12/-13 % замедления.\nСтатусный эффект на 3 секунды.\nЭффекты порчи сохраняются до тех пор, пока Выживший не благословит или не очистит Тотем порчи, отключив его на оставшуюся часть Испытания.","shortDescriptionRu":"Когда вы ловите на крючок 3 разных выживших, на случайном унылом тотеме активируется «Сглаз: напуган до смерти». и вызывает его эффект: Базовое разрушение поддона во время погони заставляет всех Выживших в радиусе 13 метров кричать и получать -11/-12/-13% замедления. Статусный эффект на 3 секунды.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_SecretProject.png":{"englishName":"Secret Project","owner":"First","role":"killer","descriptionEn":"Whenever a Totem\nis blessed or cleansed, a random unblocked generator becomes blocked for 20/25/30 seconds.\nWhenever any number of Generators\nbecome blocked, you gain Undetectable\nStatus Effect for 30 seconds.","descriptionRu":"Всякий раз, когда тотем\nблагословлен или очищен, случайный разблокированный генератор блокируется на 20/25/30 секунд.\nВсякий раз, когда любое количество Генераторов\nбудучи заблокированным, вы получаете Необнаружимый\nСтатусный эффект на 30 секунд.","shortDescriptionRu":"Всякий раз, когда тотем благословлен или очищен, случайный разблокированный генератор блокируется на 30 секунд. Всякий раз, когда любое количество Генераторов будучи заблокированным, вы получаете Необнаружимый Статусный эффект на 30 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_SilentShadow.png":{"englishName":"Silent Shadow","owner":"Slasher","role":"killer","descriptionEn":"When you hook a Survivor, you are granted Undetectable\nStatus Effect for 11/12/13 seconds.\nWhen the Exit Gates\nare powered, you are granted Undetectable\nfor the rest of the Trial.","descriptionRu":"Когда вы цепляете Выжившего, вам предоставляется Необнаружимость.\nСтатусный эффект на 11/12/13 секунд.\nКогда выходные ворота\nвключены, вам предоставляется Необнаружимый\nдо конца Суда.","shortDescriptionRu":"Когда вы цепляете Выжившего, вам предоставляется Необнаружимость. Статусный эффект на 13 секунд. Когда выходные ворота включены, вам предоставляется Необнаружимый до конца Суда.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_ToyWithThem.png":{"englishName":"Keep Them Waiting","owner":"Общий","role":"killer","descriptionEn":"Damaging any Survivor other than the Obsession\nwith a Basic Attack causes Keep Them Waiting to gain +1 Token, up to a maximum of 6/7/8 Tokens.\nDamaging the Obsession with either a Basic or Special Attack causes Keep Them Waiting to lose -2 Tokens:\nGrants a stack-able -5 % per Token Cool-down time reduction on successful Basic Attacks, up to a maximum of 30/35/40 %.\nKeep Them Waiting freezes its current Token Count once the Obsession is sacrificed or killed.\nYou can only be obsessed with one Survivor at a time.","descriptionRu":"Нанесение урона любому Выжившему, кроме Одержимости\nс помощью базовой атаки заставляет «Заставить их ждать» получить +1 жетон, максимум до 6/7/8 жетонов.\nПри нанесении урона Одержимости базовой или специальной атакой команда «Заставь их ждать» теряет -2 жетона:\nПредоставляет суммируемое сокращение времени восстановления на -5 % за каждый жетон при успешных базовых атаках, максимум до 30/35/40 %.\n«Заставь их ждать» замораживает текущее количество жетонов после того, как Одержимость будет принесена в жертву или убита.\nОдновременно вы можете быть одержимы только одним Выжившим.","shortDescriptionRu":"Нанесение урона любому Выжившему, кроме Одержимости с помощью базовой атаки заставляет «Заставить их ждать» получить +1 жетон, максимум до 8 жетонов. При нанесении урона Одержимости базовой или специальной атакой команда «Заставь их ждать» теряет -2 жетона: Предоставляет суммируемое сокращение времени восстановления на -5% за каждый жетон при успешных базовых атаках, максимум до 40%.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_TurnBackTheClock.png":{"englishName":"Turn Back the Clock","owner":"First","role":"killer","descriptionEn":"After hooking a Survivor, for 40/50/60 seconds, press the Active Ability button to make a target generator within 20 meters explode, lose -10 % progress, and start regressing.","descriptionRu":"Подцепив Выжившего, нажимайте кнопку «Активная способность» в течение 40/50/60 секунд, чтобы взорвать целевой генератор в радиусе 20 метров, потерять -10 % прогресса и начать регрессировать.","shortDescriptionRu":"Подцепив Выжившего, нажимайте кнопку «Активная способность» в течение 60 секунд, чтобы взорвать целевой генератор в радиусе 20 метров, потерять -10% прогресса и начать регрессировать.","upcomingPatch":false},"assets/perks/iconPerks_AceInTheHole.png":{"englishName":"Ace in the Hole","owner":"Ace Visconti","role":"survivor","descriptionEn":"Causes all regular Items\nyou retrieve from a Chest\nto come equipped with 1 to 2 Add-ons\n:\nFirst Slot: 100 % chance to be equipped with an Add-on of Visceral Rarity or lower.\nSecond Slot: 50/75/100 % chance to be equipped with an Add-on of Uncommon Rarity or lower.\nAce in the Hole prevents any attached Add-ons on your currently held Item to be consumed upon escaping the Trial.","descriptionRu":"Вызывает все обычные предметы\nвы получаете из сундука\nиметь от 1 до 2 надстроек\n:\nПервый слот: 100 % шанс получить надстройку интуитивной редкости или ниже.\nВторой слот: 50/75/100 % шанс получить дополнение необычной редкости или ниже.\nAce in the Hole предотвращает использование любых прикрепленных к вашему текущему предмету дополнений при выходе из Испытания.","shortDescriptionRu":"Вызывает все обычные предметы вы получаете из сундука иметь от 1 до 2 надстроек: Первый слот: 100% шанс получить надстройку интуитивной редкости или ниже. Второй слот: 100% шанс получить дополнение необычной редкости или ниже. Ace in the Hole предотвращает использование любых прикрепленных к вашему текущему предмету дополнений при выходе из Испытания.","upcomingPatch":false},"assets/perks/iconPerks_Adrenaline.png":{"englishName":"Adrenaline","owner":"Meg Thomas","role":"survivor","descriptionEn":"Once the Exit Gates\nare powered, Adrenaline activates and triggers the following effects:\nHeals you to the next Health State\n.\nGrants a +50 % Haste\nStatus Effect for 4 seconds.\nAdrenaline can be used while Exhausted and ignores an existing Status Effect.\nAdrenaline causes the Exhausted\nStatus Effect for 60/50/40 seconds after use.","descriptionRu":"Однажды Выходные Ворота\nактивируются, Адреналин активируется и вызывает следующие эффекты:\nИсцеляет вас до следующего состояния здоровья\n.\nДает +50 % скорости.\nСтатусный эффект на 4 секунды.\nАдреналин можно использовать, когда он истощен, и он игнорирует существующий эффект статуса.\nАдреналин вызывает истощение\nСтатусный эффект в течение 60/50/40 секунд после использования.","shortDescriptionRu":"Однажды Выходные Ворота активируются, Адреналин активируется и вызывает следующие эффекты: Исцеляет вас до следующего состояния здоровья. Дает +50% скорости. Статусный эффект на 4 секунды.","upcomingPatch":false},"assets/perks/iconPerks_Aftercare.png":{"englishName":"Aftercare","owner":"Jeff Johansen","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nYou see the Auras\nof the 1/2/3 most recent Survivor(s) that helped you or vice versa:\nRescued from a Hook\n.\nCompleted a Healing action on.\nThey also see your Aura.\nAftercare resets its effects when you are hooked by the Killer.\nOil work to honour my best buddies who happen to be the best musicians I know. Their first album is still my favourite. It got me through a dark time in my life.\" — Jeff, oil on canvas, 16x16","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nВы видите ауры\nиз 1/2/3 последних Выживших, которые помогли вам, или наоборот:\nСпасенный с крючка\n.\nЗавершено действие «Исцеление».\nОни также видят вашу ауру.\nЭффекты Aftercare сбрасываются, когда Убийца захватывает вас.\nРабота маслом в честь моих лучших друзей, которые оказались лучшими музыкантами, которых я знаю. Их первый альбом до сих пор мой любимый. Это помогло мне пережить темные времена в моей жизни». — Джефф, холст, масло, 16х16.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Вы видите ауры из 3 последних Выживших, которые помогли вам, или наоборот: Спасенный с крючка. Завершено действие «Исцеление». Они также видят вашу ауру.","upcomingPatch":false},"assets/perks/iconPerks_Alert.png":{"englishName":"Alert","owner":"Feng Min","role":"survivor","descriptionEn":"Whenever the Killer performs the Break or Damage Action, Alert triggers:\nTheir Aura\nis revealed to you for 3/4/5 seconds.","descriptionRu":"Каждый раз, когда убийца выполняет действие «Разрушение» или «Повреждение», срабатывает оповещение:\nИх аура\nоткрывается вам на 3/4/5 секунды.","shortDescriptionRu":"Каждый раз, когда убийца выполняет действие «Разрушение» или «Повреждение», срабатывает оповещение: Их аура открывается вам на 5 секунды.","upcomingPatch":false},"assets/perks/iconPerks_AnyMeansNecessary.png":{"englishName":"Any Means Necessary","owner":"Yui Kimura","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof dropped Pallets\nin the environment are revealed to you.\nWhile standing next to a dropped Pallet, press and hold the Active Ability button to trigger the following effect:\nResets the Pallet to its upright position over 5/4/3 seconds.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nупавших поддонов\nв окружающей среде открываются вам.\nСтоя рядом с упавшим поддоном, нажмите и удерживайте кнопку «Активная способность», чтобы вызвать следующий эффект:\nВозвращает поддон в вертикальное положение за 5/4/3 секунды.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры упавших поддонов в окружающей среде открываются вам. Стоя рядом с упавшим поддоном, нажмите и удерживайте кнопку «Активная способность», чтобы вызвать следующий эффект: Возвращает поддон в вертикальное положение за 3 секунды.","upcomingPatch":false},"assets/perks/iconPerks_Appraisal.png":{"englishName":"Appraisal","owner":"%C3%89lodie Rakoto","role":"survivor","descriptionEn":"Start the Trial with 4 Tokens.\nWhile standing next to an unlocked and empty Chest\n, press and hold the Interaction button to perform the Rummage action:\nGrants the ability to retrieve an extra Item\nfrom that Chest.\nThis consumes -1 Token and is limited to twice per Chest.\nIncreases the Rummaging speed by 40/60/80 %.","descriptionRu":"Начните пробную версию с 4 жетонами.\nСтоя рядом с незапертым и пустым сундуком.\n, нажмите и удерживайте кнопку «Взаимодействие», чтобы выполнить действие «Поиск»:\nПредоставляет возможность получить дополнительный предмет.\nиз этого сундука.\nНа это расходуется -1 жетон, но не более двух раз за сундук.\nУвеличивает скорость рытья на 40/60/80 %.","shortDescriptionRu":"Начните пробную версию с 4 жетонами. Стоя рядом с незапертым и пустым сундуком., нажмите и удерживайте кнопку «Взаимодействие», чтобы выполнить действие «Поиск»: Предоставляет возможность получить дополнительный предмет. из этого сундука.","upcomingPatch":false},"assets/perks/iconPerks_Autodidact.png":{"englishName":"Autodidact","owner":"Adam Francis","role":"survivor","descriptionEn":"Succeeding a Skill Check\nwhile healing another Survivor grants +1 Token, up to a maximum of 3/4/5 Tokens:\nSuppresses Great Healing Skill Checks.\nCauses Good Healing Skill Checks to grant Healing progress based on the number of accumulated Tokens:\n0 Tokens: -15 %.\n1 Token: +0 %.\n2 Tokens: +15 %.\n3 Tokens: +30 % (limit of Tier I).\n4 Tokens: +45 % (limit of Tier II).\n5 Tokens: +60 % (limit of Tier III).\nAutodidact is inactive when healing using a Med-Kit\n.","descriptionRu":"Успешная проверка навыков\nпри исцелении другого Выжившего дается +1 жетон, максимум до 3/4/5 жетонов:\nПодавляет проверки навыков великого исцеления.\nЗаставляет хорошие проверки навыков исцеления предоставлять прогресс исцеления в зависимости от количества накопленных жетонов:\n0 жетонов: -15 %.\n1 жетон: +0 %.\n2 жетона: +15 %.\n3 жетона: +30 % (лимит I уровня).\n4 жетона: +45 % (лимит II уровня).\n5 жетонов: +60 % (лимит III уровня).\nАвтодидакт неактивен при лечении с помощью аптечки.\n.","shortDescriptionRu":"Успешная проверка навыков при исцелении другого Выжившего дается +1 жетон, максимум до 5 жетонов: Подавляет проверки навыков великого исцеления. Заставляет хорошие проверки навыков исцеления предоставлять прогресс исцеления в зависимости от количества накопленных жетонов: 0 жетонов: -15%. 1 жетон: +0%.","upcomingPatch":false},"assets/perks/iconPerks_babySitter.png":{"englishName":"Babysitter","owner":"Steve Harrington","role":"survivor","descriptionEn":"Whenever you unhook another Survivor, you benefit from the following effect:\nThe Aura\nof the Killer is revealed to you for 8 seconds.\nThe unhooked Survivor benefits from the following effects instead for 20/25/30 seconds:\nSuppresses the creation of their Scratch Marks\nand Pools of Blood\n.\nIncreases the strength of their Haste\nStatus Effect by +10 %.","descriptionRu":"Каждый раз, когда вы отцепляете другого Выжившего, вы получаете следующий эффект:\nАура\nУбийцы открываются вам на 8 секунд.\nВместо этого на выжившего, отцепившегося от крюка, в течение 20/25/30 секунд действуют следующие эффекты:\nПодавляет создание царапин.\nи лужи крови\n.\nУвеличивает силу их скорости.\nЭффект статуса на +10 %.","shortDescriptionRu":"Каждый раз, когда вы отцепляете другого Выжившего, вы получаете следующий эффект: Аура Убийцы открываются вам на 8 секунд. Вместо этого на выжившего, отцепившегося от крюка, в течение 30 секунд действуют следующие эффекты: Подавляет создание царапин. и лужи крови.","upcomingPatch":false},"assets/perks/iconPerks_BackgroundPlayer.png":{"englishName":"Background Player","owner":"Renato Lyra","role":"survivor","descriptionEn":"Whenever the Killer picks up any other Survivor in the Dying State\n, Background Player activates for 10 seconds.\nWhile active, starting to run triggers the following effect:\nGrants a +50 % Haste\nStatus Effect for 5 seconds.\nBackground Player cannot be used while Exhausted.\nBackground Player causes the Exhausted\nStatus Effect for 30/25/20 seconds after use.","descriptionRu":"Каждый раз, когда Убийца забирает любого другого Выжившего в Умирающем Государстве.\n, Фоновый проигрыватель активируется на 10 секунд.\nПока он активен, начало бега вызывает следующий эффект:\nДает +50 % скорости.\nСтатусный эффект на 5 секунд.\nФоновый проигрыватель нельзя использовать, пока вы измотаны.\nФоновый игрок вызывает усталость\nСтатусный эффект в течение 30/25/20 секунд после использования.","shortDescriptionRu":"Каждый раз, когда Убийца забирает любого другого Выжившего в Умирающем Государстве., Фоновый проигрыватель активируется на 10 секунд. Пока он активен, начало бега вызывает следующий эффект: Дает +50% скорости. Статусный эффект на 5 секунд.","upcomingPatch":false},"assets/perks/iconPerks_BalancedLanding.png":{"englishName":"Balanced Landing","owner":"Nea Karlsson","role":"survivor","descriptionEn":"While falling from height, you benefit from the following effects:\nSuppresses all noises related to falling and landing.\nReduces the duration of the Stagger upon landing by -75 %.\nGrants a +50 % Haste\nStatus Effect for 3 seconds.\nBalanced Landing cannot be used while Exhausted.\nBalanced Landing causes the Exhausted\nStatus Effect for 60/50/40 seconds after use.","descriptionRu":"Падая с высоты, вы получаете следующие эффекты:\nПодавляет все шумы, связанные с падением и приземлением.\nУменьшает длительность ошеломления при приземлении на -75 %.\nДает +50 % скорости.\nСтатусный эффект на 3 секунды.\nСбалансированное приземление нельзя использовать, пока вы измотаны.\nСбалансированное приземление вызывает истощение\nСтатусный эффект в течение 60/50/40 секунд после использования.","shortDescriptionRu":"Падая с высоты, вы получаете следующие эффекты: Подавляет все шумы, связанные с падением и приземлением. Уменьшает длительность ошеломления при приземлении на -75%. Дает +50% скорости.","upcomingPatch":false},"assets/perks/iconPerks_BardicInspiration.png":{"englishName":"Bardic Inspiration","owner":"Troupe","role":"survivor","descriptionEn":"It's time to give your audience a show.\nWill you bring the house down or will you choke?\nPress the Active Ability button while standing and motionless to enter the Performance interaction that lasts up to 15 seconds and empowers other Survivors within 16 metres of your location.\nThe empowering effect depends on the result of you rolling a d20 and lasts for 90 seconds after completing the Performance:\n1: You scream, but without notifying the Killer.\n2 - 10: Skill Checks\ngrant +1 % Progression.\n11 - 19: Skill Checks grant +2 % Progression.\n20: Skill Checks grant +3 % Progression.\nBardic Inspiration has a cool-down of 110/100/90 seconds after completing the Performance or cancelling it.","descriptionRu":"Пришло время устроить вашей аудитории шоу.\nТы обрушишь дом или задохнешься?\nНажмите кнопку «Активная способность», стоя и неподвижно, чтобы войти в действие «Представление», которое длится до 15 секунд и усиливает других выживших в радиусе 16 метров от вашего местоположения.\nЭффект усиления зависит от результата броска d20 и длится 90 секунд после завершения Представления:\n1: Вы кричите, но не уведомляете Убийцу.\n2–10: Проверки навыков\nпредоставить +1 % прогресса.\n11–19: Проверки навыков дают +2 % прогресса.\n20: Проверки навыков дают +3 % прогресса.\nВремя восстановления «Вдохновения Барда» составляет 110/100/90 секунд после завершения выступления или его отмены.","shortDescriptionRu":"Пришло время устроить вашей аудитории шоу. Ты обрушишь дом или задохнешься? Нажмите кнопку «Активная способность», стоя и неподвижно, чтобы войти в действие «Представление», которое длится до 15 секунд и усиливает других выживших в радиусе 16 метров от вашего местоположения.","upcomingPatch":false},"assets/perks/iconPerks_BetterThanNew.png":{"englishName":"Better than New","owner":"Rebecca Chambers","role":"survivor","descriptionEn":"Patients leave your care reinvigorated.\"\nCompleting a Healing action on another Survivor grants them the following benefits until they receive damage again:\nIncreases their Action speeds for Blessing, Cleansing, Healing, and Unlocking by 40/45/50 %.","descriptionRu":"Пациенты покидают ваше отделение с новыми силами».\nВыполнение Исцеляющего действия на другом Выжившем дает ему следующие преимущества, пока он снова не получит урон:\nУвеличивает скорость действий для Благословения, Очищения, Исцеления и Разблокировки на 40/45/50 %.","shortDescriptionRu":"Пациенты покидают ваше отделение с новыми силами». Выполнение Исцеляющего действия на другом Выжившем дает ему следующие преимущества, пока он снова не получит урон: Увеличивает скорость действий для Благословения, Очищения, Исцеления и Разблокировки на 50%.","upcomingPatch":true},"assets/perks/iconPerks_betterTogether.png":{"englishName":"Better Together","owner":"Nancy Wheeler","role":"survivor","descriptionEn":"While repairing any Generator\n, you and the other Survivors benefit from the following primary effect:\nThe Aura\nof that Generator is revealed to all Survivors and highlighted in yellow.\nWhenever the Killer downs another Survivor while you are repairing, you benefit from the following secondary effect:\nThe Auras of all Survivors are revealed to you for 20/25/30 seconds.","descriptionRu":"При ремонте любого генератора\n, вы и другие Выжившие получаете следующий основной эффект:\nАура\nИнформация об этом Генераторе видна всем Выжившим и выделена желтым цветом.\nКаждый раз, когда Убийца сбивает другого Выжившего, пока вы ремонтируете, вы получаете следующий вторичный эффект:\nАуры всех Выживших открываются вам на 20/25/30 секунд.","shortDescriptionRu":"При ремонте любого генератора, вы и другие Выжившие получаете следующий основной эффект: Аура Информация об этом Генераторе видна всем Выжившим и выделена желтым цветом. Каждый раз, когда Убийца сбивает другого Выжившего, пока вы ремонтируете, вы получаете следующий вторичный эффект: Ауры всех Выживших открываются вам на 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_BiteTheBullet.png":{"englishName":"Bite the Bullet","owner":"Leon Scott Kennedy","role":"survivor","descriptionEn":"Pain hurts you as much as anyone, but you would prefer others do not know that.\nWhen healing yourself or another Survivor, you benefit from the following effects:\nSuppresses all noises related to Healing and Grunts of Pain.\nFailed Healing Skill Checks do not trigger a Loud Noise Notification.\nReduces the Penalty to 3/2/1 % of the total Progression.","descriptionRu":"Боль ранит вас не меньше, чем кого-либо другого, но вы бы предпочли, чтобы другие этого не знали.\nИсцеляя себя или другого Выжившего, вы получаете следующие эффекты:\nПодавляет все шумы, связанные с исцелением и ворчанием боли.\nНеудачные проверки навыков исцеления не вызывают громкое уведомление.\nСнижает штраф до 3/2/1 % от общего прогресса.","shortDescriptionRu":"Боль ранит вас не меньше, чем кого-либо другого, но вы бы предпочли, чтобы другие этого не знали. Исцеляя себя или другого Выжившего, вы получаете следующие эффекты: Подавляет все шумы, связанные с исцелением и ворчанием боли. Неудачные проверки навыков исцеления не вызывают громкое уведомление.","upcomingPatch":false},"assets/perks/iconPerks_BlastMine.png":{"englishName":"Blast Mine","owner":"Jill Valentine","role":"survivor","descriptionEn":"After repairing Generators\nfor the equivalent of 40 % of Progression, Blast Mine activates.\nWhile active, press the Active Ability button while standing next to a Generator to install a trap to it with a countdown of 100/110/120 seconds:\nTrips half-way through the Killer attempting to damage the Trapped Generator:\nStuns the Killer for 4 seconds.\nBlinds all Players within 12.5 metres of the Trapped Generator.\nThe trap is deactivated after its countdown has elapsed or it is tripped.\nThe Auras\nof Trapped Generators are revealed to all Survivors in yellow.","descriptionRu":"После ремонта генераторов\nза эквивалент 40 % прогресса активируется «Взрывная мина».\nПока активно, нажмите кнопку «Активная способность», стоя рядом с Генератором, чтобы установить на него ловушку с обратным отсчетом 100/110/120 секунд:\nСпотыкается на полпути через Убийцу, пытающегося повредить застрявший генератор:\nОглушает Убийцу на 4 секунды.\nОслепляет всех игроков в радиусе 12,5 метров от застрявшего генератора.\nЛовушка деактивируется после истечения ее обратного отсчета или срабатывания.\nАуры\nЗастрявшие генераторы показаны всем выжившим желтым цветом.","shortDescriptionRu":"После ремонта генераторов за эквивалент 40% прогресса активируется «Взрывная мина». Пока активно, нажмите кнопку «Активная способность», стоя рядом с Генератором, чтобы установить на него ловушку с обратным отсчетом 120 секунд: Спотыкается на полпути через Убийцу, пытающегося повредить застрявший генератор: Оглушает Убийцу на 4 секунды. Ослепляет всех игроков в радиусе 12,5 метров от застрявшего генератора.","upcomingPatch":false},"assets/perks/iconPerks_BloodPact.png":{"englishName":"Blood Pact","owner":"Cheryl Mason","role":"survivor","descriptionEn":"It is as if a latent part of yourself has awakened.\nYou feel like you can reach out beyond yourself for assistance.\nWhen either you or the Obsession\nbecome injured by any means, Blood Pact activates:\nYour Auras\nare constantly revealed to one another.\nCompleting a Healing Action on the Obsession or having them complete one on yourself, grants both of you a 5/6/7 % Haste\nStatus Effect.\nThis effect lasts for as long as you both remain within 16 metres of one another.\nIf you are the Obsession, getting Hooked will cause an another Survivor to become the Obsession.\nReduces your chance of becoming the initial Obsession by reducing the default value by -100 %.\nThe Killer can only be obsessed with one Survivor at a time.","descriptionRu":"Как будто пробудилась скрытая часть вас самих.\nВы чувствуете, что можете обратиться за помощью за пределами себя.\nКогда либо ты, либо Одержимость\nполучить травму любым способом, активируется Кровавый Договор:\nВаши ауры\nпостоянно открываются друг другу.\nЗавершение лечебного действия на Одержимости или его выполнение на себе дает вам обоим 5/6/7% скорости.\nЭффект статуса.\nЭтот эффект длится до тех пор, пока вы оба находитесь в пределах 16 метров друг от друга.\nЕсли вы — Одержимость, попадание на крючок приведет к тому, что другой Выживший станет Одержимостью.\nУменьшает ваш шанс стать первоначальной одержимостью за счет уменьшения значения по умолчанию на -100 %.\nУбийца может быть одержим только одним Выжившим одновременно.","shortDescriptionRu":"Как будто пробудилась скрытая часть вас самих. Вы чувствуете, что можете обратиться за помощью за пределами себя. Когда либо ты, либо Одержимость получить травму любым способом, активируется Кровавый Договор: Ваши ауры постоянно открываются друг другу.","upcomingPatch":true},"assets/perks/iconPerks_BloodRush.png":{"englishName":"Blood Rush","owner":"Renato Lyra","role":"survivor","descriptionEn":"After being unhooked by any means, Blood Rush activates for 40/50/60 seconds.\nWhile active, press the Active Ability button to trigger the following effect:\nInstantly recover from an existing Exhausted\nStatus Effect.\nBlood Rush does not cause the Exhausted Status Effect.\nBlood Rush is deactivated prematurely when performing a Conspicuous Action.\nBlood Rush deactivates after use and is disabled for the remainder of the Trial once the Exit Gates\nare powered.","descriptionRu":"После того, как вас отцепили любым способом, Blood Rush активируется на 40/50/60 секунд.\nПока активно, нажмите кнопку «Активная способность», чтобы активировать следующий эффект:\nМгновенно восстановиться после существующего состояния «Исчерпано»\nЭффект статуса.\nПрилив крови не вызывает эффекта истощения.\nПрилив крови деактивируется преждевременно при выполнении заметного действия.\n«Кровавый прилив» деактивируется после использования и отключается до конца испытания после выхода из ворот.\nпитаются.","shortDescriptionRu":"После того, как вас отцепили любым способом, Blood Rush активируется на 60 секунд. Пока активно, нажмите кнопку «Активная способность», чтобы активировать следующий эффект: Мгновенно восстановиться после существующего состояния «Исчерпано» Эффект статуса. Прилив крови не вызывает эффекта истощения.","upcomingPatch":false},"assets/perks/iconPerks_BoilOver.png":{"englishName":"Boil Over","owner":"Kate Denson","role":"survivor","descriptionEn":"You are a battler and do everything to escape a foe's grasp.\nWhile being carried by the Killer, the following effects apply:\nIncreases the strength of the Struggle Effects on the Killer from your Wiggling by 60/70/80 %.\nSuppresses the ability of the Killer to read the Auras\nof all Hooks\nwithin 16 metres.\nGrants +33 % of your current Wiggle progression upon landing, if the Killer drops from height.\nSwing to be free,\nYour hands just can't keep ahold of me.\" — Kate Denson's \"Boil Over\"","descriptionRu":"Вы боец ​​и делаете все, чтобы вырваться из рук врага.\nПока его несет Убийца, применяются следующие эффекты:\nУвеличивает силу эффектов борьбы на убийце от вашего покачивания на 60/70/80%.\nПодавляет способность Убийцы читать ауры.\nиз всех крючков\nв пределах 16 метров.\nДает +33 % к текущему прогрессу Покачивания при приземлении, если Убийца падает с высоты.\nКачайтесь, чтобы быть свободным,\nТвои руки просто не могут меня удержать», — Кейт Денсон «Boil Over».","shortDescriptionRu":"Вы боец ​​и делаете все, чтобы вырваться из рук врага. Пока его несет Убийца, применяются следующие эффекты: Увеличивает силу эффектов борьбы на убийце от вашего покачивания на 80%. Подавляет способность Убийцы читать ауры.","upcomingPatch":false},"assets/perks/iconPerks_Bond.png":{"englishName":"Bond","owner":"Dwight Fairfield","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof all other Survivors are revealed to you within 20/28/36 metres.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nвсех остальных Выживших открываются вам в радиусе 20/28/36 метров.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры всех остальных Выживших открываются вам в радиусе 36 метров.","upcomingPatch":false},"assets/perks/iconPerks_BoonCircleOfHealing.png":{"englishName":"Boon: Circle of Healing","owner":"Mikaela Reid","role":"survivor","descriptionEn":"A Boon that offers comfort amidst the terror.\nPress and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nIncreases the Altruistic Healing speeds by 50/75/100 % when not using a Med-Kit\n.\nIf a Survivor is injured, their Aura\nis revealed to all other Survivors.\nSurvivors can only be affected by one instance of Boon: Circle of Healing at a time.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Дар, который предлагает утешение среди ужаса.\nНажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nУвеличивает скорость альтруистического исцеления на 50/75/100 %, если не использовать аптечку.\n.\nЕсли Выживший ранен, его Аура\nраскрывается всем остальным Выжившим.\nНа выживших одновременно может воздействовать только один экземпляр Дара: Круг исцеления.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Дар, который предлагает утешение среди ужаса. Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Увеличивает скорость альтруистического исцеления на 100%, если не использовать аптечку..","upcomingPatch":false},"assets/perks/iconPerks_BoonShadowStep.png":{"englishName":"Boon: Shadow Step","owner":"Mikaela Reid","role":"survivor","descriptionEn":"A Boon that conceals the truth.\nPress and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nScratch Marks\nare suppressed.\nAuras\nare hidden from The Killer.\nBoth effects linger for 2/3/4 seconds after leaving the Boon Totem's range.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Дар, скрывающий правду.\nНажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nЦарапины\nподавляются.\nАуры\nскрыты от Убийцы.\nОба эффекта сохраняются в течение 2/3/4 секунд после выхода из зоны действия Тотема Благодати.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Дар, скрывающий правду. Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Царапины подавляются.","upcomingPatch":false},"assets/perks/iconPerks_BorrowedTime.png":{"englishName":"Borrowed Time","owner":"Bill Overbeck","role":"survivor","descriptionEn":"Whenever you gain Deep Wound\nwhile you have Endurance\nStatus Effect, you passively mend yourself over a period of 40/35/30 seconds.","descriptionRu":"Всякий раз, когда вы получаете Глубокую рану\nпока у тебя есть выносливость\nЭффект статуса: вы пассивно лечите себя в течение 40/35/30 секунд.","shortDescriptionRu":"Всякий раз, когда вы получаете Глубокую рану пока у тебя есть выносливость Эффект статуса: вы пассивно лечите себя в течение 30 секунд.","upcomingPatch":true},"assets/perks/iconPerks_BotanyKnowledge.png":{"englishName":"Botany Knowledge","owner":"Claudette Morel","role":"survivor","descriptionEn":"You benefit from the following permanent effect:\nIncreases your Healing speed by 30/40/50 %.","descriptionRu":"Вы получаете следующий постоянный эффект:\nУвеличивает скорость лечения на 30/40/50%.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Увеличивает скорость лечения на 50%.","upcomingPatch":false},"assets/perks/iconPerks_Breakdown.png":{"englishName":"Breakdown","owner":"Jeff Johansen","role":"survivor","descriptionEn":"After you are unhooked by any means, Breakdown triggers its effects:\nInstantly breaks that Hook\n.\nIncreases its Auto-Repair timer to 180 seconds.\nThe Aura\nof the Killer is revealed to you for 4/5/6 seconds.\nHere's a sketch/painting on a piece of wood I saw by the side of this road. I felt like it got a story to tell. And it didn't waste its second chance.\" — Jeff, ink and oil wash on slice of wood, 12x16","descriptionRu":"После того, как вас каким-либо образом отцепили, Breakdown активирует свои эффекты:\nМгновенно ломает этот крючок\n.\nУвеличивает таймер автоматического ремонта до 180 секунд.\nАура\nУбийцы открываются вам на 4/5/6 секунд.\nВот эскиз/рисунок на куске дерева, который я увидел на обочине дороги. Я чувствовал, что этому есть что рассказать. И он не упустил свой второй шанс». — Джефф, тушь и масло на куске дерева, 12х16.","shortDescriptionRu":"После того, как вас каким-либо образом отцепили, Breakdown активирует свои эффекты: Мгновенно ломает этот крючок. Увеличивает таймер автоматического ремонта до 180 секунд. Аура Убийцы открываются вам на 6 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Breakout.png":{"englishName":"Breakout","owner":"Yui Kimura","role":"survivor","descriptionEn":"While within 5 metres of the Killer carrying another Survivor, the following effects apply:\nGrants you a 6/8/10 % Haste\nStatus Effect.\nIncreases the Wiggling speed of the carried Survivor by +25 %.\nSurvivors can only be affected by one instance of Breakout at a time.","descriptionRu":"Находясь в пределах 5 метров от Убийцы, несущего другого Выжившего, применяются следующие эффекты:\nДает вам 6/8/10% скорости.\nЭффект статуса.\nУвеличивает скорость покачивания переносимого Выжившего на +25 %.\nНа выживших одновременно может воздействовать только один экземпляр «Прорыва».","shortDescriptionRu":"Находясь в пределах 5 метров от Убийцы, несущего другого Выжившего, применяются следующие эффекты: Дает вам 10% скорости. Эффект статуса. Увеличивает скорость покачивания переносимого Выжившего на 25%.","upcomingPatch":false},"assets/perks/iconPerks_BuckleUp.png":{"englishName":"Buckle Up","owner":"Ash Williams","role":"survivor","descriptionEn":"Whenever you are healing a dying Survivor, Buckle Up activates:\nDuring the Healing action, you and the dying Survivor benefit from the following primary effect:\nThe Aura\nof the Killer is revealed to you both.\nAfter completing the Healing action, the other Survivor benefits from the following secondary effects for 3/4/5 seconds:\nSuppresses the creation of their Scratch Marks\n.\nGrants them a +50 % Haste\nStatus Effect.\nBuckle Up does not cause the Exhausted Status Effect.","descriptionRu":"Каждый раз, когда вы лечите умирающего Выжившего, активируется функция «Пристегнитесь»:\nВо время действия «Исцеление» вы и умирающий Выживший получаете следующий основной эффект:\nАура\nУбийца откроется вам обоим.\nПосле завершения действия «Исцеление» другой Выживший получает следующие вторичные эффекты в течение 3/4/5 секунд:\nПодавляет создание царапин.\n.\nДает им +50 % скорости.\nЭффект статуса.\n«Пристегнитесь» не вызывает эффекта «Усталость».","shortDescriptionRu":"Каждый раз, когда вы лечите умирающего Выжившего, активируется функция «Пристегнитесь»: Во время действия «Исцеление» вы и умирающий Выживший получаете следующий основной эффект: Аура Убийца откроется вам обоим. После завершения действия «Исцеление» другой Выживший получает следующие вторичные эффекты в течение 5 секунд: Подавляет создание царапин.. Дает им +50% скорости.","upcomingPatch":false},"assets/perks/iconPerks_BuiltToLast.png":{"englishName":"Built to Last","owner":"Felix Richter","role":"survivor","descriptionEn":"While hiding inside a Locker\nwith a depleted Item\nequipped, Built to Last triggers the following effect after 12/10/8 seconds:\nRecharges the Item to one of the following percentages:\nFirst time: 99 %.\nSecond time: 66 %.\nThird time: 33 %.\nBuilt to Last is disabled for the remainder of the Trial after triggering its effect for the third time.","descriptionRu":"Прячась в шкафчике\nс исчерпанным товаром\nПри экипировке «Построенные навечно» через 12/10/8 секунд активируется следующий эффект:\nПерезаряжает предмет до одного из следующих процентов:\nПервый раз: 99 %.\nВторой раз: 66 %.\nТретий раз: 33 %.\nСпособность «Построено навечно» отключается до конца Испытания после срабатывания его эффекта в третий раз.","shortDescriptionRu":"Прячась в шкафчике с исчерпанным товаром При экипировке «Построенные навечно» через 8 секунд активируется следующий эффект: Перезаряжает предмет до одного из следующих процентов: Первый раз: 99%. Второй раз: 66%. Третий раз: 33%.","upcomingPatch":false},"assets/perks/iconPerks_CalmSpirit.png":{"englishName":"Calm Spirit","owner":"Jake Park","role":"survivor","descriptionEn":"You experience the following effects during a Trial:\nNearby Crows\nno longer fly off and alert others to your presence, unless you come within touching distance.\nSuppresses the urge to scream from any cause at all times.\nSuppresses all noises related to interacting with the following Props:\nChests\nTotems\nIncreases the Action speeds for Blessing, Cleansing, and Unlocking by 8/9/10 %.","descriptionRu":"Во время Испытания вы испытываете следующие эффекты:\nВороны поблизости\nбольше не улетаете и не предупреждаете других о своем присутствии, если только вы не подойдете на расстояние досягаемости.\nПостоянно подавляет желание кричать по любой причине.\nПодавляет все шумы, связанные с взаимодействием со следующими реквизитами:\nСундуки\nТотемы\nУвеличивает скорость действий для Благословения, Очищения и Разблокировки на 8/9/10 %.","shortDescriptionRu":"Во время Испытания вы испытываете следующие эффекты: Вороны поблизости больше не улетаете и не предупреждаете других о своем присутствии, если только вы не подойдете на расстояние досягаемости. Постоянно подавляет желание кричать по любой причине.","upcomingPatch":true},"assets/perks/iconPerks_Camaraderie.png":{"englishName":"Camaraderie","owner":"Steve Harrington","role":"survivor","descriptionEn":"If you are hooked and enter the Struggle Phase, Camaraderie activates:\nPauses the Struggle Phase timer for 26/30/34 seconds as soon as any Survivor comes within 16 metres of your Hook\n.","descriptionRu":"Если вы попали на крючок и вступаете в фазу борьбы, активируется дух товарищества:\nПриостанавливает таймер фазы борьбы на 26/30/34 секунды, как только любой Выживший окажется в пределах 16 метров от вашего Крюка.\n.","shortDescriptionRu":"Если вы попали на крючок и вступаете в фазу борьбы, активируется дух товарищества: Приостанавливает таймер фазы борьбы на 34 секунды, как только любой Выживший окажется в пределах 16 метров от вашего Крюка..","upcomingPatch":false},"assets/perks/iconPerks_ChemicalTrap.png":{"englishName":"Chemical Trap","owner":"Ellen Ripley","role":"survivor","descriptionEn":"After repairing Generators\nfor a total of 20 %, Chemical Trap activates:\nPress the Active Ability button while near a dropped Pallet to install a Trap, which stays active for 40/50/60 seconds.\nWhen the Killer breaks the Trapped Pallet, its Trap explodes, spraying the Killer with a chemical compound:\nCauses the Killer to suffer from a -50 % Hindered\nStatus Effect for 4 seconds.\nChemical Trap deactivates after triggering successfully or once the timer runs out.\nThe Auras\nof Trapped Pallets are revealed to all Survivors in yellow.","descriptionRu":"После ремонта генераторов\nв общей сложности 20 %, активируется химическая ловушка:\nНажмите кнопку «Активная способность», находясь рядом с упавшим поддоном, чтобы установить ловушку, которая остается активной в течение 40/50/60 секунд.\nКогда Убийца ломает застрявший поддон, его ловушка взрывается, опрыскивая Убийцу химическим составом:\nЗаставляет Убийцу страдать от замедления на -50 %.\nСтатусный эффект на 4 секунды.\nХимическая ловушка деактивируется после успешного срабатывания или по истечении таймера.\nАуры\nЗастрявшие поддоны показаны всем выжившим желтым цветом.","shortDescriptionRu":"После ремонта генераторов в общей сложности 20%, активируется химическая ловушка: Нажмите кнопку «Активная способность», находясь рядом с упавшим поддоном, чтобы установить ловушку, которая остается активной в течение 60 секунд. Когда Убийца ломает застрявший поддон, его ловушка взрывается, опрыскивая Убийцу химическим составом: Заставляет Убийцу страдать от замедления на -50%.","upcomingPatch":false},"assets/perks/iconPerks_Clairvoyance.png":{"englishName":"Clairvoyance","owner":"Mikaela Reid","role":"survivor","descriptionEn":"After cleansing or blessing a Totem\n, Clairvoyance activates.\nWhile active, press and hold the Use Item button when empty-handed to unlock your full Aura-reading potential:\nThe Auras\nof the following objects within 64 metres are revealed to you for as long as you uphold the interaction, up to a maximum of 10/11/12 seconds:\nChests\nExit Gate Switches\nGenerators\nHatch\nHooks","descriptionRu":"После очищения или благословения тотема\n, Ясновидение активируется.\nВ активном режиме нажмите и удерживайте кнопку «Использовать предмет», когда у вас нет рук, чтобы полностью раскрыть свой потенциал чтения ауры:\nАуры\nиз следующих объектов в радиусе 64 метров вам будут видны до тех пор, пока вы поддерживаете взаимодействие, максимум до 10/11/12 секунд:\nСундуки\nВыключатели выходных ворот\nГенераторы\nЛюк\nКрючки","shortDescriptionRu":"После очищения или благословения тотема, Ясновидение активируется. В активном режиме нажмите и удерживайте кнопку «Использовать предмет», когда у вас нет рук, чтобы полностью раскрыть свой потенциал чтения ауры: Ауры из следующих объектов в радиусе 64 метров вам будут видны до тех пор, пока вы поддерживаете взаимодействие, максимум до 12 секунд: Сундуки Выключатели выходных ворот Генераторы Люк Крючки","upcomingPatch":false},"assets/perks/iconPerks_Counterforce.png":{"englishName":"Counterforce","owner":"Jill Valentine","role":"survivor","descriptionEn":"You benefit from the following permanent effect:\nIncreases the default value of your Cleansing speed to 125 %.\nWhenever you cleanse a Totem\n, Counterforce triggers the following effects:\nIncreases your Cleansing speed by a stack-able +25 %.\nThe Aura\nof the Totem farthest from your current location is revealed to you for 10/12/14 seconds.","descriptionRu":"Вы получаете следующий постоянный эффект:\nУвеличивает значение скорости очищения по умолчанию до 125 %.\nКаждый раз, когда вы очищаете тотем\n, Counterforce вызывает следующие эффекты:\nУвеличивает скорость очищения на +25 %.\nАура\nТотем, наиболее удаленный от вашего текущего местоположения, открывается вам на 10/12/14 секунд.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Увеличивает значение скорости очищения по умолчанию до 125%. Каждый раз, когда вы очищаете тотем, Counterforce вызывает следующие эффекты: Увеличивает скорость очищения на 25%. Аура Тотем, наиболее удаленный от вашего текущего местоположения, открывается вам на 14 секунд.","upcomingPatch":false},"assets/perks/iconPerks_CutLoose.png":{"englishName":"Cut Loose","owner":"Thalita Lyra","role":"survivor","descriptionEn":"After performing a Rushed Vault action while being chased, Cut Loose activates for 4/5/6 seconds:\nSuppresses all noises related to the Rushed Vault action, including the Loud Noise Notification for the Killer.\nWhile active, performing another Rushed Vault action resets the timer each time.\nCut Loose has a cool-down of 45 seconds after use and the timer has elapsed.","descriptionRu":"После выполнения действия «Быстрый прыжок» во время преследования активируется способность «Отрезать» на 4/5/6 секунд:\nПодавляет все шумы, связанные с действием «Быстрое хранилище», включая громкое уведомление убийцы.\nПока оно активно, выполнение другого действия «Быстрое хранилище» каждый раз сбрасывает таймер.\nCut Loose имеет время восстановления 45 секунд после использования, и таймер истек.","shortDescriptionRu":"После выполнения действия «Быстрый прыжок» во время преследования активируется способность «Отрезать» на 6 секунд: Подавляет все шумы, связанные с действием «Быстрое хранилище», включая громкое уведомление убийцы. Пока оно активно, выполнение другого действия «Быстрое хранилище» каждый раз сбрасывает таймер. Cut Loose имеет время восстановления 45 секунд после использования, и таймер истек.","upcomingPatch":false},"assets/perks/iconPerks_DanceWithMe.png":{"englishName":"Dance With Me","owner":"Kate Denson","role":"survivor","descriptionEn":"When performing a Rushed action to vault a Window\nor exit a Locker\n, Dance With Me triggers its effect:\nSuppresses the creation of your Scratch Marks\nfor 5 seconds.\nDance With Me has a cool-down of 20/20/15 seconds.\nDance with me, cuz there's a storm a commin'\nFollow my boots, try to keep up,\nDance with me, until sun up.\" — Kate Denson's \"Dance with Me\"","descriptionRu":"При выполнении срочного действия по перемещению окна\nили выйти из шкафчика\n, «Танцуй со мной» активирует свой эффект:\nПодавляет появление царапин.\nв течение 5 секунд.\n«Танцуй со мной» имеет время восстановления 20/20/15 секунд.\nПотанцуй со мной, потому что надвигается буря.\nСледуй за моими ботинками, постарайся не отставать,\nТанцуй со мной до восхода солнца» — Кейт Денсон «Танцуй со мной».","shortDescriptionRu":"При выполнении срочного действия по перемещению окна или выйти из шкафчика, «Танцуй со мной» активирует свой эффект: Подавляет появление царапин. в течение 5 секунд. «Танцуй со мной» имеет время восстановления 15 секунд.","upcomingPatch":false},"assets/perks/iconPerks_DarkSense.png":{"englishName":"Dark Sense","owner":"Общий","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever a Generator\nis completed, Dark Sense activates:\nWhen the Killer gets within 24 metres of you, Dark Sense activates for 8/9/10 seconds:\nYou see the Killer's aura.\nYou see auras of other Survivors.\nYou see the auras of Pallets\nand Windows\nwithin 24 metres.\nDark Sense deactivates after use.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nВсякий раз, когда генератор\nзавершено, активируется Темное Чувство:\nКогда Убийца оказывается на расстоянии 24 метров от вас, «Тёмное чувство» активируется на 8/9/10 секунд:\nВы видите ауру Убийцы.\nВы видите ауры других Выживших.\nВы видите ауры Паллетов\nи Windows\nв пределах 24 метров.\nDark Sense деактивируется после использования.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Всякий раз, когда генератор завершено, активируется Темное Чувство: Когда Убийца оказывается на расстоянии 24 метров от вас, «Тёмное чувство» активируется на 10 секунд: Вы видите ауру Убийцы. Вы видите ауры других Выживших.","upcomingPatch":true},"assets/perks/iconPerks_DarkTheory.png":{"englishName":"Boon: Dark Theory","owner":"Yoichi Asakawa","role":"survivor","descriptionEn":"Press and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nGrants a +3 % Haste\nStatus Effect.\nThis effect lingers for 2/3/4 seconds after leaving the Boon Totem's range.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nДает +3 % скорости.\nЭффект статуса.\nЭтот эффект сохраняется в течение 2/3/4 секунд после выхода из зоны действия Тотема Благодати.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Дает +3% скорости. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_DeadHard.png":{"englishName":"Dead Hard","owner":"David King","role":"survivor","descriptionEn":"Tap into your adrenaline bank to avoid taking further damage.\"\nAfter being unhooked by any means, Dead Hard activates:While injured and running, press the Active Ability button to trigger the following effect:\nGrants the Endurance\nStatus Effect for 0.5 seconds.\nDead Hard cannot be used while Exhausted.\nDead Hard causes the Exhausted\nStatus Effect for 60/50/40 seconds.\nI thought to myself \"Gonna 'ave some fun 'ere lads, let's get stuck in!\".\nIt were a right dust up, I swear down!\" — David King","descriptionRu":"Используйте свой запас адреналина, чтобы избежать дальнейшего урона».\nПосле того, как вас отцепят любым способом, Dead Hard активируется: Во время ранения и бега нажмите кнопку «Активная способность», чтобы вызвать следующий эффект:\nДает выносливость\nСтатусный эффект на 0,5 секунды.\nDead Hard нельзя использовать, пока вы измотаны.\nDead Hard вызывает изнеможение\nСтатусный эффект на 60/50/40 секунд.\nЯ подумал про себя: «Ребята, повеселимся, давайте застрять!».\nЭто была настоящая пыль, клянусь!\" — Дэвид Кинг","shortDescriptionRu":"Используйте свой запас адреналина, чтобы избежать дальнейшего урона». После того, как вас отцепят любым способом, Dead Hard активируется: Во время ранения и бега нажмите кнопку «Активная способность», чтобы вызвать следующий эффект: Дает выносливость Статусный эффект на 0,5 секунды. Dead Hard нельзя использовать, пока вы измотаны.","upcomingPatch":false},"assets/perks/iconPerks_Deception.png":{"englishName":"Deception","owner":"%C3%89lodie Rakoto","role":"survivor","descriptionEn":"Press and hold the Sprint button while interacting with a Locker\nfor the following effects:\nSuppresses the creation of your Scratch Marks\nand Pools of Blood\nfor 5 seconds.\nCauses you to run past the targeted Locker, instead of entering it.\nCauses its doors to swiftly open and close again, feining you having entered it in a rush.\nTriggers a Loud Noise Notification for the Killer at its location.\nDeception has a cool-down of 25/20/15 seconds.","descriptionRu":"Нажмите и удерживайте кнопку «Спринт» во время взаимодействия со шкафчиком.\nдля следующих эффектов:\nПодавляет появление царапин.\nи лужи крови\nв течение 5 секунд.\nЗаставляет вас пробежать мимо целевого шкафчика, вместо того, чтобы войти в него.\nЗаставляет его двери быстро открываться и закрываться снова, создавая впечатление, что вы вошли в него в спешке.\nВызывает громкий шум для убийцы в месте его нахождения.\nВремя восстановления Deception составляет 25/20/15 секунд.","shortDescriptionRu":"Нажмите и удерживайте кнопку «Спринт» во время взаимодействия со шкафчиком. для следующих эффектов: Подавляет появление царапин. и лужи крови в течение 5 секунд.","upcomingPatch":false},"assets/perks/iconPerks_DecisiveStrike.png":{"englishName":"Decisive Strike","owner":"Laurie Strode","role":"survivor","descriptionEn":"Identical to Will to Live\n.","descriptionRu":"Идентичен желанию жить\n.","shortDescriptionRu":"Идентичен желанию жить.","upcomingPatch":false},"assets/perks/iconPerks_DejaVu.png":{"englishName":"Déjà Vu","owner":"Общий","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof whichever 3 Generators\nare currently in closest proximity to one another are revealed to you.\nIncreases your Repair speed on those Generators by 4/5/6 %.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nиз любых 3 генераторов\nкоторые в настоящее время находятся в наибольшей близости друг от друга, раскрываются вам.\nУвеличивает скорость ремонта этих генераторов на 4/5/6%.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры из любых 3 генераторов которые в настоящее время находятся в наибольшей близости друг от друга, раскрываются вам. Увеличивает скорость ремонта этих генераторов на 6%.","upcomingPatch":false},"assets/perks/iconPerks_Deliverance.png":{"englishName":"Deliverance","owner":"Adam Francis","role":"survivor","descriptionEn":"After safely unhooking another Survivor, Deliverance activates:\nGrants the ability to perform a successful Self-Unhook at any point during the first Hook Stage.\nCauses the Broken\nStatus Effect for 160/140/120 seconds after unhooking yourself.\nDeliverance cannot be used during the second Hook Stage or if you are hooked as the Last Survivor Standing.\nDeliverance is disabled for the remainder of the Trial after use.","descriptionRu":"После безопасного отцепления другого Выжившего активируется Избавление:\nПредоставляет возможность выполнить успешное самоотцепление в любой момент первого этапа крюка.\nВызывает поломку\nСтатусный эффект на 160/140/120 секунд после отцепления.\nОсвобождение нельзя использовать на втором этапе крюка или если вы попали на крючок как последний выживший.\nИзбавление отключено до конца Испытания после использования.","shortDescriptionRu":"После безопасного отцепления другого Выжившего активируется Избавление: Предоставляет возможность выполнить успешное самоотцепление в любой момент первого этапа крюка. Вызывает поломку Статусный эффект на 120 секунд после отцепления. Освобождение нельзя использовать на втором этапе крюка или если вы попали на крючок как последний выживший.","upcomingPatch":false},"assets/perks/iconPerks_DesperateMeasures.png":{"englishName":"Desperate Measures","owner":"Felix Richter","role":"survivor","descriptionEn":"Whenever any Survivor, including yourself, is not in the Healthy State, Desperate Measures activates:\nIncreases your Action speeds for Healing and Unhooking by a stack-able 16/18/20 % per injured, dying, or hooked Survivor, up to a maximum of 64/72/80 %.","descriptionRu":"Всякий раз, когда любой Выживший, включая вас, не находится в здоровом состоянии, активируются «Отчаянные меры»:\nУвеличивает скорость ваших действий при лечении и отцеплении на 16/18/20 % за каждого раненого, умирающего или попавшего на крючок Выжившего, вплоть до максимального значения 64/72/80 %.","shortDescriptionRu":"Всякий раз, когда любой Выживший, включая вас, не находится в здоровом состоянии, активируются «Отчаянные меры»: Увеличивает скорость ваших действий при лечении и отцеплении на 20% за каждого раненого, умирающего или попавшего на крючок Выжившего, вплоть до максимального значения 80%.","upcomingPatch":false},"assets/perks/iconPerks_DetectivesHunch.png":{"englishName":"Detective's Hunch","owner":"David Tapp","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever a Generator is completed, Detective's Hunch triggers its effect:\nThe Auras\nof the following objects within 32/48/64 metres of your location are revealed to you for 20 seconds:\nChests\nGenerators\nTotems","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nКаждый раз, когда Генератор завершен, срабатывает эффект «Предчувствия детектива»:\nАуры\nиз следующих объектов в радиусе 32/48/64 метров от вашего местоположения отображаются вам на 20 секунд:\nСундуки\nГенераторы\nТотемы","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Каждый раз, когда Генератор завершен, срабатывает эффект «Предчувствия детектива»: Ауры из следующих объектов в радиусе 64 метров от вашего местоположения отображаются вам на 20 секунд: Сундуки Генераторы Тотемы","upcomingPatch":false},"assets/perks/iconPerks_Distortion.png":{"englishName":"Distortion","owner":"Jeff Johansen","role":"survivor","descriptionEn":"Start the Trial with 1 Token.\nWhenever the Killer attempts to read your Aura\n, Distortion automatically consumes -1 Token to trigger the following effects for 8/10/12 seconds:\nBlocks your Aura from being read.\nSuppresses the creation of your Scratch Marks\n.\nDistortion recharges +1 Token every 15 seconds of being chased by the Killer, and can hold 2 Tokens.\nDistortion does not trigger its effects while in the Dying State\n.","descriptionRu":"Начните пробную версию с 1 жетоном.\nВсякий раз, когда Убийца пытается прочитать вашу ауру\n, Искажение автоматически потребляет -1 жетон для срабатывания следующих эффектов на 8/10/12 секунд:\nБлокирует чтение вашей ауры.\nПодавляет появление царапин.\n.\nИскажение перезаряжает +1 жетон каждые 15 секунд преследования Убийцы и может содержать 2 жетона.\nИскажение не активирует свои эффекты в состоянии умирания.\n.","shortDescriptionRu":"Начните пробную версию с 1 жетоном. Всякий раз, когда Убийца пытается прочитать вашу ауру, Искажение автоматически потребляет -1 жетон для срабатывания следующих эффектов на 12 секунд: Блокирует чтение вашей ауры. Подавляет появление царапин..","upcomingPatch":false},"assets/perks/iconPerks_Diversion.png":{"englishName":"Diversion","owner":"Adam Francis","role":"survivor","descriptionEn":"After staying in the Terror Radius\nwithout being chased for 30/25/20 seconds, Diversion activates.\nWhile active, press the Active Ability button while crouched and motionless to throw a pebble in the direction you are facing:\nCreates a distraction for the Killer at its landing location 20 metres away:\nTriggers a Loud Noise Notification.\nCreates fake Scratch Marks\n.\nDiversion deactivates after use.","descriptionRu":"После пребывания в Радиусе Террора\nесли вас не преследуют в течение 30/25/20 секунд, активируется отвлечение.\nВ активном режиме нажмите кнопку «Активная способность», находясь пригнувшись и неподвижно, чтобы бросить камешек в том направлении, в котором вы смотрите:\nОтвлекает Убийцу в месте приземления на расстоянии 20 метров:\nВызывает громкое уведомление.\nСоздает поддельные царапины\n.\nДиверсия деактивируется после использования.","shortDescriptionRu":"После пребывания в Радиусе Террора если вас не преследуют в течение 20 секунд, активируется отвлечение. В активном режиме нажмите кнопку «Активная способность», находясь пригнувшись и неподвижно, чтобы бросить камешек в том направлении, в котором вы смотрите: Отвлекает Убийцу в месте приземления на расстоянии 20 метров: Вызывает громкое уведомление. Создает поддельные царапины.","upcomingPatch":false},"assets/perks/iconPerks_Dramaturgy.png":{"englishName":"Dramaturgy","owner":"Nicolas Cage","role":"survivor","descriptionEn":"Whenever you are at full health, Dramaturgy activates.\nWhile active, press the Active Ability button while running to run with knees high for 0.5 seconds before benefitting from the following primary effect:\nGrants a +25 Haste\nStatus Effect for 2 seconds.\nAfterwards, Dramaturgy triggers any one of the following secondary effects, but never the same one twice in a row:\nGrants a second instance of the primary Haste Status Effect.\nInflicts the Exposed\nStatus Effect for 12 seconds.\nCauses you to scream.\nGrants a randomly selected Rare Item\npre-equipped with a random selection of Add-ons\n.\nThis causes you to automatically drop any previously held Item.\nDramaturgy cannot be used while Exhausted.\nDramaturgy causes the Exhausted\nStatus Effect for 60/50/40 seconds.","descriptionRu":"Всякий раз, когда у вас полное здоровье, активируется Драматургия.\nПока активно, нажмите кнопку «Активная способность» во время бега, чтобы бежать с высоко поднятыми коленями в течение 0,5 секунды, прежде чем воспользоваться следующим основным эффектом:\nДает +25 скорости\nСтатусный эффект на 2 секунды.\nПосле этого Драматургия вызывает любой из следующих побочных эффектов, но не один и тот же дважды подряд:\nПредоставляет второй экземпляр основного эффекта статуса скорости.\nНаносит уязвимость\nСтатусный эффект на 12 секунд.\nЗаставляет вас кричать.\nПредоставляет случайно выбранный редкий предмет.\nпредварительно оснащен случайным набором дополнений\n.\nЭто приведет к автоматическому удалению любого ранее удерживаемого предмета.\nДраматургию нельзя использовать, пока вы измотаны.\nДраматургия вызывает истощение\nСтатусный эффект на 60/50/40 секунд.","shortDescriptionRu":"Всякий раз, когда у вас полное здоровье, активируется Драматургия. Пока активно, нажмите кнопку «Активная способность» во время бега, чтобы бежать с высоко поднятыми коленями в течение 0,5 секунды, прежде чем воспользоваться следующим основным эффектом: Дает +25 скорости Статусный эффект на 2 секунды.","upcomingPatch":false},"assets/perks/iconPerks_EmpathicConnection.png":{"englishName":"Empathic Connection","owner":"Yoichi Asakawa","role":"survivor","descriptionEn":"You benefit from the following permanent primary effect:\nIncreases your Altruistic Healing speed by 40/45/50 %.\nWhenever any other Survivor is injured, Empathic Connection applies its secondary effect:\nYour Aura\nas a potential Healer is revealed to them.","descriptionRu":"Вы получаете следующий постоянный первичный эффект:\nУвеличивает скорость альтруистического исцеления на 40/45/50%.\nКаждый раз, когда любой другой Выживший получает травму, «Эмпатическая связь» применяет свой вторичный эффект:\nВаша аура\nкак им открывается потенциальный Целитель.","shortDescriptionRu":"Вы получаете следующий постоянный первичный эффект: Увеличивает скорость альтруистического исцеления на 50%. Каждый раз, когда любой другой Выживший получает травму, «Эмпатическая связь» применяет свой вторичный эффект: Ваша аура как им открывается потенциальный Целитель.","upcomingPatch":true},"assets/perks/iconPerks_Empathy.png":{"englishName":"Empathy","owner":"Claudette Morel","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof injured or dying Survivors are revealed to you within 64/96/128 metres.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nраненых или умирающих Выживших видны вам в радиусе 64/96/128 метров.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры раненых или умирающих Выживших видны вам в радиусе 128 метров.","upcomingPatch":false},"assets/perks/iconPerks_Exultation.png":{"englishName":"Exultation","owner":"Trevor Belmont","role":"survivor","descriptionEn":"While holding an Item\n, stunning the Killer by dropping a Pallet\ncauses the following effects:\nRecharges the Item by +75 %.\nUpgrades its Rarity to the next available Tier.\nExultation has a cool-down of 30/25/20 seconds.","descriptionRu":"Удерживая предмет\n, оглушив Убийцу, уронив поддон\nвызывает следующие эффекты:\nПерезаряжает предмет на +75 %.\nПовышает редкость до следующего доступного уровня.\nВремя восстановления «Ликования» составляет 30/25/20 секунд.","shortDescriptionRu":"Удерживая предмет, оглушив Убийцу, уронив поддон вызывает следующие эффекты: Перезаряжает предмет на 75%. Повышает редкость до следующего доступного уровня. Время восстановления «Ликования» составляет 20 секунд.","upcomingPatch":false},"assets/perks/iconPerks_EyesOfBelmont.png":{"englishName":"Eyes of Belmont","owner":"Trevor Belmont","role":"survivor","descriptionEn":"Whenever a Generator\nis completed, the Aura\nof the Killer is revealed to you for 1/2/3 seconds.\nExtends the duration of all instances of the Killer's Aura being revealed to you by +2 seconds.\nEyes of Belmont benefits from its own effect.","descriptionRu":"Всякий раз, когда генератор\nзавершено, Аура\nУбийцы открываются вам на 1/2/3 секунды.\nУвеличивает продолжительность всех проявлений ауры убийцы, открывающихся перед вами, на +2 секунды.\nГлаза Бельмонта получают выгоду от собственного эффекта.","shortDescriptionRu":"Всякий раз, когда генератор завершено, Аура Убийцы открываются вам на 3 секунды. Увеличивает продолжительность всех проявлений ауры убийцы, открывающихся перед вами, на 2 секунды. Глаза Бельмонта получают выгоду от собственного эффекта.","upcomingPatch":false},"assets/perks/iconPerks_FastTrack.png":{"englishName":"Fast Track","owner":"Lee Yun-jin","role":"survivor","descriptionEn":"Whenever you unhook a Survivor, Fast Track is granted 1 Token, up to a maximum of 1/2/3 Token(s)\nSucceeding a Great Repair Skill Check consumes all accumulated Tokens.\nPermanently reduces the Repair Charges requirement of that Generator by 5 charges per Token.","descriptionRu":"Каждый раз, когда вы отцепляете Выжившего, Fast Track получает 1 жетон, но не более 1/2/3 жетона(ов).\nПри успешной проверке навыка «Великий ремонт» расходуются все накопленные жетоны.\nНавсегда снижает потребность в ремонтных зарядах для этого генератора на 5 зарядов за каждый жетон.","shortDescriptionRu":"Каждый раз, когда вы отцепляете Выжившего, Fast Track получает 1 жетон, но не более 3 жетона(ов). При успешной проверке навыка «Великий ремонт» расходуются все накопленные жетоны. Навсегда снижает потребность в ремонтных зарядах для этого генератора на 5 зарядов за каждый жетон.","upcomingPatch":false},"assets/perks/iconPerks_Finesse.png":{"englishName":"Finesse","owner":"Lara Croft","role":"survivor","descriptionEn":"The threat of danger can motivate any creature to strengthen its resolve.\nWhenever you are healthy, Finesse activates:\nIncreases your Vaulting speed for a Fast Vault by +20 %.\nFinesse has a cool-down of 40/35/30 seconds after performing a Fast Vault.","descriptionRu":"Угроза опасности может побудить любое существо укрепить свою решимость.\nКогда вы здоровы, Finesse активирует:\nУвеличивает скорость прыжка для быстрого прыжка на +20 %.\nУ Finesse время восстановления составляет 40/35/30 секунд после выполнения Fast Vault.","shortDescriptionRu":"Угроза опасности может побудить любое существо укрепить свою решимость. Когда вы здоровы, Finesse активирует: Увеличивает скорость прыжка для быстрого прыжка на 20%. У Finesse время восстановления составляет 30 секунд после выполнения Fast Vault.","upcomingPatch":false},"assets/perks/iconPerks_Fixated.png":{"englishName":"Fixated","owner":"Nancy Wheeler","role":"survivor","descriptionEn":"You benefit from the following permanent effects:\nIncreases your Walking speed by 10/15/20 %.\nUnlocks the ability to see your own Scratch Marks\n.","descriptionRu":"Вы получаете следующие постоянные эффекты:\nУвеличивает скорость ходьбы на 10/15/20%.\nОткрывает возможность видеть свои собственные царапины.\n.","shortDescriptionRu":"Вы получаете следующие постоянные эффекты: Увеличивает скорость ходьбы на 20%. Открывает возможность видеть свои собственные царапины..","upcomingPatch":false},"assets/perks/iconPerks_Flashbang.png":{"englishName":"Flashbang","owner":"Leon Scott Kennedy","role":"survivor","descriptionEn":"You have adapted to a world in chaos and making what you can from the debris.\nAfter repairing Generators\nfor a total of 50/45/40 %, Flashbang activates:\nPress the Active Ability button while hiding inside a Locker\nto craft a Flash Grenade\n.\nFlashbang deactivates after use.","descriptionRu":"Вы адаптировались к миру, в котором царит хаос, и делаете все, что можете, из обломков.\nПосле ремонта генераторов\nв сумме 50/45/40 % активируется Световая граната:\nНажмите кнопку активной способности, прячась внутри шкафчика.\nсоздать светошумовую гранату\n.\nСветовая граната деактивируется после использования.","shortDescriptionRu":"Вы адаптировались к миру, в котором царит хаос, и делаете все, что можете, из обломков. После ремонта генераторов в сумме 40% активируется Световая граната: Нажмите кнопку активной способности, прячась внутри шкафчика. создать светошумовую гранату.","upcomingPatch":false},"assets/perks/iconPerks_FlipFlop.png":{"englishName":"Flip-Flop","owner":"Ash Williams","role":"survivor","descriptionEn":"Recovering in the Dying State\nalso charges the Wiggle Meter at 50 % of the Recovery rate and up to a maximum of 40/45/50 % of Wiggle Progression.","descriptionRu":"Выздоровление в умирающем состоянии\nтакже заряжает счетчик покачивания на 50 % от скорости восстановления и максимум до 40/45/50 % от прогресса покачивания.","shortDescriptionRu":"Выздоровление в умирающем состоянии также заряжает счетчик покачивания на 50% от скорости восстановления и максимум до 50% от прогресса покачивания.","upcomingPatch":false},"assets/perks/iconPerks_Fogwise.png":{"englishName":"Fogwise","owner":"Vittorio Toscano","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability while repairing Generators\n:\nThe Aura\nof the Killer is revealed to you for 4/5/6 seconds after succeeding a Great Repair Skill Check.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры при ремонте генераторов.\n:\nАура\nУбийцы открывается вам на 4/5/6 секунд после успешной проверки навыка Великого Ремонта.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры при ремонте генераторов.: Аура Убийцы открывается вам на 6 секунд после успешной проверки навыка Великого Ремонта.","upcomingPatch":false},"assets/perks/iconPerks_ForThePeople.png":{"englishName":"For the People","owner":"Zarina Kassir","role":"survivor","descriptionEn":"While healthy and healing another Survivor without using a Med-Kit\n, press the Active Ability button to trigger the following effects:\nTrade 1 Health State\nwith the other Survivor:\nInstantly heals them to the Injured State\n, if they were dying or suffering from the Deep Wound\nStatus Effect.\nInstantly heals them to full health, if they were injured.\nYou yourself become injured and suffer from the Broken\nStatus Effect for 80/70/60 seconds.\nYou become the Killer's Obsession\n, if not already.\nReduces your chance of becoming the initial Obsession by reducing the default value by -100 %.\nThe Killer can only be obsessed with one Survivor at a time.","descriptionRu":"Будучи здоровым и исцеляя другого Выжившего без использования аптечки.\n, нажмите кнопку «Активная способность», чтобы вызвать следующие эффекты:\nТорговля 1 Состояние здоровья\nс другим Выжившим:\nМгновенно исцеляет их до раненого состояния.\n, если бы они умирали или страдали от глубокой раны\nЭффект статуса.\nМгновенно восстанавливает им полное здоровье, если они были ранены.\nВы сами получаете ранения и страдаете от Сломанного\nСтатусный эффект на 80/70/60 секунд.\nВы становитесь одержимостью убийцы\n, если еще не.\nУменьшает ваш шанс стать первоначальной одержимостью за счет уменьшения значения по умолчанию на -100 %.\nУбийца может быть одержим только одним Выжившим одновременно.","shortDescriptionRu":"Будучи здоровым и исцеляя другого Выжившего без использования аптечки., нажмите кнопку «Активная способность», чтобы вызвать следующие эффекты: Торговля 1 Состояние здоровья с другим Выжившим: Мгновенно исцеляет их до раненого состояния., если бы они умирали или страдали от глубокой раны Эффект статуса. Мгновенно восстанавливает им полное здоровье, если они были ранены.","upcomingPatch":false},"assets/perks/iconPerks_FriendlyCompetition.png":{"englishName":"Friendly Competition","owner":"Thalita Lyra","role":"survivor","descriptionEn":"Each time you complete a Generator\ntogether with at least one other Survivor, Friendly Competition activates:\nIncreases the Repair speed of all participating Survivors, including yourself, by +10 % for 80/85/90 seconds.","descriptionRu":"Каждый раз, когда вы завершаете Генератор\nвместе с хотя бы еще одним Выжившим активируется Дружеское соревнование:\nУвеличивает скорость ремонта всех участвующих Выживших, включая вас, на +10 % на 80/85/90 секунд.","shortDescriptionRu":"Каждый раз, когда вы завершаете Генератор вместе с хотя бы еще одним Выжившим активируется Дружеское соревнование: Увеличивает скорость ремонта всех участвующих Выживших, включая вас, на 10% на 90 секунд.","upcomingPatch":true},"assets/perks/iconPerks_guardian.png":{"englishName":"Babysitter","owner":"Steve Harrington","role":"survivor","descriptionEn":"Whenever you unhook another Survivor, you benefit from the following effect:\nThe Aura\nof the Killer is revealed to you for 8 seconds.\nThe unhooked Survivor benefits from the following effects instead for 20/25/30 seconds:\nSuppresses the creation of their Scratch Marks\nand Pools of Blood\n.\nIncreases the strength of their Haste\nStatus Effect by +10 %.","descriptionRu":"Каждый раз, когда вы отцепляете другого Выжившего, вы получаете следующий эффект:\nАура\nУбийцы открываются вам на 8 секунд.\nВместо этого на выжившего, отцепившегося от крюка, в течение 20/25/30 секунд действуют следующие эффекты:\nПодавляет создание царапин.\nи лужи крови\n.\nУвеличивает силу их скорости.\nЭффект статуса на +10 %.","shortDescriptionRu":"Каждый раз, когда вы отцепляете другого Выжившего, вы получаете следующий эффект: Аура Убийцы открываются вам на 8 секунд. Вместо этого на выжившего, отцепившегося от крюка, в течение 30 секунд действуют следующие эффекты: Подавляет создание царапин. и лужи крови.","upcomingPatch":false},"assets/perks/iconPerks_Hardened.png":{"englishName":"Hardened","owner":"Lara Croft","role":"survivor","descriptionEn":"Live long enough, and survival will run in your blood.\nAfter unlocking a Chest\nand either blessing or cleansing a Totem\n, Hardened activates:\nSuppresses the urge to scream from any cause and instead causes the Aura\nof the Killer to be revealed to you for 3/4/5 seconds.","descriptionRu":"Живите достаточно долго, и выживание будет у вас в крови.\nПосле открытия сундука\nи либо благословлять, либо очищать тотем\n, Закалка активирует:\nПодавляет желание кричать по любой причине и вместо этого вызывает ауру.\nУбийцы откроется вам на 3/4/5 секунды.","shortDescriptionRu":"Живите достаточно долго, и выживание будет у вас в крови. После открытия сундука и либо благословлять, либо очищать тотем, Закалка активирует: Подавляет желание кричать по любой причине и вместо этого вызывает ауру. Убийцы откроется вам на 5 секунды.","upcomingPatch":false},"assets/perks/iconPerks_HeadOn.png":{"englishName":"Head On","owner":"Jane Romero","role":"survivor","descriptionEn":"After hiding in a Locker\nfor 3 seconds, Head On activates.\nWhile active, hold the Sprint button while exiting the Locker to trigger its effect:\nCauses you to forcefully launch yourself from the Locker, stunning the Killer if they are too close to it:\nHas a Stun range of 2.5 metres.\nHas a Stun duration of 3 seconds.\nTriggers a Loud Noise Notification for the Killer upon missing.\nHead On cannot be used while Exhausted.\nHead On causes the Exhausted\nStatus Effect for 60/50/40 seconds on a successful stun.","descriptionRu":"После того, как спрятался в шкафчике\nна 3 секунды активируется Head On.\nПока активно, удерживайте кнопку «Спринт» при выходе из шкафчика, чтобы активировать его эффект:\nЗаставляет вас с силой выпрыгнуть из шкафчика, оглушая Убийцу, если он окажется слишком близко к нему:\nИмеет радиус оглушения 2,5 метра.\nИмеет продолжительность оглушения 3 секунды.\nВ случае пропажи убийца запускает громкое уведомление.\nHead On нельзя использовать, пока вы измотаны.\nHead On вызывает усталость\nСтатусный эффект на 60/50/40 секунд при успешном оглушении.","shortDescriptionRu":"После того, как спрятался в шкафчике на 3 секунды активируется Head On. Пока активно, удерживайте кнопку «Спринт» при выходе из шкафчика, чтобы активировать его эффект: Заставляет вас с силой выпрыгнуть из шкафчика, оглушая Убийцу, если он окажется слишком близко к нему: Имеет радиус оглушения 2,5 метра. Имеет продолжительность оглушения 3 секунды.","upcomingPatch":false},"assets/perks/iconPerks_Hope.png":{"englishName":"Hope","owner":"Общий","role":"survivor","descriptionEn":"Once the Exit Gates\nare powered, Hope activates for the remainder of the Trial:\nGrants a 3/4/5 % Haste\nStatus Effect.","descriptionRu":"Однажды Выходные Ворота\nвключены, Надежда активируется до конца Испытания:\nДает 3/4/5% скорости.\nЭффект статуса.","shortDescriptionRu":"Однажды Выходные Ворота включены, Надежда активируется до конца Испытания: Дает 5% скорости. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_Hyperfocus.png":{"englishName":"Hyperfocus","owner":"Rebecca Chambers","role":"survivor","descriptionEn":"Succeeding a Great Skill Check\nwhile repairing or healing grants +1 Token, up to a maximum of 6 Tokens:\nIncreases the Skill Check Trigger odds and Pointer-Rotation speed by +4 % per Token each, up to a maximum of +24 %.\nIncreases the Skill Check Bonus progression by 10/20/30 % of its base value per Token, up to a maximum of 60/120/180 %.\nHyperfocus loses all Tokens after succeeding just a Good Skill Check, failing one, or if the action is interrupted by any means.","descriptionRu":"Успешная проверка навыков\nпри ремонте или исцелении дает +1 жетон, максимум до 6 жетонов:\nУвеличивает вероятность срабатывания проверки навыков и скорость вращения указателя на +4 % за каждый жетон, максимум до +24 %.\nУвеличивает прогресс Бонуса проверки навыков на 10/20/30 % от его базового значения за каждый жетон, вплоть до максимального значения 60/120/180 %.\nГиперфокус теряет все жетоны после успешной проверки хороших навыков, провала одной из них или если действие прерывается каким-либо образом.","shortDescriptionRu":"Успешная проверка навыков при ремонте или исцелении дает +1 жетон, максимум до 6 жетонов: Увеличивает вероятность срабатывания проверки навыков и скорость вращения указателя на 4% за каждый жетон, максимум до +24%. Увеличивает прогресс Бонуса проверки навыков на 30% от его базового значения за каждый жетон, вплоть до максимального значения 180%.","upcomingPatch":false},"assets/perks/iconPerks_InnerFocus.png":{"englishName":"Inner Focus","owner":"Haddie Kaur","role":"survivor","descriptionEn":"You have honed your ability to see through the haze of the Ravage.\nGrants the ability to see the Scratch Marks\nof other Survivors.\nWhenever another Survivor loses a Health State\ndue to the Killer, the Aura\nof the latter is revealed to your for 6/8/10 seconds.","descriptionRu":"Вы отточили свою способность видеть сквозь дымку Опустошения.\nПредоставляет возможность видеть царапины.\nдругих Выживших.\nКаждый раз, когда другой Выживший теряет состояние здоровья\nиз-за Убийцы, Аура\nиз последних открывается вам на 6/8/10 секунд.","shortDescriptionRu":"Вы отточили свою способность видеть сквозь дымку Опустошения. Предоставляет возможность видеть царапины. других Выживших.","upcomingPatch":false},"assets/perks/iconPerks_innerStrength.png":{"englishName":"Inner Strength","owner":"Nancy Wheeler","role":"survivor","descriptionEn":"After cleansing a Totem\nof any kind, Inner Strength activates.\nWhile active, hiding inside a Locker\nfor 10/9/8 seconds triggers the following effect:\nHeals you to the next Health State\n.\nInner Strength deactivates after use.\nInner Strength cannot be used while suffering from the Broken\nStatus Effect.","descriptionRu":"После очищения тотема\nлюбого рода, активируется Внутренняя Сила.\nПока активен, прячется внутри шкафчика.\nна 10/9/8 секунд вызывает следующий эффект:\nИсцеляет вас до следующего состояния здоровья\n.\nВнутренняя сила деактивируется после использования.\nВнутреннюю силу нельзя использовать, пока вы страдаете от Сломанного.\nЭффект статуса.","shortDescriptionRu":"После очищения тотема любого рода, активируется Внутренняя Сила. Пока активен, прячется внутри шкафчика. на 8 секунд вызывает следующий эффект: Исцеляет вас до следующего состояния здоровья.","upcomingPatch":false},"assets/perks/iconPerks_IronWill.png":{"englishName":"Iron Will","owner":"Jake Park","role":"survivor","descriptionEn":"While injured, you benefit from the following effects:\nReduces the volume of Grunts of Pain by 80/90/100 %.\nIron Will cannot be used while Exhausted, but does not cause the Status Effect.","descriptionRu":"При ранении вы получаете следующие эффекты:\nУменьшает громкость Grunts of Pain на 80/90/100%.\nЖелезная воля не может быть использована во время истощения, но не вызывает эффекта статуса.","shortDescriptionRu":"При ранении вы получаете следующие эффекты: Уменьшает громкость Grunts of Pain на 100%. Железная воля не может быть использована во время истощения, но не вызывает эффекта статуса.","upcomingPatch":false},"assets/perks/iconPerks_Kindred.png":{"englishName":"Kindred","owner":"Общий","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability.\nWhenever any Survivor is hooked, Kindred activates and applies the following effects:\nThe Aura\nof the Killer is revealed to all Survivors whenever the Killer comes within 14/15/16 metres of the Hook\n.\nIf you are the Hooked Survivor, the Auras of all Survivors are revealed to each other.\nIf you are not the Hooked Survivor, the Auras of all other Survivors are only revealed to you.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nКаждый раз, когда любой Выживший попадает на крючок, Сородич активируется и применяет следующие эффекты:\nАура\nИнформация об Убийце раскрывается всем Выжившим, когда Убийца приближается к Крюку на расстояние 14/15/16 метров.\n.\nЕсли вы — Выживший на крючке, ауры всех Выживших открываются друг другу.\nЕсли вы не Выживший на крючке, ауры всех остальных Выживших открываются только вам.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Каждый раз, когда любой Выживший попадает на крючок, Сородич активируется и применяет следующие эффекты: Аура Информация об Убийце раскрывается всем Выжившим, когда Убийца приближается к Крюку на расстояние 16 метров.. Если вы — Выживший на крючке, ауры всех Выживших открываются друг другу.","upcomingPatch":true},"assets/perks/iconPerks_Leader.png":{"englishName":"Leader","owner":"Dwight Fairfield","role":"survivor","descriptionEn":"All other Survivors within 10 metres of your location benefit from the following effect:\nIncreases their Action speeds for Cleansing, Gate-Opening, Healing, Sabotaging, Unhooking, and Unlocking by 20/25/30 %.\nThis effect lingers for 15 seconds after leaving its Area of Effect.\nSurvivors can only be affected by one instance of Leader at a time.","descriptionRu":"Все остальные Выжившие в радиусе 10 метров от вашего местоположения получают следующий эффект:\nУвеличивает скорость действий при очистке, открытии врат, исцелении, саботаже, отцеплении и разблокировке на 20/25/30 %.\nЭтот эффект сохраняется в течение 15 секунд после выхода из области действия.\nНа выживших одновременно может воздействовать только один экземпляр Лидера.","shortDescriptionRu":"Все остальные Выжившие в радиусе 10 метров от вашего местоположения получают следующий эффект: Увеличивает скорость действий при очистке, открытии врат, исцелении, саботаже, отцеплении и разблокировке на 30%. Этот эффект сохраняется в течение 15 секунд после выхода из области действия. На выживших одновременно может воздействовать только один экземпляр Лидера.","upcomingPatch":false},"assets/perks/iconPerks_LeftBehind.png":{"englishName":"Left Behind","owner":"Bill Overbeck","role":"survivor","descriptionEn":"Once you are the Last Survivor Standing, Left Behind activates:\nThe Aura\nof the Hatch\nis revealed to you within 24/28/32 metres.","descriptionRu":"Как только вы станете последним выжившим, активируется функция «Оставленные позади»:\nАура\nиз Люка\nоткрывается вам в радиусе 24/28/32 метров.","shortDescriptionRu":"Как только вы станете последним выжившим, активируется функция «Оставленные позади»: Аура из Люка открывается вам в радиусе 32 метров.","upcomingPatch":false},"assets/perks/iconPerks_LightFooted.png":{"englishName":"Light-Footed","owner":"Ellen Ripley","role":"survivor","descriptionEn":"Whenever you are healthy, Light-Footed activates:\nSuppresses the sound of your footsteps while running.\nLight-Footed has a cool-down of 14/12/10 seconds after performing a Rush Vault action.","descriptionRu":"Когда вы здоровы, активируется «Легконогий»:\nПодавляет звук шагов во время бега.\nУ Легконогого время восстановления составляет 14/12/10 секунд после выполнения действия Rush Vault.","shortDescriptionRu":"Когда вы здоровы, активируется «Легконогий»: Подавляет звук шагов во время бега. У Легконогого время восстановления составляет 10 секунд после выполнения действия Rush Vault.","upcomingPatch":false},"assets/perks/iconPerks_Lightweight.png":{"englishName":"Lightweight","owner":"Общий","role":"survivor","descriptionEn":"Your running is light and soft, making your tracks harder to follow.\nReduces the Lifetime of your Scratch Marks\nby 3/4/5 seconds.\nReduces the Spawn chance of patches of Scratch Marks by -60 %, making their spacing inconsistent.\n'live slow and die old'.\" — Dylan, The Lost Tapes","descriptionRu":"Ваш бег легкий и мягкий, поэтому следить за вашими следами становится сложнее.\nСокращает срок службы ваших царапин\nна 3/4/5 секунды.\nСнижает вероятность появления пятен с царапинами на -60 %, делая расстояние между ними непостоянным.\n«Живи медленно и умри старым»» — Дилан, «Потерянные ленты».","shortDescriptionRu":"Ваш бег легкий и мягкий, поэтому следить за вашими следами становится сложнее. Сокращает срок службы ваших царапин на 5 секунды. Снижает вероятность появления пятен с царапинами на -60%, делая расстояние между ними непостоянным.","upcomingPatch":false},"assets/perks/iconPerks_Lithe.png":{"englishName":"Lithe","owner":"Feng Min","role":"survivor","descriptionEn":"Whenever you perform a Rushed Vault action, Lithe triggers its effect:\nGrants a +50 % Haste\nStatus Effect for 3 seconds.\nLithe cannot be used while Exhausted.\nLithe causes the Exhausted\nStatus Effect for 60/50/40 seconds.","descriptionRu":"Каждый раз, когда вы выполняете действие «Быстрое хранилище», Гиб срабатывает его эффект:\nДает +50 % скорости.\nСтатусный эффект на 3 секунды.\nГибкость нельзя использовать, пока вы измотаны.\nГибкость вызывает истощение\nСтатусный эффект на 60/50/40 секунд.","shortDescriptionRu":"Каждый раз, когда вы выполняете действие «Быстрое хранилище», Гиб срабатывает его эффект: Дает +50% скорости. Статусный эффект на 3 секунды. Гибкость нельзя использовать, пока вы измотаны.","upcomingPatch":false},"assets/perks/iconPerks_LowProfile.png":{"englishName":"Low Profile","owner":"Ada Wong","role":"survivor","descriptionEn":"Whenever you are the only Survivor in the Trial not currently incapacitated by either being downed, carried, or hooked, Low Profile activates:\nSuppresses your Grunts of Pain and the creation of Pools of Blood\nand Scratch Marks\nfor 70/80/90 seconds.\nLow Profile deactivates after use and only accounts for Survivors still participating in the Trial.","descriptionRu":"Каждый раз, когда вы единственный выживший в Испытании, который в данный момент не выведен из строя из-за того, что вас сбили, унесли или зацепили на крючок, активируется режим «Низкий профиль»:\nПодавляет ваши стоны боли и образование луж крови.\nи царапины\nна 70/80/90 секунд.\nРежим «Низкий профиль» деактивируется после использования и учитывает только выживших, все еще участвующих в Испытании.","shortDescriptionRu":"Каждый раз, когда вы единственный выживший в Испытании, который в данный момент не выведен из строя из-за того, что вас сбили, унесли или зацепили на крючок, активируется режим «Низкий профиль»: Подавляет ваши стоны боли и образование луж крови. и царапины на 90 секунд. Режим «Низкий профиль» деактивируется после использования и учитывает только выживших, все еще участвующих в Испытании.","upcomingPatch":false},"assets/perks/iconPerks_LuckyBreak.png":{"englishName":"Lucky Break","owner":"Yui Kimura","role":"survivor","descriptionEn":"Whenever you are in the Injured State\n, Lucky Break activates:\nSuppresses the creation of Pools of Blood\nand Scratch Marks\nfor up to 40/50/60 seconds.\nWhenever you are healing another Survivor, Lucky Break recharges by the same amount of time spent performing the Healing action, up to its initial maximum.\nLucky Break deactivates once its timer runs out or whenever your Health State\nupdates to any other but the Injured State.\nNot even close.\" — Yui Kimura","descriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии\n, активируется Lucky Break:\nПодавляет образование луж крови.\nи царапины\nдо 40/50/60 секунд.\nКаждый раз, когда вы исцеляете другого Выжившего, Lucky Break перезаряжается на то же количество времени, затраченное на выполнение Исцеляющего действия, до первоначального максимума.\nLucky Break деактивируется, как только истечет его таймер или когда ваше состояние здоровья\nобновления для любого другого состояния, кроме поврежденного состояния.\nДаже близко» — Юи Кимура","shortDescriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии, активируется Lucky Break: Подавляет образование луж крови. и царапины до 60 секунд. Каждый раз, когда вы исцеляете другого Выжившего, Lucky Break перезаряжается на то же количество времени, затраченное на выполнение Исцеляющего действия, до первоначального максимума.","upcomingPatch":false},"assets/perks/iconPerks_LuckyStar.png":{"englishName":"Lucky Star","owner":"Ellen Ripley","role":"survivor","descriptionEn":"While hiding inside a Locker\n, you benefit from the following effect:\nSuppresses your Grunts of Pain.\nAfter exiting the Locker you benefit from the following effects for 30 seconds:\nSuppresses your Grunts of Pain and the creation of Pools of Blood\n.\nThe Auras\nof all other Survivors are revealed to you.\nThe Aura of the nearest Generator is revealed to you and highlighted in yellow.\nLucky Star has a cool-down of 35/30/25 seconds.","descriptionRu":"Прячась в шкафчике\n, вы получаете следующий эффект:\nПодавляет ваши стоны боли.\nПосле выхода из шкафчика вы получаете следующие эффекты в течение 30 секунд:\nПодавляет ваши стоны боли и образование луж крови.\n.\nАуры\nвсех остальных Выживших открываются вам.\nАура ближайшего Генератора открывается вам и выделяется желтым цветом.\nВремя восстановления Lucky Star составляет 35/30/25 секунд.","shortDescriptionRu":"Прячась в шкафчике, вы получаете следующий эффект: Подавляет ваши стоны боли. После выхода из шкафчика вы получаете следующие эффекты в течение 30 секунд: Подавляет ваши стоны боли и образование луж крови.. Ауры всех остальных Выживших открываются вам.","upcomingPatch":false},"assets/perks/IconPerks_madeForThis.png":{"englishName":"Made for This","owner":"Gabriel Soma","role":"survivor","descriptionEn":"Whenever you are in the Injured State\n, Made for This activates.\nWhile active, completing a Healing action on another Survivor triggers the following primary effect:\nGrants the Endurance\nStatus Effect for 6/8/10 seconds.\nEndurance is cancelled prematurely when performing a Conspicuous Action of any kind.\nWhile active and suffering from the Deep Wound\nStatus Effect, running triggers the following secondary effect:\nGrants a 1/2/3 % Haste\nStatus Effect.","descriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии\n, Активируется «Сделано для этого».\nПока активно, выполнение Исцеляющего действия на другом Выжившем вызывает следующий основной эффект:\nДает выносливость\nСтатусный эффект на 6/8/10 секунд.\nВыносливость преждевременно аннулируется при выполнении любого заметного действия.\nПока активен и страдает от глубокой раны\nЭффект статуса: бег вызывает следующий вторичный эффект:\nДает 1/2/3% скорости.\nЭффект статуса.","shortDescriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии, Активируется «Сделано для этого». Пока активно, выполнение Исцеляющего действия на другом Выжившем вызывает следующий основной эффект: Дает выносливость Статусный эффект на 10 секунд. Выносливость преждевременно аннулируется при выполнении любого заметного действия.","upcomingPatch":false},"assets/perks/iconPerks_MettleOfMan.png":{"englishName":"Mettle of Man","owner":"Ash Williams","role":"survivor","descriptionEn":"After triggering a third Protection Hit by any means, Mettle of Man activates:\nWhile in the Injured State\n, Mettle of Man shields you from the next attack that would put you into the Dying State\n.\nAfter healing back to full health by any means, Mettle of Man reveals your Aura\nto the Killer whenever you are farther than 12/14/16 metres from their location.\nMettle of Man deactivates after entering the Dying State by any means.\nIncreases your chance of becoming the initial Obsession by increasing the default value by +100 %.\nThe Killer can only be obsessed with one Survivor at a time.","descriptionRu":"После срабатывания третьего защитного удара любым способом активируется «Храбрость человека»:\nНаходясь в раненом состоянии\n, Мужество Человека защищает вас от следующей атаки, которая приведет вас в состояние умирания.\n.\nПосле восстановления полного здоровья любым способом «Храбрость человека» раскрывает вашу ауру.\nУбийце всякий раз, когда вы находитесь дальше, чем на 12/14/16 метров от их местоположения.\n«Храбрость человека» деактивируется после входа в состояние умирания любым способом.\nПовышает ваши шансы стать первоначальной одержимостью за счет увеличения значения по умолчанию на +100 %.\nУбийца может быть одержим только одним Выжившим одновременно.","shortDescriptionRu":"После срабатывания третьего защитного удара любым способом активируется «Храбрость человека»: Находясь в раненом состоянии, Мужество Человека защищает вас от следующей атаки, которая приведет вас в состояние умирания.. После восстановления полного здоровья любым способом «Храбрость человека» раскрывает вашу ауру. Убийце всякий раз, когда вы находитесь дальше, чем на 16 метров от их местоположения.","upcomingPatch":false},"assets/perks/iconPerks_MirroredIllusion.png":{"englishName":"Mirrored Illusion","owner":"Troupe","role":"survivor","descriptionEn":"A familiar spell made unfamiliar in this corrupted landscape.\nAfter repairing Generators for a total of 20 %, Mirrored Illusion activates:\nPress the Active Ability button when next to either a Chest\n, Exit Gate\n, Generator\n, or a Totem\nto spawn a Static Illusion that lasts for 40/50/60 seconds.\nMirrored Illusion deactivates after triggering successfully.","descriptionRu":"Знакомое заклинание стало незнакомым в этом испорченном ландшафте.\nПосле ремонта Генераторов на 20 % активируется Зеркальная Иллюзия:\nНажмите кнопку «Активная способность», когда рядом с сундуком\n, Выходные ворота\n, Генератор\n, или Тотем\nчтобы создать статическую иллюзию, которая длится 40/50/60 секунд.\nЗеркальная иллюзия деактивируется после успешного срабатывания.","shortDescriptionRu":"Знакомое заклинание стало незнакомым в этом испорченном ландшафте. После ремонта Генераторов на 20% активируется Зеркальная Иллюзия: Нажмите кнопку «Активная способность», когда рядом с сундуком, Выходные ворота, Генератор, или Тотем чтобы создать статическую иллюзию, которая длится 60 секунд. Зеркальная иллюзия деактивируется после успешного срабатывания.","upcomingPatch":false},"assets/perks/iconPerks_MomentOfGlory.png":{"englishName":"Moment of Glory","owner":"Trevor Belmont","role":"survivor","descriptionEn":"After performing the Unlocking or Rummaging action on Chests\na total of 1 time, Moment of Glory activates:\nWhen you become injured, you instantly suffer from the Broken\nStatus Effect.\nYou are automatically healed 1 Health State after 80/70/60 seconds.\nThis effect is cancelled prematurely if you enter the Dying State.\nMoment of Glory does not activate if you already suffer from the Broken Status Effect.\nMoment of Glory deactivates after healing you.","descriptionRu":"После выполнения действия «Разблокировка» или «Рошение» сундуков.\nвсего 1 раз активируется «Момент Славы»:\nКогда вы получаете травму, вы мгновенно страдаете от Сломанного.\nЭффект статуса.\nВы автоматически восстанавливаете 1 состояние здоровья через 80/70/60 секунд.\nЭтот эффект отменяется преждевременно, если вы входите в состояние умирания.\n«Момент славы» не активируется, если вы уже страдаете от эффекта «Сломанный статус».\n«Момент славы» деактивируется после вашего исцеления.","shortDescriptionRu":"После выполнения действия «Разблокировка» или «Рошение» сундуков. всего 1 раз активируется «Момент Славы»: Когда вы получаете травму, вы мгновенно страдаете от Сломанного. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_NoMither.png":{"englishName":"No Mither","owner":"David King","role":"survivor","descriptionEn":"Your thick blood coagulates practically instantly.\"\nYou suffer permanently from the Broken\nStatus Effect in exchange for the following benefits:\nSuppresses the creation of Pools of Blood\n.\nSuppresses your Grunts of Pain while in the Injured State\nor in the Dying State\n.\nUnlocks the Self-Recovery ability, allowing you to fully recover from the Dying State:\nIncreases the Recovery speed by 15/20/25 %.","descriptionRu":"Твоя густая кровь свертывается практически мгновенно».\nВы постоянно страдаете от Сломанного\nСтатусный эффект в обмен на следующие преимущества:\nПодавляет образование луж крови.\n.\nПодавляет ваши стоны боли в раненом состоянии.\nили в умирающем состоянии\n.\nОткрывает способность самовосстановления, позволяющую полностью выйти из состояния умирания:\nУвеличивает скорость восстановления на 15/20/25%.","shortDescriptionRu":"Твоя густая кровь свертывается практически мгновенно». Вы постоянно страдаете от Сломанного Статусный эффект в обмен на следующие преимущества: Подавляет образование луж крови.. Подавляет ваши стоны боли в раненом состоянии.","upcomingPatch":false},"assets/perks/iconPerks_NoOneLeftBehind.png":{"englishName":"No One Left Behind","owner":"Общий","role":"survivor","descriptionEn":"Once the Exit Gates\nare powered, No One Left Behind activates:\nThe Auras\nof all other Survivors are revealed to you.\nIncreases your Action speeds for Healing and Unhooking by 80/90/100 %.\nIncreases the strength and duration of the Haste Status Effect granted to Survivors you unhook by +10 % and +5 seconds respectively:\nCauses them to benefit from a 20 % Haste\nStatus Effect for 15 seconds.\nBut I believe we can outsmart and overthrow him if we work together.\nDon't be predictable and selfish!\" — Clyde, The Lost Tapes","descriptionRu":"Однажды Выходные Ворота\nвключены, активируется функция «Никто не останется позади»:\nАуры\nвсех остальных Выживших открываются вам.\nУвеличивает скорость действий при лечении и расцеплении на 80/90/100%.\nУвеличивает силу и продолжительность эффекта статуса ускорения, предоставленного выжившим, которого вы отцепили от крюка, на +10 % и +5 секунд соответственно:\nУвеличивает скорость на 20 %.\nСтатусный эффект на 15 секунд.\nНо я верю, что мы сможем перехитрить и свергнуть его, если будем работать вместе.\nНе будьте предсказуемыми и эгоистичными!» — Клайд, «Потерянные ленты».","shortDescriptionRu":"Однажды Выходные Ворота включены, активируется функция «Никто не останется позади»: Ауры всех остальных Выживших открываются вам. Увеличивает скорость действий при лечении и расцеплении на 100%. Увеличивает силу и продолжительность эффекта статуса ускорения, предоставленного выжившим, которого вы отцепили от крюка, на 10% и +5 секунд соответственно: Увеличивает скорость на 20%.","upcomingPatch":true},"assets/perks/iconPerks_ObjectOfObsession.png":{"englishName":"Object of Obsession","owner":"Laurie Strode","role":"survivor","descriptionEn":"Identical to Bound by Obsession\n.","descriptionRu":"Идентичен Bound by Obsession\n.","shortDescriptionRu":"Идентичен Bound by Obsession.","upcomingPatch":false},"assets/perks/iconPerks_OffTheRecord.png":{"englishName":"Off the Record","owner":"Zarina Kassir","role":"survivor","descriptionEn":"After being unhooked or unhooking yourself, Off the Record activates for 30/35/40 seconds:\nBlocks your Aura\nfrom being revealed.\nSuppresses your Grunts of Pain while in the Injured State\n.\nSuppresses the creation of your Scratch Marks\n.\nGrants the Endurance\nStatus Effect.\nEndurance is cancelled prematurely when performing a Conspicuous Action of any kind.\nOff the Record deactivates prematurely and is disabled for the remainder of the Trial upon powering the Exit Gates\n.","descriptionRu":"После того, как вас отцепили или отцепили самостоятельно, Off the Record активируется на 30/35/40 секунд:\nБлокирует вашу ауру\nот раскрытия.\nПодавляет ваши стоны боли в раненом состоянии.\n.\nПодавляет появление царапин.\n.\nДает выносливость\nЭффект статуса.\nВыносливость преждевременно аннулируется при выполнении любого заметного действия.\nВыключение записи отключается преждевременно и отключается до конца испытания после подачи питания на выходные ворота.\n.","shortDescriptionRu":"После того, как вас отцепили или отцепили самостоятельно, Off the Record активируется на 40 секунд: Блокирует вашу ауру от раскрытия. Подавляет ваши стоны боли в раненом состоянии.. Подавляет появление царапин..","upcomingPatch":false},"assets/perks/iconPerks_OpenHanded.png":{"englishName":"Open-Handed","owner":"Ace Visconti","role":"survivor","descriptionEn":"All Survivors benefit from the following permanent effect:\nIncreases the radius of all Aura-reading abilities by 8/12/16 metres.\nOpen-Handed only affects Auras\nthat emanate from the Survivor causing them.\nSurvivors can only be affected by one instance of Open-Handed at a time.","descriptionRu":"Все выжившие получают следующий постоянный эффект:\nУвеличивает радиус всех способностей чтения ауры на 8/12/16 метров.\nОткрытая рука действует только на ауры.\nкоторые исходят от Выжившего, вызывая их.\nНа выживших одновременно может воздействовать только один экземпляр «Открытой руки».","shortDescriptionRu":"Все выжившие получают следующий постоянный эффект: Увеличивает радиус всех способностей чтения ауры на 16 метров. Открытая рука действует только на ауры. которые исходят от Выжившего, вызывая их.","upcomingPatch":false},"assets/perks/iconPerks_Overzealous.png":{"englishName":"Overzealous","owner":"Haddie Kaur","role":"survivor","descriptionEn":"Fighting back against the Ravage motivates and inspires you.\nAfter cleansing or blessing a Totem\n, Overzealous activates:\nDull Totem: Increases your Repair speed by 8/9/10 %.\nHex Totem: Increases your Repair speed by 16/18/20 %.\nOverzealous deactivates after losing a Health State\nby any means.","descriptionRu":"Борьба с Опустошением мотивирует и вдохновляет вас.\nПосле очищения или благословения тотема\n, Чрезмерное усердие активирует:\nТупой тотем: увеличивает скорость ремонта на 8/9/10%.\nШестигранный тотем: увеличивает скорость ремонта на 16/18/20%.\nOverzealous деактивируется после потери состояния здоровья.\nлюбыми способами.","shortDescriptionRu":"Борьба с Опустошением мотивирует и вдохновляет вас. После очищения или благословения тотема, Чрезмерное усердие активирует: Тупой тотем: увеличивает скорость ремонта на 10%. Шестигранный тотем: увеличивает скорость ремонта на 20%.","upcomingPatch":false},"assets/perks/iconPerks_ParentalGuidance.png":{"englishName":"Parental Guidance","owner":"Yoichi Asakawa","role":"survivor","descriptionEn":"After stunning the Killer by any means, Parental Guidance triggers its effect:\nSuppresses your Grunts of Pain and the creation of Scratch Marks\nand Pools of Blood\nfor 5/6/7 seconds.","descriptionRu":"После оглушения Убийцы любым способом срабатывает эффект Родительского наставления:\nПодавляет ваши ворчания боли и образование царапин.\nи лужи крови\nна 5/6/7 секунд.","shortDescriptionRu":"После оглушения Убийцы любым способом срабатывает эффект Родительского наставления: Подавляет ваши ворчания боли и образование царапин. и лужи крови на 7 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Pharmacy.png":{"englishName":"Pharmacy","owner":"Quentin Smith","role":"survivor","descriptionEn":"While unlocking a Chest\n, you benefit from the following effects:\nIncreases the Unlocking and Rummaging speeds by 75/100/125 %.\nReduces the audible range of all noises related to the Unlocking interaction by -12 metres.\nGuarantees an Emergency Med-Kit\nafter completing the interaction.\nYou can rummage each chest 1 time.","descriptionRu":"При открытии сундука\n, вы получаете следующие эффекты:\nУвеличивает скорость открытия и поиска на 75/100/125%.\nУменьшает диапазон слышимости всех шумов, связанных с разблокировкой, на -12 метров.\nГарантирует наличие аптечки для неотложной помощи\nпосле завершения взаимодействия.\nКаждый сундук можно обшарить 1 раз.","shortDescriptionRu":"При открытии сундука, вы получаете следующие эффекты: Увеличивает скорость открытия и поиска на 125%. Уменьшает диапазон слышимости всех шумов, связанных с разблокировкой, на -12 метров. Гарантирует наличие аптечки для неотложной помощи после завершения взаимодействия.","upcomingPatch":true},"assets/perks/iconPerks_PlotTwist.png":{"englishName":"Plot Twist","owner":"Nicolas Cage","role":"survivor","descriptionEn":"Whenever you are in the Injured State\n, Plot Twist activates.\nWhile active, press the Active Ability button while crouching and stationary to trigger the following primary effects:\nSilently enter the Dying State\nwithout notifying the Killer.\nSuppresses your Grunts of Pain and the creation of Pools of Blood\n.\nUnlocks the Self-Recovery ability, allowing you to fully recover from the Dying State:\nIncreases the Recovery speed by +25 %.\nAfter self-recovering from the Dying State, you benefit from the following secondary effects:\nInstantly heals you to full health.\nGrants a +50 % Haste\nStatus Effect for 2/3/4 seconds.\nPlot Twist is disabled after recovering by any means, but can be reactivated once more upon powering the Exit Gates\n.","descriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии\n, Активируется поворот сюжета.\nВ активном состоянии нажмите кнопку «Активная способность», присев и неподвижно, чтобы активировать следующие основные эффекты:\nТихо войдите в состояние умирания\nне уведомив убийцу.\nПодавляет ваши стоны боли и образование луж крови.\n.\nОткрывает способность самовосстановления, позволяющую полностью выйти из состояния умирания:\nУвеличивает скорость восстановления на +25%.\nПосле самостоятельного выхода из состояния умирания вы получаете следующие побочные эффекты:\nМгновенно восстанавливает вам полное здоровье.\nДает +50 % скорости.\nСтатусный эффект на 2/3/4 секунды.\n«Поворот сюжета» отключается после восстановления любым способом, но может быть активирован еще раз при включении выходных ворот.\n.","shortDescriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии, Активируется поворот сюжета. В активном состоянии нажмите кнопку «Активная способность», присев и неподвижно, чтобы активировать следующие основные эффекты: Тихо войдите в состояние умирания не уведомив убийцу. Подавляет ваши стоны боли и образование луж крови..","upcomingPatch":false},"assets/perks/iconPerks_PlunderersInstinct.png":{"englishName":"Plunderer's Instinct","owner":"Общий","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof the following objects are revealed to you:\nClosed Chests\nlocated in the environment.\nItems\nsitting inside opened Chests.\nItems dropped in the environment.\nIncreases the chances of finding rarer Items inside Chests by +50 %.\nIncreases the unlocking speed of Chests by 150/175/200 %.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nВам открываются следующие объекты:\nЗакрытые сундуки\nнаходится в окружающей среде.\nПредметы\nсидя внутри открытых сундуков.\nПредметы, выпавшие в окружающую среду.\nУвеличивает шансы найти более редкие предметы в сундуках на +50 %.\nУвеличивает скорость открытия Сундуков на 150/175/200 %.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры Вам открываются следующие объекты: Закрытые сундуки находится в окружающей среде. Предметы сидя внутри открытых сундуков. Предметы, выпавшие в окружающую среду.","upcomingPatch":true},"assets/perks/iconPerks_Poised.png":{"englishName":"Poised","owner":"Jane Romero","role":"survivor","descriptionEn":"Whenever a Generator\nis completed, Poised triggers its primary effect:\nSuppresses the creation of your Scratch Marks\nfor 20/25/30 seconds.\nWhenever you start repairing a Generator for the first time, Poised triggers its secondary effect:\nThe Aura\nof the Killer is revealed to you for 8 seconds.","descriptionRu":"Всякий раз, когда генератор\nзавершено, Poused активирует свой основной эффект:\nПодавляет появление царапин.\nна 20/25/30 секунд.\nКаждый раз, когда вы впервые начинаете ремонтировать Генератор, «Уравновешенность» активирует свой вторичный эффект:\nАура\nУбийцы открываются вам на 8 секунд.","shortDescriptionRu":"Всякий раз, когда генератор завершено, Poused активирует свой основной эффект: Подавляет появление царапин. на 30 секунд. Каждый раз, когда вы впервые начинаете ремонтировать Генератор, «Уравновешенность» активирует свой вторичный эффект: Аура Убийцы открываются вам на 8 секунд.","upcomingPatch":false},"assets/perks/iconPerks_PotentialEnergy.png":{"englishName":"Potential Energy","owner":"Vittorio Toscano","role":"survivor","descriptionEn":"While repairing a Generator\n, press the Active Ability button to Store Potential Energy:\nRepair Charges no longer progress the Generator and are instead converted into Tokens:\nGain 1 Token for the equivalent of 1 % Progression, up to a maximum of 10/15/20 Tokens.\nFailed Repair Skill Checks incur a penalty depending on how many Tokens have been accumulated:\nNot at Token Limit: Reduces the number of accumulated Tokens by -20 %.\nAt Token Limit: Regresses the Generator by -10 %.\nHaving accumulated at least 1 Token, press the Active Ability button again on the same or a different Generator to Release Potential Energy:\nConsumes all accumulated Tokens.\nInstantly progresses that Generator by +1 % per Token.\nPotential Energy deactivates after use or losing a Health State\nby any means, and will lose all accumulated Tokens in case of the latter.","descriptionRu":"Во время ремонта генератора\n, нажмите кнопку «Активная способность», чтобы сохранить потенциальную энергию:\nЗаряды на ремонт больше не ускоряют работу Генератора, а вместо этого конвертируются в жетоны:\nПолучите 1 жетон, эквивалентный 1 % прогресса, но не более 10/15/20 жетонов.\nНеудачная проверка навыков ремонта влечет за собой штраф в зависимости от того, сколько жетонов было накоплено:\nНе достигнут лимит токенов: уменьшает количество накопленных токенов на -20 %.\nПри лимите токенов: снижает производительность генератора на -10 %.\nНакопив хотя бы 1 жетон, еще раз нажмите кнопку активной способности на том же или другом генераторе, чтобы высвободить потенциальную энергию:\nПотребляет все накопленные токены.\nМгновенно улучшает этот Генератор на +1 % за каждый токен.\nПотенциальная энергия деактивируется после использования или потери состояния здоровья.\nлюбыми способами и в последнем случае потеряет все накопленные Токены.","shortDescriptionRu":"Во время ремонта генератора, нажмите кнопку «Активная способность», чтобы сохранить потенциальную энергию: Заряды на ремонт больше не ускоряют работу Генератора, а вместо этого конвертируются в жетоны: Получите 1 жетон, эквивалентный 1% прогресса, но не более 20 жетонов.","upcomingPatch":false},"assets/perks/iconPerks_PowerStruggle.png":{"englishName":"Power Struggle","owner":"%C3%89lodie Rakoto","role":"survivor","descriptionEn":"Whenever you are in the Dying State\n, you benefit from the following primary effect:\nThe Auras\nof upright Pallets\nare revealed to you.\nAfter reaching 25/20/15 % of Wiggle progression, Power Struggle unlocks the following secondary effect:\nGrants the ability to drop a nearby Pallet while being carried by the Killer.\nStuns the Killer and causes them to release you from their grasp.\nPower Struggle deactivates after use.","descriptionRu":"Всякий раз, когда вы находитесь в состоянии умирания\n, вы получаете следующий основной эффект:\nАуры\nвертикальных поддонов\nоткрываются вам.\nПосле достижения 25/20/15% прогресса покачивания, борьба за власть открывает следующий вторичный эффект:\nПредоставляет возможность бросить ближайший поддон, пока его несет Убийца.\nОглушает Убийцу и заставляет его высвободить вас из своих рук.\nPower Struggle деактивируется после использования.","shortDescriptionRu":"Всякий раз, когда вы находитесь в состоянии умирания, вы получаете следующий основной эффект: Ауры вертикальных поддонов открываются вам. После достижения 15% прогресса покачивания, борьба за власть открывает следующий вторичный эффект: Предоставляет возможность бросить ближайший поддон, пока его несет Убийца. Оглушает Убийцу и заставляет его высвободить вас из своих рук.","upcomingPatch":false},"assets/perks/iconPerks_Premonition.png":{"englishName":"Premonition","owner":"Общий","role":"survivor","descriptionEn":"While not being chased, looking in the Killer's direction within a range of 32 metres triggers Premonition:\nTriggers an audio cue\nReveals the Killer's aura for 3 seconds.\nPremonition has a cool-down of 70/65/60 seconds.","descriptionRu":"Если вас не преследуют, если посмотреть в сторону Убийцы на расстоянии до 32 метров, активируется Предчувствие:\nЗапускает звуковой сигнал\nРаскрывает ауру Убийцы на 3 секунды.\nПредчувствие имеет время восстановления 70/65/60 секунд.","shortDescriptionRu":"Если вас не преследуют, если посмотреть в сторону Убийцы на расстоянии до 32 метров, активируется Предчувствие: Запускает звуковой сигнал Раскрывает ауру Убийцы на 3 секунды. Предчувствие имеет время восстановления 60 секунд.","upcomingPatch":true},"assets/perks/iconPerks_ProveThyself.png":{"englishName":"Prove Thyself","owner":"Dwight Fairfield","role":"survivor","descriptionEn":"Increases the Repair speed by a stack-able 6/8/10 % per other Survivor within 4 metres of your location, up to a maximum of 18/24/30 %.\nProve Thyself extends its effect to all Survivors within its range.\nSurvivors can only be affected by one instance of Prove Thyself at a time.","descriptionRu":"Увеличивает скорость ремонта на 6/8/10 % за каждого другого выжившего в радиусе 4 метров от вашего местоположения, максимум до 18/24/30 %.\n«Прояви себя» распространяется на всех выживших в радиусе действия способности.\nНа выживших одновременно может действовать только один экземпляр «Прояви себя».","shortDescriptionRu":"Увеличивает скорость ремонта на 10% за каждого другого выжившего в радиусе 4 метров от вашего местоположения, максимум до 30%. «Прояви себя» распространяется на всех выживших в радиусе действия способности. На выживших одновременно может действовать только один экземпляр «Прояви себя».","upcomingPatch":false},"assets/perks/iconPerks_pushThroughIt.png":{"englishName":"Second Wind","owner":"Steve Harrington","role":"survivor","descriptionEn":"Part of you still thinks your best option is to run away and hope things will take care of themselves.\"\nWhen you heal another Survivor\nfor the equivalent of 1 Health State\n, Second Wind activates:\nThe next time you are unhooked or unhook yourself, you suffer from the Broken\nStatus Effect until Second Wind deactivates.\nYou are automatically healed 1 Health State after 28/24/20 seconds.\nWhile Second Wind is active, the following conditions will deactivate it:\nSuccessfully being healed by Second Wind.\nBeing put into the Dying State\nbefore the timer elapses.\nSecond Wind does not activate if you already suffer from the Broken Status Effect.","descriptionRu":"Часть вас все еще думает, что лучший вариант — сбежать и надеяться, что все пойдет само собой».\nКогда вы исцеляете другого Выжившего\nза эквивалент 1 состояния здоровья\n, Второе дыхание активируется:\nВ следующий раз, когда вас отцепят или отцепят сами, вы пострадаете от Сломанного\nЭффект статуса до тех пор, пока Второе дыхание не деактивируется.\nВы автоматически восстанавливаете 1 состояние здоровья через 28/24/20 секунд.\nПока «Второе дыхание» активно, следующие условия отключают его:\nУспешно исцелился с помощью «Второго дыхания».\nПомещение в умирающее состояние\nдо того, как истечет таймер.\nВторое дыхание не активируется, если вы уже страдаете от эффекта разбитого статуса.","shortDescriptionRu":"Часть вас все еще думает, что лучший вариант — сбежать и надеяться, что все пойдет само собой». Когда вы исцеляете другого Выжившего за эквивалент 1 состояния здоровья, Второе дыхание активируется: В следующий раз, когда вас отцепят или отцепят сами, вы пострадаете от Сломанного Эффект статуса до тех пор, пока Второе дыхание не деактивируется.","upcomingPatch":false},"assets/perks/iconPerks_QuickAndQuiet.png":{"englishName":"Quick & Quiet","owner":"Meg Thomas","role":"survivor","descriptionEn":"When performing a Rushed action to vault across Pallets\nor Windows\n, or to enter or exit Lockers\n, Quick & Quiet triggers its effect:\nSuppresses all noises related to those interactions and the accompanying Loud Noise Notification.\nQuick & Quiet has a cool-down of 25/20/15 seconds.","descriptionRu":"При выполнении срочного действия по перебежке через поддоны\nили Windows\nили для входа или выхода из шкафчиков\n, Quick & Quiet активирует свой эффект:\nПодавляет все шумы, связанные с этими взаимодействиями, и сопровождающее их уведомление о громком шуме.\nQuick & Quiet имеет время восстановления 25/20/15 секунд.","shortDescriptionRu":"При выполнении срочного действия по перебежке через поддоны или Windows или для входа или выхода из шкафчиков, Quick & Quiet активирует свой эффект: Подавляет все шумы, связанные с этими взаимодействиями, и сопровождающее их уведомление о громком шуме. Quick & Quiet имеет время восстановления 15 секунд.","upcomingPatch":false},"assets/perks/iconPerks_ReactiveHealing.png":{"englishName":"Reactive Healing","owner":"Ada Wong","role":"survivor","descriptionEn":"Whenever another Survivor within 32 metres of your location loses a Health State\nby any means while you are in the Injured State\n, you benefit from the following effect:\nGrants 40/45/50 % of your missing Healing Progression towards your Health Bar.","descriptionRu":"Каждый раз, когда другой Выживший в радиусе 32 метров от вашего местоположения теряет состояние здоровья.\nлюбыми способами, пока вы находитесь в повреждённом состоянии\n, вы получаете следующий эффект:\nПредоставляет 40/45/50 % недостающего прогресса исцеления к вашей шкале здоровья.","shortDescriptionRu":"Каждый раз, когда другой Выживший в радиусе 32 метров от вашего местоположения теряет состояние здоровья. любыми способами, пока вы находитесь в повреждённом состоянии, вы получаете следующий эффект: Предоставляет 50% недостающего прогресса исцеления к вашей шкале здоровья.","upcomingPatch":false},"assets/perks/iconPerks_Reassurance.png":{"englishName":"Reassurance","owner":"Rebecca Chambers","role":"survivor","descriptionEn":"While within 6 metres of a hooked Survivor, press the Active Ability button to trigger the following effects for 20/25/30 seconds:\nPauses the Sacrifice Process.\nThis also pauses the Struggle Skill Checks for Survivors in the Struggle Phase.\nCauses the outline of that Survivor to be highlighted in white.\nReassurance can only be used once per Survivor per Hook Instance.","descriptionRu":"Находясь в пределах 6 метров от подключённого Выжившего, нажмите кнопку активной способности, чтобы активировать следующие эффекты на 20/25/30 секунд:\nПриостанавливает процесс жертвоприношения.\nЭто также приостанавливает проверки навыков борьбы для выживших в фазе борьбы.\nВыделяет контур этого Выжившего белым.\nЗаверение можно использовать только один раз на каждого Выжившего в каждом экземпляре Крюка.","shortDescriptionRu":"Находясь в пределах 6 метров от подключённого Выжившего, нажмите кнопку активной способности, чтобы активировать следующие эффекты на 30 секунд: Приостанавливает процесс жертвоприношения. Это также приостанавливает проверки навыков борьбы для выживших в фазе борьбы. Выделяет контур этого Выжившего белым.","upcomingPatch":false},"assets/perks/iconPerks_RedHerring.png":{"englishName":"Red Herring","owner":"Zarina Kassir","role":"survivor","descriptionEn":"After repairing a Generator\nfor at least 1 second, Red Herring triggers its primary effect:\nThe Aura\nof that Generator is highlighted to you in yellow.\nThe highlight persists until either of the following occurs:\nThe Generator is completed.\nYou start repairing a different Generator.\nYou enter a Locker.\nWhen entering a Locker\n, Red Herring triggers its secondary effect:\nTriggers a Loud Noise Notification for the Killer on the highlighted Generator.\nRed Herring has a cool-down of 25/20/15 seconds.","descriptionRu":"После ремонта генератора\nминимум на 1 секунду отвлекающий маневр активирует свой основной эффект:\nАура\nэтого Генератора выделен желтым цветом.\nПодсветка сохраняется до тех пор, пока не произойдет одно из следующих событий:\nГенератор готов.\nВы начинаете ремонтировать другой Генератор.\nВы входите в шкафчик.\nПри входе в шкафчик\n, отвлекающий маневр вызывает вторичный эффект:\nВызывает громкое звуковое уведомление для убийцы на выделенном генераторе.\nRed Herring имеет время восстановления 25/20/15 секунд.","shortDescriptionRu":"После ремонта генератора минимум на 1 секунду отвлекающий маневр активирует свой основной эффект: Аура этого Генератора выделен желтым цветом. Подсветка сохраняется до тех пор, пока не произойдет одно из следующих событий: Генератор готов. Вы начинаете ремонтировать другой Генератор.","upcomingPatch":false},"assets/perks/iconPerks_RepressedAlliance.png":{"englishName":"Repressed Alliance","owner":"Cheryl Mason","role":"survivor","descriptionEn":"You are accustomed to being hunted by malicious forces, and you have begun using it to your advantage.\nAfter repairing Generators\nfor a total of 40/35/30 seconds, Repressed Alliance activates:\nPress the Active Ability button to call upon The Entity\nto block the Generator you are currently repairing for 15 seconds, after which Repressed Alliance deactivates.\nThe Aura\nof the blocked Generator is revealed to all Survivors in white.\nRepressed Alliance can only be triggered when no other Survivors are repairing your Generator.","descriptionRu":"Вы привыкли к тому, что за вами охотятся злые силы, и начали использовать это в своих целях.\nПосле ремонта генераторов\nв общей сложности на 40/35/30 секунд активируется Подавленный Альянс:\nНажмите кнопку «Активная способность», чтобы призвать Сущность.\nчтобы заблокировать Генератор, который вы сейчас ремонтируете, на 15 секунд, после чего Подавленный альянс деактивируется.\nАура\nзаблокированного Генератора отображается всем Выжившим в белом цвете.\nПодавленный альянс может быть активирован только в том случае, если другие выжившие не ремонтируют ваш генератор.","shortDescriptionRu":"Вы привыкли к тому, что за вами охотятся злые силы, и начали использовать это в своих целях. После ремонта генераторов в общей сложности на 30 секунд активируется Подавленный Альянс: Нажмите кнопку «Активная способность», чтобы призвать Сущность. чтобы заблокировать Генератор, который вы сейчас ремонтируете, на 15 секунд, после чего Подавленный альянс деактивируется.","upcomingPatch":false},"assets/perks/iconPerks_ResidualManifest.png":{"englishName":"Residual Manifest","owner":"Haddie Kaur","role":"survivor","descriptionEn":"A lifetime of chasing the darkness has taught you that the best disinfectant is light.\nAfter a successful Killer Blind, the Killer suffers from the Blindness\nStatus Effect for 20/25/30 seconds.\nResidual Manifest grants the ability to rummage through an opened Chest\nonce per Trial and will guarantee a basic Flashlight\n.","descriptionRu":"Жизнь в погоне за тьмой научила вас тому, что лучшее дезинфицирующее средство — это свет.\nПосле успешного Ослепления Убийцы Убийца страдает от Слепоты.\nСтатусный эффект на 20/25/30 секунд.\nОстаточный манифест дает возможность рыться в открытом сундуке.\nодин раз за пробную версию и гарантирует базовый фонарик.\n.","shortDescriptionRu":"Жизнь в погоне за тьмой научила вас тому, что лучшее дезинфицирующее средство — это свет. После успешного Ослепления Убийцы Убийца страдает от Слепоты. Статусный эффект на 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Resilience.png":{"englishName":"Resilience","owner":"Общий","role":"survivor","descriptionEn":"Whenever you are in the Injured State\n, Resilience activates:\nIncreases the Action speeds for the following interactions by 7/8/9 %:\nBlessing or Cleansing Totems\n.\nHealing yourself or other Survivors\n.\nOpening Exit Gates\n.\nRepairing Generators\n.\nSabotaging Hooks\n.\nSearching Chests\n.\nUnhooking other Survivors.\nVaulting Windows\n.","descriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии\n, Устойчивость активируется:\nУвеличивает скорость действий для следующих взаимодействий на 7/8/9 %:\nБлагословляющие или очищающие тотемы\n.\nИсцеление себя или других выживших\n.\nОткрытие выходных ворот\n.\nРемонт генераторов\n.\nСаботажные крючки\n.\nПоиск сундуков\n.\nОтцепление других выживших.\nСводчатые окна\n.","shortDescriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии, Устойчивость активируется: Увеличивает скорость действий для следующих взаимодействий на 9%: Благословляющие или очищающие тотемы. Исцеление себя или других выживших. Открытие выходных ворот.","upcomingPatch":true},"assets/perks/iconPerks_Resurgence.png":{"englishName":"Resurgence","owner":"Jill Valentine","role":"survivor","descriptionEn":"After you are unhooked by any means, Resurgence triggers the following effect:\nGrants you 50/60/70 % of Healing progression.","descriptionRu":"После того, как вас каким-либо образом отцепят, «Возрождение» вызывает следующий эффект:\nДает вам 50/60/70% прогресса исцеления.","shortDescriptionRu":"После того, как вас каким-либо образом отцепят, «Возрождение» вызывает следующий эффект: Дает вам 70% прогресса исцеления.","upcomingPatch":false},"assets/perks/iconPerks_RookieSpirit.png":{"englishName":"Rookie Spirit","owner":"Leon Scott Kennedy","role":"survivor","descriptionEn":"You keep a careful eye on objectives when they are slipping away.\nWhile repairing Generators\n, succeed 5/4/3 Good or Great Skill Checks\nto activate Rookie Spirit for the remainder of the Trial:\nThe Auras\nof any regressing Generators are revealed to you until they stop regressing by any means.","descriptionRu":"Вы внимательно следите за целями, когда они ускользают.\nПри ремонте генераторов\n, преуспейте в 5/4/3 проверках хороших или отличных навыков.\nчтобы активировать Дух новичка на оставшуюся часть Испытания:\nАуры\nЛюбые регрессирующие Генераторы открываются вам до тех пор, пока они любыми способами не перестанут регрессировать.","shortDescriptionRu":"Вы внимательно следите за целями, когда они ускользают. При ремонте генераторов, преуспейте в 3 проверках хороших или отличных навыков. чтобы активировать Дух новичка на оставшуюся часть Испытания: Ауры Любые регрессирующие Генераторы открываются вам до тех пор, пока они любыми способами не перестанут регрессировать.","upcomingPatch":false},"assets/perks/iconPerks_Saboteur.png":{"englishName":"Saboteur","owner":"Jake Park","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nWhile the Killer is carrying another Survivor, the Auras\nof all Hooks\nwithin 56 metres of their original Pick-up location are revealed to you:\nThe Auras of normal Hooks are white.\nThe Auras of Scourge Hooks are yellow.\nUnlocks the ability to sabotage Hooks without Toolboxes\n:\nIncreases the Sabotage speed without a Toolbox by +30 %.\nThis effect has a cool-down of 70/65/60 seconds after use.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nПока Убийца несет еще одного Выжившего, Ауры\nиз всех крючков\nВ пределах 56 метров от места их первоначального получения вам будут показаны:\nАуры обычных Крюков белые.\nАуры Плетевых Крюков желтые.\nОткрывает возможность саботировать крючки без ящиков для инструментов.\n:\nУвеличивает скорость саботажа без ящика с инструментами на +30 %.\nЭтот эффект имеет время восстановления 70/65/60 секунд после использования.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Пока Убийца несет еще одного Выжившего, Ауры из всех крючков В пределах 56 метров от места их первоначального получения вам будут показаны: Ауры обычных Крюков белые. Ауры Плетевых Крюков желтые. Открывает возможность саботировать крючки без ящиков для инструментов.: Увеличивает скорость саботажа без ящика с инструментами на 30%.","upcomingPatch":false},"assets/perks/IconPerks_scavenger.png":{"englishName":"Scavenger","owner":"Gabriel Soma","role":"survivor","descriptionEn":"While holding a depleted Toolbox, Scavenger activates:\nSucceeding at Great Repairing Skill Checks grants 1 Token, up to a maximum of 5 Tokens.\nReaching the maximum number of Tokens automatically consumes them and fully recharges the Toolbox.\nRecharging a Toolbox will reduce your Repair speed by -50 % for the next 40/35/30 seconds.\nScavenger grants the ability to rummage through an opened Chest\nonce per Trial and will guarantee a basic Toolbox\n.","descriptionRu":"Удерживая пустой ящик с инструментами, Мусорщик активирует:\nУспешная проверка навыков великого ремонта дает 1 жетон, максимум до 5 жетонов.\nДостижение максимального количества жетонов автоматически расходует их и полностью перезаряжает Набор инструментов.\nПерезарядка ящика с инструментами снизит скорость ремонта на -50 % на следующие 40/35/30 секунд.\nScavenger дает возможность рыться в открытом сундуке.\nодин раз за пробную версию и гарантирует базовый набор инструментов.\n.","shortDescriptionRu":"Удерживая пустой ящик с инструментами, Мусорщик активирует: Успешная проверка навыков великого ремонта дает 1 жетон, максимум до 5 жетонов. Достижение максимального количества жетонов автоматически расходует их и полностью перезаряжает Набор инструментов. Перезарядка ящика с инструментами снизит скорость ремонта на -50% на следующие 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_ScenePartner.png":{"englishName":"Scene Partner","owner":"Nicolas Cage","role":"survivor","descriptionEn":"Whenever you are inside the Terror Radius\n, Scene Partner activates:\nLooking at the Killer causes you to scream, which reveals their Aura\nfor 4/5/6 seconds.\nThere is a chance of 50 % that you will scream again, extending the Aura-reveal duration by another +2 seconds.\nScene Partner has a cool-down of 40 seconds.","descriptionRu":"Всякий раз, когда вы находитесь внутри радиуса террора\n, Партнер сцены активирует:\nВзгляд на Убийцу заставляет вас кричать, что раскрывает его ауру.\nна 4/5/6 секунд.\nСуществует вероятность 50 %, что вы снова закричите, продлевая продолжительность раскрытия ауры еще на +2 секунды.\nВремя восстановления Scene Partner составляет 40 секунд.","shortDescriptionRu":"Всякий раз, когда вы находитесь внутри радиуса террора, Партнер сцены активирует: Взгляд на Убийцу заставляет вас кричать, что раскрывает его ауру. на 6 секунд. Существует вероятность 50%, что вы снова закричите, продлевая продолжительность раскрытия ауры еще на 2 секунды.","upcomingPatch":false},"assets/perks/iconPerks_secondWind.png":{"englishName":"Second Wind","owner":"Steve Harrington","role":"survivor","descriptionEn":"Part of you still thinks your best option is to run away and hope things will take care of themselves.\"\nWhen you heal another Survivor\nfor the equivalent of 1 Health State\n, Second Wind activates:\nThe next time you are unhooked or unhook yourself, you suffer from the Broken\nStatus Effect until Second Wind deactivates.\nYou are automatically healed 1 Health State after 28/24/20 seconds.\nWhile Second Wind is active, the following conditions will deactivate it:\nSuccessfully being healed by Second Wind.\nBeing put into the Dying State\nbefore the timer elapses.\nSecond Wind does not activate if you already suffer from the Broken Status Effect.","descriptionRu":"Часть вас все еще думает, что лучший вариант — сбежать и надеяться, что все пойдет само собой».\nКогда вы исцеляете другого Выжившего\nза эквивалент 1 состояния здоровья\n, Второе дыхание активируется:\nВ следующий раз, когда вас отцепят или отцепят сами, вы пострадаете от Сломанного\nЭффект статуса до тех пор, пока Второе дыхание не деактивируется.\nВы автоматически восстанавливаете 1 состояние здоровья через 28/24/20 секунд.\nПока «Второе дыхание» активно, следующие условия отключают его:\nУспешно исцелился с помощью «Второго дыхания».\nПомещение в умирающее состояние\nдо того, как истечет таймер.\nВторое дыхание не активируется, если вы уже страдаете от эффекта разбитого статуса.","shortDescriptionRu":"Часть вас все еще думает, что лучший вариант — сбежать и надеяться, что все пойдет само собой». Когда вы исцеляете другого Выжившего за эквивалент 1 состояния здоровья, Второе дыхание активируется: В следующий раз, когда вас отцепят или отцепят сами, вы пострадаете от Сломанного Эффект статуса до тех пор, пока Второе дыхание не деактивируется.","upcomingPatch":false},"assets/perks/iconPerks_Self-Preservation.png":{"englishName":"Self-Preservation","owner":"Lee Yun-jin","role":"survivor","descriptionEn":"The more confirmation you get of that, the more prepared you become.\"\nWhenever another Survivor is hooked, Self-Preservation triggers its effect:\nGrants the Elusive\nStatus Effect for 13/14/15 seconds","descriptionRu":"Чем больше подтверждений вы получите от этого, тем более подготовленными вы станете».\nКаждый раз, когда другой Выживший попадает на крючок, срабатывает эффект Самосохранения:\nДарует неуловимое\nСтатусный эффект на 13/14/15 секунд.","shortDescriptionRu":"Чем больше подтверждений вы получите от этого, тем более подготовленными вы станете». Каждый раз, когда другой Выживший попадает на крючок, срабатывает эффект Самосохранения: Дарует неуловимое Статусный эффект на 15 секунд.","upcomingPatch":true},"assets/perks/IconPerks_SelfAware.png":{"englishName":"Fixated","owner":"Nancy Wheeler","role":"survivor","descriptionEn":"You benefit from the following permanent effects:\nIncreases your Walking speed by 10/15/20 %.\nUnlocks the ability to see your own Scratch Marks\n.","descriptionRu":"Вы получаете следующие постоянные эффекты:\nУвеличивает скорость ходьбы на 10/15/20%.\nОткрывает возможность видеть свои собственные царапины.\n.","shortDescriptionRu":"Вы получаете следующие постоянные эффекты: Увеличивает скорость ходьбы на 20%. Открывает возможность видеть свои собственные царапины..","upcomingPatch":false},"assets/perks/iconPerks_SelfCare.png":{"englishName":"Self-Care","owner":"Claudette Morel","role":"survivor","descriptionEn":"Unlocks the Self-Care ability:\nGrants the ability to self-heal without needing a Med-Kit\nat 25/30/35 % of the regular Healing speed.","descriptionRu":"Открывает способность «Забота о себе»:\nПредоставляет возможность самоисцеления без необходимости использования аптечки.\nсо скоростью 25/30/35 % от обычной скорости исцеления.","shortDescriptionRu":"Открывает способность «Забота о себе»: Предоставляет возможность самоисцеления без необходимости использования аптечки. со скоростью 35% от обычной скорости исцеления.","upcomingPatch":false},"assets/perks/iconPerks_situationalAwareness.png":{"englishName":"Better Together","owner":"Nancy Wheeler","role":"survivor","descriptionEn":"While repairing any Generator\n, you and the other Survivors benefit from the following primary effect:\nThe Aura\nof that Generator is revealed to all Survivors and highlighted in yellow.\nWhenever the Killer downs another Survivor while you are repairing, you benefit from the following secondary effect:\nThe Auras of all Survivors are revealed to you for 20/25/30 seconds.","descriptionRu":"При ремонте любого генератора\n, вы и другие Выжившие получаете следующий основной эффект:\nАура\nИнформация об этом Генераторе видна всем Выжившим и выделена желтым цветом.\nКаждый раз, когда Убийца сбивает другого Выжившего, пока вы ремонтируете, вы получаете следующий вторичный эффект:\nАуры всех Выживших открываются вам на 20/25/30 секунд.","shortDescriptionRu":"При ремонте любого генератора, вы и другие Выжившие получаете следующий основной эффект: Аура Информация об этом Генераторе видна всем Выжившим и выделена желтым цветом. Каждый раз, когда Убийца сбивает другого Выжившего, пока вы ремонтируете, вы получаете следующий вторичный эффект: Ауры всех Выживших открываются вам на 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_SlipperyMeat.png":{"englishName":"Slippery Meat","owner":"Общий","role":"survivor","descriptionEn":"You have developed an efficient way to get off Hooks.\nOther Survivors unhook you 90/95/100 % faster.\nIncreases the Haste\ngranted by Unhook Protections by +5 %.","descriptionRu":"Вы разработали эффективный способ избавиться от крючков.\nДругие Выжившие отцепят вас на 90/95/100% быстрее.\nУвеличивает скорость\nпредоставляется Защитой от отсоединения на +5 %.","shortDescriptionRu":"Вы разработали эффективный способ избавиться от крючков. Другие Выжившие отцепят вас на 100% быстрее. Увеличивает скорость предоставляется Защитой от отсоединения на 5%.","upcomingPatch":true},"assets/perks/iconPerks_SmallGame.png":{"englishName":"Small Game","owner":"Общий","role":"survivor","descriptionEn":"See auras of Totems\nwithin 10/11/12 metres.","descriptionRu":"Увидеть ауры Тотемов\nв пределах 10/11/12 метров.","shortDescriptionRu":"Увидеть ауры Тотемов в пределах 12 метров.","upcomingPatch":true},"assets/perks/iconPerks_SmashHit.png":{"englishName":"Smash Hit","owner":"Lee Yun-jin","role":"survivor","descriptionEn":"Whenever you stun the Killer with a Pallet\n, Smash Hit triggers its effect:\nGrants a +50 % Haste\nStatus Effect for 4 seconds.\nSmash Hit cannot be used while Exhausted.\nSmash Hit causes the Exhausted\nStatus Effect for 30/25/20 seconds.","descriptionRu":"Каждый раз, когда вы оглушаете Убийцу паллетой\n, Smash Hit активирует свой эффект:\nДает +50 % скорости.\nСтатусный эффект на 4 секунды.\nSmash Hit нельзя использовать, пока вы измотаны.\nSmash Hit вызывает истощение\nСтатусный эффект на 30/25/20 секунд.","shortDescriptionRu":"Каждый раз, когда вы оглушаете Убийцу паллетой, Smash Hit активирует свой эффект: Дает +50% скорости. Статусный эффект на 4 секунды. Smash Hit нельзя использовать, пока вы измотаны.","upcomingPatch":false},"assets/perks/iconPerks_SoleSurvivor.png":{"englishName":"Sole Survivor","owner":"Laurie Strode","role":"survivor","descriptionEn":"Identical to Down to the Last\n.","descriptionRu":"Идентичен «До последнего»\n.","shortDescriptionRu":"Идентичен «До последнего».","upcomingPatch":false},"assets/perks/iconPerks_Solidarity.png":{"englishName":"Solidarity","owner":"Jane Romero","role":"survivor","descriptionEn":"While injured, healing another Survivor causes Solidarity to apply the following effects:\nGrants the ability to passively heal yourself while healing other Survivors.\nReduces your Personal Healing speed to 65/70/75 % of your Altruistic Healing speed.","descriptionRu":"При ранении исцеление другого Выжившего заставляет Солидарность применять следующие эффекты:\nПредоставляет возможность пассивно исцелять себя, одновременно исцеляя других Выживших.\nСнижает вашу скорость личного исцеления до 65/70/75 % от скорости альтруистического исцеления.","shortDescriptionRu":"При ранении исцеление другого Выжившего заставляет Солидарность применять следующие эффекты: Предоставляет возможность пассивно исцелять себя, одновременно исцеляя других Выживших. Снижает вашу скорость личного исцеления до 75% от скорости альтруистического исцеления.","upcomingPatch":true},"assets/perks/iconPerks_SoulGuard.png":{"englishName":"Soul Guard","owner":"Cheryl Mason","role":"survivor","descriptionEn":"Whenever you heal or recover from the Dying State\n, Soul Guard triggers its primary effect:\nGrants the Endurance\nStatus Effect for 4/6/8 seconds.\nEndurance is cancelled prematurely when performing a Conspicuous Action of any kind.\nThis ability has a cool-down of 30 seconds.\nWhile suffering from the Cursed\nStatus Effect, Soul Guard applies its secondary effect:\nUnlocks the Self-Recovery ability, allowing you to fully recover from the Dying State..","descriptionRu":"Всякий раз, когда вы исцеляетесь или выходите из состояния умирания\n, Soul Guard активирует свой основной эффект:\nДает выносливость\nСтатусный эффект на 4/6/8 секунд.\nВыносливость преждевременно аннулируется при выполнении любого заметного действия.\nВремя восстановления этой способности составляет 30 секунд.\nСтрадая от проклятия\nЭффект статуса, Soul Guard применяет свой дополнительный эффект:\nОткрывает способность самовосстановления, позволяющую полностью выйти из состояния умирания.","shortDescriptionRu":"Всякий раз, когда вы исцеляетесь или выходите из состояния умирания, Soul Guard активирует свой основной эффект: Дает выносливость Статусный эффект на 8 секунд. Выносливость преждевременно аннулируется при выполнении любого заметного действия. Время восстановления этой способности составляет 30 секунд.","upcomingPatch":false},"assets/perks/iconPerks_Specialist.png":{"englishName":"Specialist","owner":"Lara Croft","role":"survivor","descriptionEn":"Adventure. Exploration. Excavation.\nYou are in your element.\nWhenever you unlock or rummage through a Chest\n, Specialist gains +1 Token, up to a maximum of 6 Tokens:\nSucceeding a Great Repair Skill Check while repairing a Generator\nconsumes all Tokens.\nPermanently reduces the Repair Charges requirement of that Generator by 2/3/4 Charges per Token, up to a maximum of 12/18/24 Charges.","descriptionRu":"Приключение. Разведка. Раскопки.\nВы в своей стихии.\nКаждый раз, когда вы открываете или роетесь в сундуке\n, Специалист получает +1 жетон, максимум до 6 жетонов:\nУспешная проверка навыка ремонта при ремонте генератора\nпотребляет все токены.\nНавсегда снижает потребность в ремонтных зарядах для этого генератора на 2/3/4 заряда за каждый жетон, максимум до 12/18/24 зарядов.","shortDescriptionRu":"Приключение. Разведка. Раскопки.","upcomingPatch":false},"assets/perks/iconPerks_SpineChill.png":{"englishName":"Spine Chill","owner":"Общий","role":"survivor","descriptionEn":"An unnatural tingle warns you of impending doom.\nWhenever the Killer is within 40 metres of your location and is looking at you, Spine Chill activates:\nYou are notified.\nYou cannot scream for 12 seconds.\nYou vault +10 % faster for 12 seconds.\nSpine Chill then goes on a 40/35/30 seconds cool-down.","descriptionRu":"Неестественное покалывание предупреждает вас о надвигающейся гибели.\nВсякий раз, когда Убийца находится в пределах 40 метров от вашего местоположения и смотрит на вас, активируется Spine Chill:\nВы уведомлены.\nВы не можете кричать в течение 12 секунд.\nВы прыгаете на 10 % быстрее в течение 12 секунд.\nЗатем Spine Chill восстанавливается в течение 40/35/30 секунд.","shortDescriptionRu":"Неестественное покалывание предупреждает вас о надвигающейся гибели. Всякий раз, когда Убийца находится в пределах 40 метров от вашего местоположения и смотрит на вас, активируется Spine Chill: Вы уведомлены. Вы не можете кричать в течение 12 секунд.","upcomingPatch":true},"assets/perks/iconPerks_SprintBurst.png":{"englishName":"Sprint Burst","owner":"Meg Thomas","role":"survivor","descriptionEn":"Starting to run triggers Sprint Burst:\nGrants a +50 % Haste\nStatus Effect for 2 seconds.\nSprint Burst cannot be used while Exhausted.\nSprint Burst causes the Exhausted\nStatus Effect for 60/50/40 seconds.","descriptionRu":"Начало бега запускает Sprint Burst:\nДает +50 % скорости.\nСтатусный эффект на 2 секунды.\nSprint Burst нельзя использовать, пока вы измотаны.\nSprint Burst вызывает усталость\nСтатусный эффект на 60/50/40 секунд.","shortDescriptionRu":"Начало бега запускает Sprint Burst: Дает +50% скорости. Статусный эффект на 2 секунды. Sprint Burst нельзя использовать, пока вы измотаны.","upcomingPatch":false},"assets/perks/iconPerks_StakeOut.png":{"englishName":"Stake Out","owner":"David Tapp","role":"survivor","descriptionEn":"Staying in the Terror Radius\nand within 24 metres of the Killer without being chased grants +1 Token every 15 seconds, up to a maximum of 2/3/4 Tokens.\nWhile performing a skilful interaction that can trigger Skill Checks\n, you benefit from the following effects:\nReplaces regular Skill Checks with special Skill Checks.\nThese Skill Checks grant +4 % more progress on success and lose -4 % more progress on miss.\nSucceeding or missing a special Skill Check consumes -1 Token.","descriptionRu":"Пребывание в радиусе террора\nи в пределах 24 метров от Убийцы без преследования дает +1 жетон каждые 15 секунд, максимум до 2/3/4 жетонов.\nПри умелом взаимодействии, которое может вызвать проверку навыков.\n, вы получаете следующие эффекты:\nЗаменяет обычные проверки навыков специальными проверками навыков.\nЭти проверки навыков дают +4 % больше прогресса в случае успеха и теряют -4 % больше прогресса в случае промаха.\nУспешное прохождение или пропуск специальной проверки навыков требует -1 жетона.","shortDescriptionRu":"Пребывание в радиусе террора и в пределах 24 метров от Убийцы без преследования дает +1 жетон каждые 15 секунд, максимум до 4 жетонов. При умелом взаимодействии, которое может вызвать проверку навыков., вы получаете следующие эффекты: Заменяет обычные проверки навыков специальными проверками навыков.","upcomingPatch":true},"assets/perks/iconPerks_StillSight.png":{"englishName":"Still Sight","owner":"Troupe","role":"survivor","descriptionEn":"After standing still for 4/3/2 seconds, Still Sight activates:\nThe following Auras are revealed to you within 24 meters:\nKiller\nChests\nGenerators\nStill Sight deactivates once you start moving again.","descriptionRu":"После простоя на месте в течение 4/3/2 секунд активируется Still Sight:\nВ радиусе 24 метров вам открываются следующие ауры:\nУбийца\nСундуки\nГенераторы\nStill Sight деактивируется, как только вы снова начинаете двигаться.","shortDescriptionRu":"После простоя на месте в течение 2 секунд активируется Still Sight: В радиусе 24 метров вам открываются следующие ауры: Убийца Сундуки Генераторы Still Sight деактивируется, как только вы снова начинаете двигаться.","upcomingPatch":false},"assets/perks/iconPerks_Streetwise.png":{"englishName":"Streetwise","owner":"Nea Karlsson","role":"survivor","descriptionEn":"Any Items\nwith Charges you retrieve from Chests\nbenefit from the following primary effect:\nIncreases their Charges permanently by 60/70/80 %.\nWhenever your currently equipped Item is depleted for the first time, Streetwise triggers its secondary effect:\nThe Aura\nof the Killer is revealed to you for 8 seconds.","descriptionRu":"Любые предметы\nс зарядами, которые вы получаете из сундуков\nполучить выгоду от следующего основного эффекта:\nПостоянно увеличивает их заряды на 60/70/80 %.\nКаждый раз, когда ваш текущий предмет в первый раз исчерпывается, Streetwise активирует свой вторичный эффект:\nАура\nУбийцы открываются вам на 8 секунд.","shortDescriptionRu":"Любые предметы с зарядами, которые вы получаете из сундуков получить выгоду от следующего основного эффекта: Постоянно увеличивает их заряды на 80%. Каждый раз, когда ваш текущий предмет в первый раз исчерпывается, Streetwise активирует свой вторичный эффект: Аура Убийцы открываются вам на 8 секунд.","upcomingPatch":false},"assets/perks/iconPerks_TeamworkCollectiveStealth.png":{"englishName":"Teamwork: Collective Stealth","owner":"Renato Lyra","role":"survivor","descriptionEn":"Whenever another Survivor finishes healing you, Teamwork: Collective Stealth activates, and both you and the Survivor who healed you benefit from the following effect:\nSuppresses your Scratch Marks\nfor as long as you stay within 8/12/16 metres of one another.\nThis effect lingers for 4 seconds once out of range and resumes upon re-entering it before that timer elapses.\nSurvivors can only be affected by one instance of Teamwork: Collective Stealth at a time.","descriptionRu":"Каждый раз, когда другой Выживший заканчивает лечить вас, активируется «Командная работа: Коллективная скрытность», и вы и выживший, который вас исцелил, получаете следующий эффект:\nПодавляет царапины\nдо тех пор, пока вы находитесь на расстоянии 8/12/16 метров друг от друга.\nЭтот эффект сохраняется в течение 4 секунд после выхода за пределы диапазона и возобновляется при повторном входе в него до истечения этого таймера.\nНа выживших одновременно может воздействовать только один экземпляр «Командная работа: коллективная скрытность».","shortDescriptionRu":"Каждый раз, когда другой Выживший заканчивает лечить вас, активируется «Командная работа: Коллективная скрытность», и вы и выживший, который вас исцелил, получаете следующий эффект: Подавляет царапины до тех пор, пока вы находитесь на расстоянии 16 метров друг от друга.","upcomingPatch":false},"assets/perks/iconPerks_TeamworkPowerOfTwo.png":{"englishName":"Teamwork: Power of Two","owner":"Thalita Lyra","role":"survivor","descriptionEn":"Whenever you finish healing another Survivor, Teamwork: Power of Two activates, and both you and the healed Survivor benefit from the following effect:\nGrants a +5 % Haste\nStatus Effect for as long as you stay within 8/12/16 metres of one another.\nThis effect lingers for 4 seconds once out of range and resumes upon re-entering it before that timer elapses.\nSurvivors can only be affected by one instance of Teamwork: Power of Two at a time.","descriptionRu":"Каждый раз, когда вы завершаете лечение другого Выжившего, активируется «Командная работа: Сила двух», и вы и исцеленный Выживший получаете следующий эффект:\nДает +5 % скорости.\nСтатусный эффект действует до тех пор, пока вы находитесь в пределах 8/12/16 метров друг от друга.\nЭтот эффект сохраняется в течение 4 секунд после выхода за пределы диапазона и возобновляется при повторном входе в него до истечения этого таймера.\nНа выживших одновременно может воздействовать только один экземпляр «Командная работа: сила двух».","shortDescriptionRu":"Каждый раз, когда вы завершаете лечение другого Выжившего, активируется «Командная работа: Сила двух», и вы и исцеленный Выживший получаете следующий эффект: Дает +5% скорости. Статусный эффект действует до тех пор, пока вы находитесь в пределах 16 метров друг от друга.","upcomingPatch":false},"assets/perks/iconPerks_Technician.png":{"englishName":"Technician","owner":"Feng Min","role":"survivor","descriptionEn":"While repairing a Generator\n, the following effects apply:\nReduces the audible range of all noises related to the Repair interaction by -16 metres.\nIncreases the Progression penalty incurred when failing a Skill Check\nby 4/3/2 %.\nSuppresses the explosion of the Generator and the Loud Noise Notification usually triggered by that.","descriptionRu":"Во время ремонта генератора\n, применяются следующие эффекты:\nУменьшает диапазон слышимости всех шумов, связанных с ремонтом, на -16 метров.\nУвеличивает штраф за прогресс, налагаемый при провале проверки навыков.\nна 4/3/2 %.\nПодавляет взрыв генератора и обычно вызванное этим оповещение о громком шуме.","shortDescriptionRu":"Во время ремонта генератора, применяются следующие эффекты: Уменьшает диапазон слышимости всех шумов, связанных с ремонтом, на -16 метров. Увеличивает штраф за прогресс, налагаемый при провале проверки навыков. на 2%.","upcomingPatch":false},"assets/perks/iconPerks_Tenacity.png":{"englishName":"Tenacity","owner":"David Tapp","role":"survivor","descriptionEn":"Your ferocious tenacity in dire situations allows you to benefit from the following effects while in the Dying State\n:\nGrants the ability to recover while crawling.\nGrants a 30/40/50 % Haste\nStatus Effect.\nReduces the volume of Grunts of Pain by -75 %.\nBlocks your Aura\nfrom being read.","descriptionRu":"Ваше свирепое упорство в тяжелых ситуациях позволяет вам воспользоваться следующими эффектами, находясь в состоянии умирания.\n:\nПредоставляет возможность восстанавливаться во время ползания.\nДает 30/40/50% скорости.\nЭффект статуса.\nУменьшает громкость «Ворчания боли» на -75 %.\nБлокирует вашу ауру\nот прочтения.","shortDescriptionRu":"Ваше свирепое упорство в тяжелых ситуациях позволяет вам воспользоваться следующими эффектами, находясь в состоянии умирания.: Предоставляет возможность восстанавливаться во время ползания. Дает 50% скорости. Эффект статуса.","upcomingPatch":false},"assets/perks/iconPerks_ThisIsNotHappening.png":{"englishName":"This Is Not Happening","owner":"Общий","role":"survivor","descriptionEn":"While repairing or healing, This Is Not Happening activates:\nIncreases the Success zone for a Great Skill Check by +30 %.\nIncreases the Success zone for a Good Skill Check by 150/175/200 %.","descriptionRu":"Во время ремонта или исцеления активируется эффект «Этого не происходит»:\nУвеличивает зону успеха при проверке великих навыков на +30 %.\nУвеличивает зону успеха при хорошей проверке навыков на 150/175/200 %.","shortDescriptionRu":"Во время ремонта или исцеления активируется эффект «Этого не происходит»: Увеличивает зону успеха при проверке великих навыков на 30%. Увеличивает зону успеха при хорошей проверке навыков на 200%.","upcomingPatch":true},"assets/perks/IconPerks_troubleshooter.png":{"englishName":"Troubleshooter","owner":"Gabriel Soma","role":"survivor","descriptionEn":"When you are chased by the Killer, Troubleshooter activates:\nThe Aura\nof the Generator\nwith the most progress is revealed to you.\nThe Aura of the Killer is revealed to you for 4/5/6 seconds after dropping a Pallet\n.\nThese effects linger for 6/8/10 seconds after ending the Chase, after which Troubleshooter deactivates.","descriptionRu":"Когда вас преследует Убийца, активируется Устранение неполадок:\nАура\nГенератора\nс наибольшим прогрессом откроется вам.\nАура Убийцы открывается вам на 4/5/6 секунд после падения поддона.\n.\nЭти эффекты сохраняются в течение 6/8/10 секунд после окончания погони, после чего средство устранения неполадок отключается.","shortDescriptionRu":"Когда вас преследует Убийца, активируется Устранение неполадок: Аура Генератора с наибольшим прогрессом откроется вам. Аура Убийцы открывается вам на 6 секунд после падения поддона.. Эти эффекты сохраняются в течение 10 секунд после окончания погони, после чего средство устранения неполадок отключается.","upcomingPatch":false},"assets/perks/iconPerks_Unbreakable.png":{"englishName":"Unbreakable","owner":"Bill Overbeck","role":"survivor","descriptionEn":"Whenever you are put in the Dying State\nby the Killer, Unbreakable activates:\nIncreases your Recovery speed by 25/30/35 %.\nUnlocks the Self-Recovery ability, allowing you to fully recover from the Dying State.\nThis ability can only be used once per Trial.","descriptionRu":"Всякий раз, когда вас помещают в состояние умирания\nУбийцей активируется Неуязвимый:\nУвеличивает скорость восстановления на 25/30/35%.\nОткрывает способность самовосстановления, позволяющую полностью выйти из состояния умирания.\nЭту способность можно использовать только один раз за испытание.","shortDescriptionRu":"Всякий раз, когда вас помещают в состояние умирания Убийцей активируется Неуязвимый: Увеличивает скорость восстановления на 35%. Открывает способность самовосстановления, позволяющую полностью выйти из состояния умирания. Эту способность можно использовать только один раз за испытание.","upcomingPatch":false},"assets/perks/iconPerks_UpTheAnte.png":{"englishName":"Up the Ante","owner":"Ace Visconti","role":"survivor","descriptionEn":"Your confidence strengthens the feeling of hope for those around you.\"\nUnlocks the ability to attempt Self-Unhooks during the first Hook Stage for all Survivors.\nFor every Survivor still in the Trial, Up the Ante is granted +1 Token:\nIncreases the Luck\nat succeeding Self-Unhook attempts for all Survivors by a stack-able 1/2/3 % per Token, up to a maximum of 3/6/9 %.","descriptionRu":"Ваша уверенность усиливает чувство надежды у окружающих».\nОткрывает возможность самостоятельно отцепиться на первом этапе для всех выживших.\nЗа каждого Выжившего, все еще находящегося в Испытании, Up the Ante получает +1 жетон:\nУвеличивает удачу\nпри успешных попытках самоотцепления для всех Выживших суммируется 1/2/3 % за каждый жетон, вплоть до максимума 3/6/9 %.","shortDescriptionRu":"Ваша уверенность усиливает чувство надежды у окружающих». Открывает возможность самостоятельно отцепиться на первом этапе для всех выживших. За каждого Выжившего, все еще находящегося в Испытании, Up the Ante получает +1 жетон: Увеличивает удачу при успешных попытках самоотцепления для всех Выживших суммируется 3% за каждый жетон, вплоть до максимума 9%.","upcomingPatch":false},"assets/perks/iconPerks_UrbanEvasion.png":{"englishName":"Urban Evasion","owner":"Nea Karlsson","role":"survivor","descriptionEn":"You benefit from the following permanent effect:\nIncreases your Movement speed while crouched by 90/95/100 %.","descriptionRu":"Вы получаете следующий постоянный эффект:\nУвеличивает скорость передвижения в положении приседа на 90/95/100%.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Увеличивает скорость передвижения в положении приседа на 100%.","upcomingPatch":false},"assets/perks/iconPerks_Vigil.png":{"englishName":"Vigil","owner":"Quentin Smith","role":"survivor","descriptionEn":"You recover 20/25/30 % faster from the following:\nThe Exhausted\nStatus Effect.\nVigil extends its effect to all Survivors within 16 metres of your location and lingers for 15 seconds after leaving its Area of Effect.\nSurvivors can only be affected by one instance of Vigil at a time.","descriptionRu":"Вы восстанавливаетесь на 20/25/30 % быстрее благодаря следующему:\nИзмученный\nЭффект статуса.\nЭффект «Бдения» распространяется на всех выживших в радиусе 16 метров от вашего местоположения и сохраняется на 15 секунд после выхода из области действия.\nНа выживших одновременно может воздействовать только один экземпляр Vigil.","shortDescriptionRu":"Вы восстанавливаетесь на 30% быстрее благодаря следующему: Измученный Эффект статуса. Эффект «Бдения» распространяется на всех выживших в радиусе 16 метров от вашего местоположения и сохраняется на 15 секунд после выхода из области действия. На выживших одновременно может воздействовать только один экземпляр Vigil.","upcomingPatch":false},"assets/perks/iconPerks_Visionary.png":{"englishName":"Visionary","owner":"Felix Richter","role":"survivor","descriptionEn":"You benefit from the following permanent effect:\nThe Auras\nof Generators\nare revealed to you within 32 metres.\nVisionary is temporarily deactivated for 20/18/16 seconds whenever a Generator is completed.","descriptionRu":"Вы получаете следующий постоянный эффект:\nАуры\nгенераторов\nоткрываются вам в радиусе 32 метров.\nVisionary временно деактивируется на 20/18/16 секунд каждый раз, когда Генератор завершен.","shortDescriptionRu":"Вы получаете следующий постоянный эффект: Ауры генераторов открываются вам в радиусе 32 метров. Visionary временно деактивируется на 16 секунд каждый раз, когда Генератор завершен.","upcomingPatch":false},"assets/perks/iconPerks_VittoriosGambit.png":{"englishName":"Quick Gambit","owner":"Vittorio Toscano","role":"survivor","descriptionEn":"While being chased by the Killer, the following effects apply:\nThe Auras\nof other Survivors are revealed to you.\nIncreases the Repair speed of other Survivors by 3/4/5 %.\nQuick Gambit has a cool-down of 40 seconds upon losing a Health State\n.","descriptionRu":"Когда вас преследует Убийца, применяются следующие эффекты:\nАуры\nвам откроются сведения о других Выживших.\nУвеличивает скорость ремонта других Выживших на 3/4/5 %.\nБыстрый Гамбит имеет время восстановления 40 секунд после потери состояния здоровья.\n.","shortDescriptionRu":"Когда вас преследует Убийца, применяются следующие эффекты: Ауры вам откроются сведения о других Выживших. Увеличивает скорость ремонта других Выживших на 5%. Быстрый Гамбит имеет время восстановления 40 секунд после потери состояния здоровья..","upcomingPatch":false},"assets/perks/iconPerks_WakeUp.png":{"englishName":"Wake Up!","owner":"Quentin Smith","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability.\nOnce all Generators\nare completed, Wake Up! activates:\nThe Auras\nof the Exit Gate Switches\nare revealed to you permanently while within 128 metres.\nYour Aura is revealed to all other Survivors within 128 metres while you are opening an Exit Gate.\nIncreases your Gate-Opening speed by 8/9/10 % and by an additional #effect for each Survivor still alive in the Trial up to a maximum of 68/69/70 %.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nКогда все генераторы\nзавершены, просыпайтесь! активирует:\nАуры\nпереключателей выходных ворот\nоткрываются вам постоянно, пока вы находитесь в пределах 128 метров.\nВаша аура видна всем остальным Выжившим в радиусе 128 метров, пока вы открываете Выходные ворота.\nУвеличивает скорость открытия врат на 8/9/10 % и на дополнительный #эффект за каждого Выжившего, оставшегося в живых в Испытании, максимум до 68/69/70 %.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Когда все генераторы завершены, просыпайтесь! активирует: Ауры переключателей выходных ворот открываются вам постоянно, пока вы находитесь в пределах 128 метров.","upcomingPatch":false},"assets/perks/iconPerks_WeaveAttunement.png":{"englishName":"Weave Attunement","owner":"Lich","role":"killer","descriptionEn":"Whenever an Item\nis depleted for the first time, it is automatically dropped:\nThe Auras\nof dropped Survivor Items are revealed to you, as well as the Auras of any Survivors within 12 metres of them.\nAffected Survivors see the Aura of that Item as well.\nCauses Survivors picking up a Survivor Item to suffer from the Oblivious\nStatus Effect for 20/25/30 seconds.","descriptionRu":"Всякий раз, когда предмет\nисчерпан в первый раз, он автоматически удаляется:\nАуры\nВам будут показаны выпавшие предметы Выжившего, а также ауры всех Выживших в радиусе 12 метров от них.\nПострадавшие выжившие также видят ауру этого предмета.\nЗаставляет выживших, подбирающих предмет выжившего, страдать от забывчивости.\nСтатусный эффект на 20/25/30 секунд.","shortDescriptionRu":"Всякий раз, когда предмет исчерпан в первый раз, он автоматически удаляется: Ауры Вам будут показаны выпавшие предметы Выжившего, а также ауры всех Выживших в радиусе 12 метров от них. Пострадавшие выжившие также видят ауру этого предмета. Заставляет выживших, подбирающих предмет выжившего, страдать от забывчивости.","upcomingPatch":false},"assets/perks/iconPerks_WellMakeIt.png":{"englishName":"We'll Make It","owner":"Общий","role":"survivor","descriptionEn":"After unhooking another Survivor, We'll Make It activates for 70/80/90 seconds:\nIncreases your Altruistic Healing speed by +100 %.","descriptionRu":"После отцепления другого Выжившего эффект «Мы сделаем это» активируется на 70/80/90 секунд:\nУвеличивает скорость альтруистического исцеления на +100 %.","shortDescriptionRu":"После отцепления другого Выжившего эффект «Мы сделаем это» активируется на 90 секунд: Увеличивает скорость альтруистического исцеления на 100%.","upcomingPatch":true},"assets/perks/iconPerks_WereGonnaLiveForever.png":{"englishName":"We're Gonna Live Forever","owner":"David King","role":"survivor","descriptionEn":"Your few friends deserve the best protection.\nYou benefit from the following effect when healing a dying Survivor:\nIncreases your Healing speed by +100 %.\nAny dying Survivor you heal back to the Injured State benefits from the following effect:\nGrants the Endurance\nStatus Effect for 6/8/10 seconds.\nThis effect can only be triggered once every 30 seconds.","descriptionRu":"Ваши немногие друзья заслуживают лучшей защиты.\nПри исцелении умирающего Выжившего вы получаете следующий эффект:\nУвеличивает скорость лечения на +100 %.\nЛюбой умирающий Выживший, которого вы исцеляете до раненого состояния, получает следующий эффект:\nДает выносливость\nСтатусный эффект на 6/8/10 секунд.\nЭтот эффект может срабатывать только один раз каждые 30 секунд.","shortDescriptionRu":"Ваши немногие друзья заслуживают лучшей защиты. При исцелении умирающего Выжившего вы получаете следующий эффект: Увеличивает скорость лечения на 100%. Любой умирающий Выживший, которого вы исцеляете до раненого состояния, получает следующий эффект: Дает выносливость Статусный эффект на 10 секунд.","upcomingPatch":false},"assets/perks/iconPerks_WindowsOfOpportunity.png":{"englishName":"Windows of Opportunity","owner":"Kate Denson","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability.\nThe Auras\nof Windows\nare revealed to you within 40/35/30 seconds..\nYou vault Windows +10 % faster.\nWindows of Opportunity goes on a 40/35/30 seconds cool-down when you vault a Window.\nTake aim, pull the trigger, hit the bulls eye for fame,\nKnow the value of faith, an' family, and don't you complain,\nOpen wide, your windows of opportunity\" — Kate Denson's \"Windows of Opportunity\"","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры.\nАуры\nокон\nраскрываются вам в течение 40/35/30 секунд..\nВы получаете Windows на 10 % быстрее.\nОкна возможностей перезаряжаются 40/35/30 секунд, когда вы прыгаете через Окно.\nПрицельтесь, нажмите на курок, попадите в яблочко ради славы,\nЗнай цену вере и семье и не жалуйся,\nОткройте широко свои окна возможностей» — Кейт Денсон «Окна возможностей».","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры. Ауры окон раскрываются вам в течение 30 секунд.. Вы получаете Windows на 10% быстрее.","upcomingPatch":false},"assets/perks/iconPerks_Wiretap.png":{"englishName":"Wiretap","owner":"Ada Wong","role":"survivor","descriptionEn":"After repairing a Generator\nfor the equivalent of 40 % of Progression, Wiretap activates.\nWhile active, press the Active Ability button while standing next to a Generator to install a listening device to it with a countdown of 100/110/120 seconds:\nReveals the Aura of the Killer coming within 14 metres of the Bugged Generator to all Survivors.\nThe listening device is deactivated after its countdown has elapsed or the Bugged Generator is damaged.\nThe Auras\nof Bugged Generators are revealed to all Survivors in yellow.","descriptionRu":"После ремонта генератора\nдля эквивалента 40 % прогресса активируется прослушивание.\nВ активном режиме нажмите кнопку «Активная способность», стоя рядом с генератором, чтобы установить к нему подслушивающее устройство с обратным отсчетом 100/110/120 секунд:\nПоказывает всем выжившим ауру убийцы, приближающуюся в радиусе 14 метров от прослушиваемого генератора.\nПодслушивающее устройство отключается после истечения его обратного отсчета или повреждения генератора ошибок.\nАуры\nГенераторов с ошибками показаны всем Выжившим желтым цветом.","shortDescriptionRu":"После ремонта генератора для эквивалента 40% прогресса активируется прослушивание. В активном режиме нажмите кнопку «Активная способность», стоя рядом с генератором, чтобы установить к нему подслушивающее устройство с обратным отсчетом 120 секунд: Показывает всем выжившим ауру убийцы, приближающуюся в радиусе 14 метров от прослушиваемого генератора.","upcomingPatch":false},"assets/perks/iconsPerks_ChampionOfLight.png":{"englishName":"Champion of Light","owner":"Alan Wake","role":"survivor","descriptionEn":"While shining a Flashlight\n, Champion of Light triggers its primary effect:\nGrants a +50 % Haste\nStatus Effect.\nAfter blinding the Killer by any means, Champion of Light triggers its secondary effect:\nCauses the Killer to suffer from a -20 % Hindered\nStatus Effect for 6 seconds.\nThis effect does not stack.\nChampion of Light applies a cool-down of 60/50/40 seconds after blinding the Killer.","descriptionRu":"Пока светит фонариком\n, Чемпион Света активирует свой основной эффект:\nДает +50 % скорости.\nЭффект статуса.\nПосле ослепления Убийцы любым способом Чемпион Света активирует свой вторичный эффект:\nЗаставляет Убийцу страдать от -20 % затруднений.\nСтатусный эффект на 6 секунд.\nЭтот эффект не суммируется.\nЧемпион Света применяет время восстановления 60/50/40 секунд после ослепления Убийцы.","shortDescriptionRu":"Пока светит фонариком, Чемпион Света активирует свой основной эффект: Дает +50% скорости. Эффект статуса. После ослепления Убийцы любым способом Чемпион Света активирует свой вторичный эффект: Заставляет Убийцу страдать от -20% затруднений.","upcomingPatch":false},"assets/perks/iconsPerks_Deadline.png":{"englishName":"Deadline","owner":"Alan Wake","role":"survivor","descriptionEn":"Whenever you are in the Injured State\n, Deadline activates:\nIncreases the Odds of triggering Skill Checks\nby 6/8/10 % while repairing or healing.\nCauses Skill Checks to appear in random places.\nReduces the penalty for missed Skill Checks by -50 %.","descriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии\n, Дедлайн активируется:\nУвеличивает вероятность запуска проверок навыков.\nна 6/8/10 % во время ремонта или лечения.\nЗаставляет проверки навыков появляться в случайных местах.\nСнижает штраф за пропущенные проверки навыков на -50 %.","shortDescriptionRu":"Всякий раз, когда вы находитесь в поврежденном состоянии, Дедлайн активируется: Увеличивает вероятность запуска проверок навыков. на 10% во время ремонта или лечения. Заставляет проверки навыков появляться в случайных местах.","upcomingPatch":false},"assets/perks/iconsPerks_Illumination.png":{"englishName":"Boon: Illumination","owner":"Alan Wake","role":"survivor","descriptionEn":"Press and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nThe Auras\nof all Chests\nand Generators\nare highlighted to you in blue.\nIncreases your Blessing action speed by 150/175/200 % while you have a lit Boon Totem.\nSurvivors can only be affected by one instance of Boon: Illumination at a time.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nАуры\nиз всех сундуков\nи генераторы\nвыделены для вас синим цветом.\nУвеличивает скорость действия Благословения на 150/175/200 %, пока у вас горит Тотем Благословения.\nНа выживших одновременно может воздействовать только один экземпляр Дара: Освещение.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Ауры из всех сундуков и генераторы выделены для вас синим цветом. Увеличивает скорость действия Благословения на 200%, пока у вас горит Тотем Благословения.","upcomingPatch":true},"assets/perks/iconsPerks_InvocationWeavingSpiders.png":{"englishName":"Invocation: Weaving Spiders","owner":"Sable Ward","role":"survivor","descriptionEn":"When in the Basement\nnear the circle, press the Active Ability button to begin the Invocation, which takes 60 seconds to complete.\nDuring an Invocation, your Aura\nis revealed to all other Survivors and they can join in, accelerating the process by +100 %, if they too have an Invocation Perk equipped, or by +50 %, if they have not.\nOnce the Invocation is completed, the following effects apply:\nPermanently reduces the Repair Charges requirement of all Generators\nin the Trial by 8/9/10 Charges.\nYou automatically enter the Injured State\nfrom any previous Health State, and suffer from the Broken\nStatus Effect for the remainder of the Trial.\nCompleting this Invocation disables all other instances of Invocation: Weaving Spiders for the remainder of the Trial.","descriptionRu":"Когда в подвале\nрядом с кругом нажмите кнопку «Активная способность», чтобы начать призыв, который занимает 60 секунд.\nВо время призыва ваша аура\nраскрывается всем остальным Выжившим, и они могут присоединиться, ускоряя процесс на +100 %, если у них тоже есть навык призыва, или на +50 %, если у них его нет.\nПосле завершения Призыва применяются следующие эффекты:\nПостоянно снижает требования к затратам на ремонт всех генераторов.\nв суде по обвинениям 8/9/10.\nВы автоматически входите в состояние травмы\nот любого предыдущего состояния здоровья и страдают от Сломанного\nЭффект статуса на оставшуюся часть Испытания.\nЗавершение этого Призыва отключает все остальные экземпляры Призыва: Плетение Пауков на оставшуюся часть Испытания.","shortDescriptionRu":"Когда в подвале рядом с кругом нажмите кнопку «Активная способность», чтобы начать призыв, который занимает 60 секунд. Во время призыва ваша аура раскрывается всем остальным Выжившим, и они могут присоединиться, ускоряя процесс на 100%, если у них тоже есть навык призыва, или на 50%, если у них его нет.","upcomingPatch":false},"assets/perks/iconsPerks_StrengthInShadows.png":{"englishName":"Strength in Shadows","owner":"Sable Ward","role":"survivor","descriptionEn":"Whenever you are inside the Basement\n, Strength in Shadows activates:\nUnlocks the Strength in Shadows ability, allowing you to self-heal without needing a Med-Kit\nat 70 % of the normal Healing speed.\nUpon finishing a heal in the Basement, the Aura\nof the Killer is revealed to you for 6/8/10 seconds.","descriptionRu":"Всякий раз, когда вы находитесь в подвале\n, Сила в тенях активируется:\nОткрывает способность «Сила в тенях», позволяющую вам самоисцеляться без аптечки.\nсо скоростью 70 % от нормальной скорости исцеления.\nПосле завершения лечения в Подвале Аура\nУбийцы открываются вам на 6/8/10 секунд.","shortDescriptionRu":"Всякий раз, когда вы находитесь в подвале, Сила в тенях активируется: Открывает способность «Сила в тенях», позволяющую вам самоисцеляться без аптечки. со скоростью 70% от нормальной скорости исцеления. После завершения лечения в Подвале Аура Убийцы открываются вам на 10 секунд.","upcomingPatch":false},"assets/perks/iconsPerks_Wicked.png":{"englishName":"Wicked","owner":"Sable Ward","role":"survivor","descriptionEn":"But you're not going down so easily.\"\nAfter you are unhooked by any means, Wicked triggers the following effect:\nThe Aura\nof the Killer is revealed to you for 16/18/20 seconds.\nWhile hooked inside the Basement\n, Wicked potentially triggers the following effect:\nFirst Hook Stage: 100 % to succeed an attempted Self-Unhook.\nSecond Hook Stage: Does not trigger the effect.\nLast Survivor Standing: Does not trigger the effect.","descriptionRu":"Но так легко ты не сдашься».\nПосле того, как вас каким-либо образом отцепят, Wicked активирует следующий эффект:\nАура\nУбийцы открываются вам на 16/18/20 секунд.\nПока на крючке в подвале\n, Wicked потенциально вызывает следующий эффект:\nПервый этап крюка: 100 % успешная попытка самоотцепления.\nВторой этап крюка: не вызывает эффекта.\nПоследний выживший: не вызывает эффекта.","shortDescriptionRu":"Но так легко ты не сдашься». После того, как вас каким-либо образом отцепят, Wicked активирует следующий эффект: Аура Убийцы открываются вам на 20 секунд. Пока на крючке в подвале, Wicked потенциально вызывает следующий эффект: Первый этап крюка: 100% успешная попытка самоотцепления.","upcomingPatch":false},"assets/perks/T_iconPerks_BoonExponential.png":{"englishName":"Boon: Exponential","owner":"Jonah Vasquez","role":"survivor","descriptionEn":"Press and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nIncreases the Recovery speed while in the Dying State\nby 90/95/100 %.\nUnlocks the Self-Recovery ability, allowing them to fully recover from the Dying State.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nУвеличивает скорость восстановления в состоянии умирания.\nна 90/95/100%.\nОткрывает способность самовосстановления, позволяющую полностью восстановиться после умирающего состояния.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Увеличивает скорость восстановления в состоянии умирания. на 100%.","upcomingPatch":false},"assets/perks/T_iconPerks_CorrectiveAction.png":{"englishName":"Corrective Action","owner":"Jonah Vasquez","role":"survivor","descriptionEn":"You start the Trial with 1/2/3 Token(s) and succeeding a Great Skill Check grants +1 Token, up to a maximum of 5 Tokens.\nWhile any other Survivor performs a skilful interaction that can trigger Skill Checks\n, they benefit from the following effects:\nConverts any Failed Skill Check into a Good Skill Check.\nThis consumes -1 Token.\nThe Aura\nof that Survivor is revealed to you for 6 seconds.\nCorrective Action does not apply to special Skill Checks.","descriptionRu":"Вы начинаете испытание с 1/2/3 жетонами, а успешная проверка великих навыков дает +1 жетон, максимум до 5 жетонов.\nВ то время как любой другой Выживший выполняет умелое взаимодействие, которое может вызвать проверку навыков\n, они получают следующие эффекты:\nПреобразует любую неудачную проверку навыка в хорошую проверку навыка.\nЭто потребляет -1 жетон.\nАура\nэтого Выжившего открывается вам на 6 секунд.\nКорректирующее действие не применяется к специальным проверкам навыков.","shortDescriptionRu":"Вы начинаете испытание с 3 жетонами, а успешная проверка великих навыков дает +1 жетон, максимум до 5 жетонов. В то время как любой другой Выживший выполняет умелое взаимодействие, которое может вызвать проверку навыков, они получают следующие эффекты: Преобразует любую неудачную проверку навыка в хорошую проверку навыка. Это потребляет -1 жетон.","upcomingPatch":false},"assets/perks/T_iconPerks_Overcome.png":{"englishName":"Overcome","owner":"Jonah Vasquez","role":"survivor","descriptionEn":"Whenever you enter the Injured State\nfrom full health, Overcome triggers its effect:\nExtends the duration of the On-hit Sprint boost by +2 seconds.\nOvercome cannot be used while Exhausted.\nOvercome causes the Exhausted\nStatus Effect for 60/50/40 seconds.","descriptionRu":"Всякий раз, когда вы входите в состояние травмы\nпри полном здоровье Преодоление срабатывает:\nУвеличивает продолжительность ускорения спринта при попадании на +2 секунды.\nПреодоление нельзя использовать, пока вы измотаны.\nПреодоление вызывает истощение\nСтатусный эффект на 60/50/40 секунд.","shortDescriptionRu":"Всякий раз, когда вы входите в состояние травмы при полном здоровье Преодоление срабатывает: Увеличивает продолжительность ускорения спринта при попадании на 2 секунды. Преодоление нельзя использовать, пока вы измотаны. Преодоление вызывает истощение Статусный эффект на 40 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_ApocalypticIngenuity.png":{"englishName":"Apocalyptic Ingenuity","owner":"Rick Grimes","role":"survivor","descriptionEn":"Unlocks potential in your Aura-reading ability:\nThe Auras\nof broken Pallets\nare revealed to you within 24/28/32 metres.\nAfter unlocking or rummaging through 1 Chest\n, Apocalyptic Ingenuity gains a special ability.\nWhile standing next to the location of a broken Pallet, press and hold the Active Ability button for 3 seconds to use it:\nRebuilds it as a Fragile Pallet.\nFragile Pallets instantly break when dropped.","descriptionRu":"Раскрывает потенциал вашей способности чтения ауры:\nАуры\nсломанных поддонов\nоткрываются вам в радиусе 24/28/32 метров.\nПосле открытия или рытья 1 сундука\n, Апокалиптическая изобретательность получает особую способность.\nСтоя рядом со сломанным поддоном, нажмите и удерживайте кнопку «Активная способность» в течение 3 секунд, чтобы использовать ее:\nВосстанавливает его как хрупкий поддон.\nХрупкие поддоны мгновенно ломаются при падении.","shortDescriptionRu":"Раскрывает потенциал вашей способности чтения ауры: Ауры сломанных поддонов открываются вам в радиусе 32 метров. После открытия или рытья 1 сундука, Апокалиптическая изобретательность получает особую способность. Стоя рядом со сломанным поддоном, нажмите и удерживайте кнопку «Активная способность» в течение 3 секунд, чтобы использовать ее: Восстанавливает его как хрупкий поддон.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_ComeAndGetMe.png":{"englishName":"Come and Get Me!","owner":"Rick Grimes","role":"survivor","descriptionEn":"After unhooking a Survivor, while crouched and stationary, press the Active Ability button to trigger the following effects:\nSuppresses the creation of Grunts of Pain, Pools of Blood\n, and Scratch Marks\nfor all injured or dying Survivors within 24 metres of your location for the next 10/12.5/15 seconds.\nCauses you to scream and reveal your Aura\nto the Killer for 5 seconds.","descriptionRu":"После отцепления Выжившего, когда он присел и стоит, нажмите кнопку «Активная способность», чтобы активировать следующие эффекты:\nПодавляет создание стонов боли и луж крови.\nи царапины\nдля всех раненых или умирающих Выживших в радиусе 24 метров от вашего местоположения в течение следующих 10/12,5/15 секунд.\nЗаставляет вас кричать и раскрывать свою ауру\nУбийце на 5 секунд.","shortDescriptionRu":"После отцепления Выжившего, когда он присел и стоит, нажмите кнопку «Активная способность», чтобы активировать следующие эффекты: Подавляет создание стонов боли и луж крови. и царапины для всех раненых или умирающих Выживших в радиусе 24 метров от вашего местоположения в течение следующих 15 секунд. Заставляет вас кричать и раскрывать свою ауру Убийце на 5 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_Conviction.png":{"englishName":"Conviction","owner":"Michonne Grimes","role":"survivor","descriptionEn":"After having completed a Healing action on another Survivor, whenever you are in the Dying State\n, Conviction activates.\nWhile active, press the Active Ability button after reaching at least 25 % Recovery progress to trigger the following effects:\nUnlocks the Self-Recovery ability, allowing you to fully recover from the Dying State.\nInflicts the Broken\nStatus Effect.\nCauses you to automatically re-enter the Dying State after 20/25/30 seconds.","descriptionRu":"После завершения действия исцеления другого Выжившего, когда вы находитесь в состоянии умирания.\n, Осуждение активируется.\nПока активна, нажмите кнопку «Активная способность» после достижения хотя бы 25 % прогресса восстановления, чтобы активировать следующие эффекты:\nОткрывает способность самовосстановления, позволяющую полностью выйти из состояния умирания.\nНаносит сломанный\nЭффект статуса.\nЗаставляет вас автоматически повторно войти в состояние умирания через 20/25/30 секунд.","shortDescriptionRu":"После завершения действия исцеления другого Выжившего, когда вы находитесь в состоянии умирания., Осуждение активируется. Пока активна, нажмите кнопку «Активная способность» после достижения хотя бы 25% прогресса восстановления, чтобы активировать следующие эффекты: Открывает способность самовосстановления, позволяющую полностью выйти из состояния умирания. Наносит сломанный Эффект статуса.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_GhostNotes.png":{"englishName":"Ghost Notes","owner":"Vee Boonyasak","role":"survivor","descriptionEn":"While suffering from the Exhausted\nStatus Effect, you benefit from the following effects:\nCauses your Scratch Marks\nto disappear +50 % faster.\nIncreases your Recovery rate from that Status Effect by 5/7.5/10 %.\nGhost Notes does not cause the Exhausted Status Effect.","descriptionRu":"Страдая от истощения\nЭффект статуса, вы получаете следующие эффекты:\nВызывает появление царапин\nисчезнуть на 50 % быстрее.\nУвеличивает скорость восстановления от этого эффекта статуса на 5/7,5/10 %.\nПризрачные заметки не вызывают эффекта «Исчерпан».","shortDescriptionRu":"Страдая от истощения Эффект статуса, вы получаете следующие эффекты: Вызывает появление царапин исчезнуть на 50% быстрее. Увеличивает скорость восстановления от этого эффекта статуса на 10%. Призрачные заметки не вызывают эффекта «Исчерпан».","upcomingPatch":false},"assets/perks/T_UI_iconPerks_LastStand.png":{"englishName":"Last Stand","owner":"Michonne Grimes","role":"survivor","descriptionEn":"After staying in the Terror Radius\nwithout being chased for 120/105/90 seconds, Last Stand activates.\nWhile active, perform a Rushed Vault action to trigger its effect:\nStuns the Killer for 3 seconds, if they are within 2.5 metres of that Vault location.\nLast Stand is disabled for the remainder of the Trial after use.","descriptionRu":"После пребывания в Радиусе Террора\nбез преследования в течение 120/105/90 секунд активируется Last Stand.\nПока активно, выполните действие «Срочное хранилище», чтобы активировать его эффект:\nОглушает Убийцу на 3 секунды, если он находится в пределах 2,5 метров от этого Убежища.\n«Последний бой» отключен на оставшуюся часть испытания после использования.","shortDescriptionRu":"После пребывания в Радиусе Террора без преследования в течение 90 секунд активируется Last Stand. Пока активно, выполните действие «Срочное хранилище», чтобы активировать его эффект: Оглушает Убийцу на 3 секунды, если он находится в пределах 2,5 метров от этого Убежища. «Последний бой» отключен на оставшуюся часть испытания после использования.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_OneTwoThreeFour.png":{"englishName":"One-Two-Three-Four!","owner":"Vee Boonyasak","role":"survivor","descriptionEn":"While standing and idle, press the Active Ability button to start a Performance:\nLasts for up to 15 seconds.\nEmpowers Survivors within 16 metres of your location.\nTriggers continuous Skill Checks\n.\nAfter successfully completing the Performance, empowered Survivors performing Healing or Repairing actions benefit from the following effect for 90 seconds:\nIncreases the chances of triggering Skill Checks by +20 %.\nOne-Two-Three-Four! has a cool-down of 110/100/90 seconds after cancelling or completing the Performance.","descriptionRu":"Стоя и бездействуя, нажмите кнопку «Активная способность», чтобы начать представление:\nДлится до 15 секунд.\nУсиливает выживших в радиусе 16 метров от вас.\nЗапускает постоянные проверки навыков\n.\nПосле успешного завершения Представления усиленные Выжившие, выполняющие действия Исцеления или Восстановления, получают следующий эффект на 90 секунд:\nУвеличивает вероятность запуска проверки навыков на +20 %.\nРаз-два-три-четыре! имеет время восстановления 110/100/90 секунд после отмены или завершения выступления.","shortDescriptionRu":"Стоя и бездействуя, нажмите кнопку «Активная способность», чтобы начать представление: Длится до 15 секунд. Усиливает выживших в радиусе 16 метров от вас. Запускает постоянные проверки навыков.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_RoadLife.png":{"englishName":"Road Life","owner":"Vee Boonyasak","role":"survivor","descriptionEn":"While injured and repairing a Generator\n, regular Skill Checks\nhave the following effects:\nGain +1 Token for Great Repair Skill Checks.\nGain 0 Tokens for Good Repair Skill Checks.\nLose -1 Token for Failed Repair Skill Checks.\nOnce you accumulate 6/5/4 Tokens, consume all Tokens to benefit from the following effect:\nUnlocks the ability to heal yourself\nIncreases your Self-Healing speed by +100 % until you stop healing and for 4 seconds after.","descriptionRu":"Во время ранения и ремонта генератора\n, регулярные проверки навыков\nимеют следующие эффекты:\nПолучите +1 жетон для проверок навыков отличного ремонта.\nПолучите 0 жетонов за хорошие проверки навыков ремонта.\nПотеряйте -1 жетон за неудачную проверку навыка ремонта.\nКак только вы накопите 6/5/4 жетона, израсходуйте все жетоны, чтобы получить следующий эффект:\nОткрывает способность исцелять себя\nУвеличивает скорость самоисцеления на +100 % до тех пор, пока вы не перестанете лечить, и в течение 4 секунд после этого.","shortDescriptionRu":"Во время ранения и ремонта генератора, регулярные проверки навыков имеют следующие эффекты: Получите +1 жетон для проверок навыков отличного ремонта. Получите 0 жетонов за хорошие проверки навыков ремонта. Потеряйте -1 жетон за неудачную проверку навыка ремонта.","upcomingPatch":true},"assets/perks/T_UI_iconPerks_TeamworkThrowDown.png":{"englishName":"Teamwork: Throw Down","owner":"Michonne Grimes","role":"survivor","descriptionEn":"Whenever you blind the Killer by any means or stun them using a Pallet\n, Teamwork: Throw Down triggers its effect:\nGrants the Endurance\nStatus Effect to all other injured Survivors within 24 metres of your location for 6/8/10 seconds.","descriptionRu":"Каждый раз, когда вы ослепляете Убийцу любым способом или оглушаете его с помощью поддона.\n, Командная работа: «Бросок вниз» срабатывает:\nДает выносливость\nСтатусный эффект для всех остальных раненых Выживших в радиусе 24 метров от вашего местоположения на 6/8/10 секунд.","shortDescriptionRu":"Каждый раз, когда вы ослепляете Убийцу любым способом или оглушаете его с помощью поддона., Командная работа: «Бросок вниз» срабатывает: Дает выносливость Статусный эффект для всех остальных раненых Выживших в радиусе 24 метров от вашего местоположения на 10 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconPerks_TeamworkToughenUp.png":{"englishName":"Teamwork: Toughen Up","owner":"Rick Grimes","role":"survivor","descriptionEn":"While injured, whenever another Survivor within 24 metres of your location blinds the Killer by any means or stuns them using a Pallet\n, Teamwork: Toughen Up triggers its effect:\nSuppresses your Grunts of Pain, and the creation of Pools of Blood\nand Scratch Marks\nfor 20/25/30 seconds.","descriptionRu":"Будучи раненым, каждый раз, когда другой Выживший в пределах 24 метров от вас ослепляет Убийцу любым способом или оглушает его с помощью поддона.\n, Работа в команде: «Закалка» срабатывает:\nПодавляет ваши стоны боли и образование луж крови.\nи царапины\nна 20/25/30 секунд.","shortDescriptionRu":"Будучи раненым, каждый раз, когда другой Выживший в пределах 24 метров от вас ослепляет Убийцу любым способом или оглушает его с помощью поддона., Работа в команде: «Закалка» срабатывает: Подавляет ваши стоны боли и образование луж крови. и царапины на 30 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_aPlaceForUs.png":{"englishName":"A Place For Us","owner":"Kwon Tae-young","role":"survivor","descriptionEn":"While healing an another Survivor, both you and the healed Survivor gain Elusive\nStatus Effect.\nWhen you finish healing the Obsession\n, both you and the Obsession gain Elusive\nStatus Effect for 20/25/30 seconds.\nReduces your chance of becoming the initial Obsession by reducing the default value by -100 %.\nThe Killer can only be obsessed with one Survivor at a time.","descriptionRu":"Исцеляя другого Выжившего, и вы, и исцеленный Выживший получаете Неуловимость.\nЭффект статуса.\nКогда вы закончите исцелять одержимость\n, и вы, и Одержимость получаете Неуловимость.\nСтатусный эффект на 20/25/30 секунд.\nУменьшает ваш шанс стать первоначальной одержимостью за счет уменьшения значения по умолчанию на -100 %.\nУбийца может быть одержим только одним Выжившим одновременно.","shortDescriptionRu":"Исцеляя другого Выжившего, и вы, и исцеленный Выживший получаете Неуловимость. Эффект статуса. Когда вы закончите исцелять одержимость, и вы, и Одержимость получаете Неуловимость.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_BadaBadaBoom.png":{"englishName":"Bada Bada Boom","owner":"Dustin Henderson","role":"survivor","descriptionEn":"After completing 20 % worth of Generator\nrepairs, Bada Bada Boom activates:\nWhile active, press Active Ability button next to a window to install a Trap, which stays active for up to 40/50/60 seconds.\nThe Trap tiggers when the Killer\nperforms a vault through the window, causing the Killer to suffer from a -50 % Hindered\nStatus Effect for 6 seconds.\nBada Bada Boom deactives after triggering successfully or once the timer runs out.\nThe Auras\nof Trapped Windows are revealed to all Survivors in yellow.","descriptionRu":"После завершения Генератора на 20 %.\nремонт, Bada Bada Boom активирует:\nПока она активна, нажмите кнопку «Активная способность» рядом с окном, чтобы установить ловушку, которая остается активной до 40/50/60 секунд.\nЛовушка срабатывает, когда убийца\nвыполняет прыжок через окно, в результате чего Убийца получает -50 % замедление\nСтатусный эффект на 6 секунд.\nBada Bada Boom деактивируется после успешного срабатывания или по истечении таймера.\nАуры\nЗапертые окна показаны всем Выжившим желтым цветом.","shortDescriptionRu":"После завершения Генератора на 20%. ремонт, Bada Bada Boom активирует: Пока она активна, нажмите кнопку «Активная способность» рядом с окном, чтобы установить ловушку, которая остается активной до 60 секунд. Ловушка срабатывает, когда убийца выполняет прыжок через окно, в результате чего Убийца получает -50% замедление Статусный эффект на 6 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_BoonSteadfast.png":{"englishName":"Boon: Steadfast","owner":"Aurora Stardotter","role":"survivor","descriptionEn":"Press and hold the Active Ability button on a Dull or Hex Totem to bless it and create a Boon Totem\n.\nAll Survivors within 24 metres hear soft chimes ringing out and benefit from its Boon Effects:\nGenerators\nwithin this Boon's range:\nRegress -50 % slower.\nSurvivors repair them +8/9/10 % faster.\nSurvivors see their auras while inside the Boon's range.\nSurvivors can only be affected by one instance of Boon: Steadfast at a time.\nOnly one Totem can be blessed by your Boon Perks at a time and all of their effects are active on the same Boon Totem.","descriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.\n.\nВсе выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты:\nГенераторы\nв радиусе действия этого Дара:\nРегресс на 50 % медленнее.\nВыжившие ремонтируют их на 8/9/10 % быстрее.\nВыжившие видят свои ауры, находясь в радиусе действия Дара.\nНа выживших одновременно может воздействовать только один экземпляр Дара: Стойкость.\nТолько один Тотем может быть благословлен вашими Благотворительными перками одновременно, и все их эффекты активны на одном Благотворном Тотеме.","shortDescriptionRu":"Нажмите и удерживайте кнопку активной способности на тупом или шестигранном тотеме, чтобы благословить его и создать тотем благ.. Все выжившие в радиусе 24 метров слышат тихий звон колокольчиков и получают бонусные эффекты: Генераторы в радиусе действия этого Дара: Регресс на 50% медленнее. Выжившие ремонтируют их на 10% быстрее.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_ChangeOfPlan.png":{"englishName":"Change of Plan","owner":"Dustin Henderson","role":"survivor","descriptionEn":"You start the Trial with 2 Tokens.\nWhile hiding inside a Locker\nand holding a non-event Toolbox\n, press Active Ability button to spend 1 Token and transform your Toolbox into a Med-Kit\nof the same rarity with a random add-on of the same rarity.\nThe new Med-kit has 80/90/100 % of its charges.","descriptionRu":"Вы начинаете испытание с 2 жетонами.\nПрячась в шкафчике\nи держа в руках набор инструментов, не относящийся к событию\n, нажмите кнопку «Активная способность», чтобы потратить 1 жетон и превратить свой ящик с инструментами в аптечку.\nтой же редкости со случайным дополнением той же редкости.\nНовая аптечка имеет 80/90/100% заряда.","shortDescriptionRu":"Вы начинаете испытание с 2 жетонами. Прячась в шкафчике и держа в руках набор инструментов, не относящийся к событию, нажмите кнопку «Активная способность», чтобы потратить 1 жетон и превратить свой ящик с инструментами в аптечку. той же редкости со случайным дополнением той же редкости.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_CleanBreak.png":{"englishName":"Clean Break","owner":"Taurie Cain","role":"survivor","descriptionEn":"After completing a Healing action on another Survivor, Clean Break activates.\nPress the Active Ability button while being healed by another Survivor to trigger the following effects:\nSuffer from the Broken\nStatus Effect.\nYou are automatically healed 1 Health State after 75/60/45 seconds.\nThis effect is cancelled prematurely if you enter the Dying State.\nClean Break does not activate if you already suffer from Broken.\nClean Break deactivates after healing you.","descriptionRu":"После завершения действия исцеления на другом выжившем активируется «Чистый разрыв».\nНажмите кнопку «Активная способность», пока вас исцеляет другой Выживший, чтобы активировать следующие эффекты:\nСтрадать от сломанного\nЭффект статуса.\nВы автоматически восстанавливаете 1 состояние здоровья через 75/60/45 секунд.\nЭтот эффект отменяется преждевременно, если вы входите в состояние умирания.\nClean Break не активируется, если вы уже страдаете от Broken.\nClean Break деактивируется после исцеления вас.","shortDescriptionRu":"После завершения действия исцеления на другом выжившем активируется «Чистый разрыв». Нажмите кнопку «Активная способность», пока вас исцеляет другой Выживший, чтобы активировать следующие эффекты: Страдать от сломанного Эффект статуса. Вы автоматически восстанавливаете 1 состояние здоровья через 45 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_CrossExamination.png":{"englishName":"Cross-Examination","owner":"Shane Wiigwaas","role":"survivor","descriptionEn":"While inside the Killer's Terror Radius\nand not being chased, you can see Light Marks the Killer leaves behind while moving. Light Marks have a duration of 10 seconds.\nWhile standing on a Light Mark, gain Elusive\nStatus Effect. This lingers for 3/4/5 seconds.","descriptionRu":"Находясь внутри радиуса террора убийцы\nи, не преследуясь, вы можете видеть световые метки, которые Убийца оставляет позади во время движения. Световые метки имеют продолжительность 10 секунд.\nСтоя на светлой метке, вы получаете Неуловимость.\nЭффект статуса. Это длится 3/4/5 секунды.","shortDescriptionRu":"Находясь внутри радиуса террора убийцы и, не преследуясь, вы можете видеть световые метки, которые Убийца оставляет позади во время движения. Световые метки имеют продолжительность 10 секунд. Стоя на светлой метке, вы получаете Неуловимость.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_DesperateFocus.png":{"englishName":"Down to the Last","owner":"Общий","role":"survivor","descriptionEn":"As more of your friends fall to the Killer, you become shrouded in isolation and the Killer's Aura-reading abilities towards you are disrupted.\nWhenever you are hooked or you repair a Generator\n, Down to the Last gains 1 Token, up to a maximum of 6 Tokens:\nFor each Token, other Survivor open Exit Gates\n+10 % faster.\nWhen you are the Last Survivor Standing and have at least 3 Tokens, you benefit from the following effects:\nGain the ability to open the Hatch\nwithout the need of a Key\n.\nFor each Token, your aura is hidden from the Killer for 6/8/10 seconds.\nIncreases your chance of becoming the initial Obsession by increasing the default value by +100 %.\nThe Killer can only be obsessed with one Survivor at a time.","descriptionRu":"По мере того, как все больше ваших друзей попадают в руки Убийцы, вы оказываетесь в изоляции, и способность Убийцы читать ауру по отношению к вам нарушается.\nВсякий раз, когда вы подсаживаетесь или ремонтируете генератор\n, До последнего получает 1 жетон, максимум до 6 жетонов:\nЗа каждый жетон другой Выживший открывает ворота выхода.\n+10 % быстрее.\nЕсли вы являетесь последним выжившим и у вас есть как минимум 3 жетона, вы получаете следующие эффекты:\nПолучите возможность открывать Люк.\nбез необходимости ключа\n.\nЗа каждый Жетон ваша аура скрывается от Убийцы на 6/8/10 секунд.\nПовышает ваши шансы стать первоначальной одержимостью за счет увеличения значения по умолчанию на +100 %.\nУбийца может быть одержим только одним Выжившим одновременно.","shortDescriptionRu":"По мере того, как все больше ваших друзей попадают в руки Убийцы, вы оказываетесь в изоляции, и способность Убийцы читать ауру по отношению к вам нарушается. Всякий раз, когда вы подсаживаетесь или ремонтируете генератор, До последнего получает 1 жетон, максимум до 6 жетонов: За каждый жетон другой Выживший открывает ворота выхода. +10% быстрее.","upcomingPatch":true},"assets/perks/T_UI_iconsPerks_DoNoHarm.png":{"englishName":"Do No Harm","owner":"Orela Rose","role":"survivor","descriptionEn":"When healing another Survivor, depending on their accumulated Hook Stages, you benefit from the following effects:\nIncreases your Altruistic Healing speed by 30/40/50 % per Hook Stage, up to a maximum of 60/80/100 %.\nIncreases the Progression bonus of Great Healing Skill Checks by +3 % per Hook Stage, up to a maximum of +6 %.\nIncreases the odds of triggering a Skill Check\nby +5 % per Hook Stage, up to a maximum of +5 %Max.","descriptionRu":"При исцелении другого Выжившего, в зависимости от накопленных им стадий крюка, вы получаете следующие эффекты:\nУвеличивает скорость альтруистического исцеления на 30/40/50 % за каждую стадию крюка, максимум до 60/80/100 %.\nУвеличивает бонус прогресса проверок навыков великого исцеления на +3 % за каждую стадию крюка, вплоть до максимального значения +6 %.\nУвеличивает вероятность запуска проверки навыков.\nна +5 % за каждую стадию крюка, максимум до +5 %Макс.","shortDescriptionRu":"При исцелении другого Выжившего, в зависимости от накопленных им стадий крюка, вы получаете следующие эффекты: Увеличивает скорость альтруистического исцеления на 50% за каждую стадию крюка, максимум до 100%. Увеличивает бонус прогресса проверок навыков великого исцеления на 3% за каждую стадию крюка, вплоть до максимального значения +6%. Увеличивает вероятность запуска проверки навыков.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_DutyOfCare.png":{"englishName":"Duty of Care","owner":"Orela Rose","role":"survivor","descriptionEn":"While healthy, taking a Protection Hit causes all other Survivors within 12 metres of your location to benefit from the following effect:\nGrants them a +25 % Haste\nStatus Effect for 4/5/6 seconds.","descriptionRu":"Пока вы здоровы, получение защитного удара приводит к тому, что все остальные выжившие в радиусе 12 метров от вашего местоположения получают следующий эффект:\nДает им +25 % скорости.\nСтатусный эффект на 4/5/6 секунд.","shortDescriptionRu":"Пока вы здоровы, получение защитного удара приводит к тому, что все остальные выжившие в радиусе 12 метров от вашего местоположения получают следующий эффект: Дает им +25% скорости. Статусный эффект на 6 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_ExtrasensoryPerception.png":{"englishName":"Extrasensory Perception","owner":"Eleven","role":"survivor","descriptionEn":"Crouch for 4 seconds to activate this perk. While active:\nYou see the Auras\nof Survivors\n, the Killer\n, and a variety of objects. These are revealed in an expanding 44 meter radius..\nRevealed objects include Chests\n, Exit Gate\n, Generators\n, Hatch\n, Items\n, Pallets\n, Totems\n, and Windows\n.\nYou gain Elusive\nand Oblivious\nStatus Effects\nWhen you stop crouching, or after 11 seconds, all effects of this perk end and it enters a 60/50/40 seconds cool-down.","descriptionRu":"Присядьте на 4 секунды, чтобы активировать этот перк. Пока активно:\nВы видите ауры\nвыживших\n, Убийца\nи различные объекты. Они раскрываются в расширяющемся радиусе 44 метра.\nОбнаруженные объекты включают сундуки.\n, Выходные ворота\n, Генераторы\n, Хэтч\n, Предметы\n, Поддоны\n, Тотемы\nи Windows\n.\nВы получаете Неуловимость\nи не обращающий внимания\nЭффекты статуса\nКогда вы перестанете приседать или через 11 секунд, все эффекты этого перка прекращаются, и начинается период восстановления 60/50/40 секунд.","shortDescriptionRu":"Присядьте на 4 секунды, чтобы активировать этот перк. Пока активно: Вы видите ауры выживших, Убийца и различные объекты. Они раскрываются в расширяющемся радиусе 44 метра.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_FiveMovesAhead.png":{"englishName":"Five Moves Ahead","owner":"Kwon Tae-young","role":"survivor","descriptionEn":"This perk activates while you are being chased by the Killer or are inside the Killer's Terror Radius\n:\nAfter you drop a Pallet\n, you start moving 50 % earlier.\nSee the auras of the 5 closest Pallets.\nThis perk goes on a 40/35/30 seconds cool-down when you drop a Pallet while this perk is activated.","descriptionRu":"Этот перк активируется, когда вас преследует Убийца или вы находитесь в радиусе террора Убийцы.\n:\nПосле того, как вы уронили поддон\n, вы начнете двигаться на 50 % раньше.\nПосмотрите ауры 5 ближайших поддонов.\nЭтот перк восстанавливается 40/35/30 секунд, когда вы бросаете поддон, пока этот перк активирован.","shortDescriptionRu":"Этот перк активируется, когда вас преследует Убийца или вы находитесь в радиусе террора Убийцы.: После того, как вы уронили поддон, вы начнете двигаться на 50% раньше. Посмотрите ауры 5 ближайших поддонов. Этот перк восстанавливается 30 секунд, когда вы бросаете поддон, пока этот перк активирован.","upcomingPatch":true},"assets/perks/T_UI_iconsPerks_FlowState.png":{"englishName":"Flow State","owner":"Kwon Tae-young","role":"survivor","descriptionEn":"Whenever a Generator\nis completed, gain a token, up to 5.\nFor each token:\nBless and cleanse Totems\n13/14/15 % faster.\nHeal 13/14/15 % faster.\nUnhook Survivors 13/14/15 % faster.","descriptionRu":"Всякий раз, когда генератор\nзавершено, получите жетон до 5.\nДля каждого токена:\nБлагословение и очистка тотемов\nНа 13/14/15 % быстрее.\nИсцеляйтесь на 13/14/15% быстрее.\nОтцепляйте выживших на 13/14/15% быстрее.","shortDescriptionRu":"Всякий раз, когда генератор завершено, получите жетон до 5. Для каждого токена: Благословение и очистка тотемов На 15% быстрее. Исцеляйтесь на 15% быстрее.","upcomingPatch":true},"assets/perks/T_UI_iconsPerks_FruitsOfYourLabor.png":{"englishName":"Fruits of Your Labor","owner":"Aurora Stardotter","role":"survivor","descriptionEn":"Whenever a Generator\nis completed, gain a token.\nWhenever you finish repairing a Generator, for each token this perk has:\nGain +5 % Haste\nStatus Effect for 2 seconds.\nGain 10/15/20 % healing progress.","descriptionRu":"Всякий раз, когда генератор\nзавершено, получите жетон.\nКаждый раз, когда вы заканчиваете ремонт Генератора, для каждого жетона этот перк имеет:\nПолучите +5 % скорости.\nСтатусный эффект на 2 секунды.\nПолучите 10/15/20% прогресса лечения.","shortDescriptionRu":"Всякий раз, когда генератор завершено, получите жетон. Каждый раз, когда вы заканчиваете ремонт Генератора, для каждого жетона этот перк имеет: Получите +5% скорости. Статусный эффект на 2 секунды.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_InvocationTreacherousCrows.png":{"englishName":"Invocation: Treacherous Crows","owner":"Taurie Cain","role":"survivor","descriptionEn":"When in the Basement\nnear the circle, press the Active Ability button to begin the Invocation, which takes 60 seconds to complete.\nDuring an Invocation, your Aura\nis revealed to all other Survivors and they can join in, accelerating the process by +100 %, if they too have an Invocation Perk equipped, or by +50 %, if they have not.\nOnce the Invocation is completed, the following effects apply:\nWhenever the Killer scares a Crow\nwhile a Survivor is inside their Terror Radius\n, their Aura\nis revealed to all Survivors for 1/1.5/2 seconds.\nYou automatically enter the Injured State\nfrom any previous Health State, and suffer from the Broken\nStatus Effect for the remainder of the Trial.","descriptionRu":"Когда в подвале\nрядом с кругом нажмите кнопку «Активная способность», чтобы начать призыв, который занимает 60 секунд.\nВо время призыва ваша аура\nраскрывается всем остальным Выжившим, и они могут присоединиться, ускоряя процесс на +100 %, если у них тоже есть навык призыва, или на +50 %, если у них его нет.\nПосле завершения Призыва применяются следующие эффекты:\nВсякий раз, когда Убийца пугает Ворону\nпока Выживший находится внутри радиуса террора\n, их аура\nоткрывается всем Выжившим на 1/1,5/2 секунды.\nВы автоматически входите в состояние травмы\nот любого предыдущего состояния здоровья и страдают от Сломанного\nЭффект статуса на оставшуюся часть Испытания.","shortDescriptionRu":"Когда в подвале рядом с кругом нажмите кнопку «Активная способность», чтобы начать призыв, который занимает 60 секунд. Во время призыва ваша аура раскрывается всем остальным Выжившим, и они могут присоединиться, ускоряя процесс на 100%, если у них тоже есть навык призыва, или на 50%, если у них его нет.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_LendaHand.png":{"englishName":"Lend a Hand","owner":"Shane Wiigwaas","role":"survivor","descriptionEn":"Cleansing or Blessing a Totem\nactivates this perk:\nOnce per Survivor, while healing a Survivor, press Activate Ability 2 to give the healed Survivor 2/3/4 permanent healing charges.","descriptionRu":"Очищение или благословение тотема\nактивирует этот перк:\nОдин раз для каждого Выжившего, исцеляя Выжившего, нажмите «Активировать Способность 2», чтобы дать исцеленному Выжившему 2/3/4 постоянных заряда исцеления.","shortDescriptionRu":"Очищение или благословение тотема активирует этот перк: Один раз для каждого Выжившего, исцеляя Выжившего, нажмите «Активировать Способность 2», чтобы дать исцеленному Выжившему 4 постоянных заряда исцеления.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_RapidResponse.png":{"englishName":"Rapid Response","owner":"Orela Rose","role":"survivor","descriptionEn":"Your survival depends on it.\"\nWhenever you become afflicted by the Exhausted\nStatus Effect, Rapid Response triggers its effect:\nThe Aura of the Killer is revealed to you for 2 seconds.\nPerform a Rushed action to exit a Locker\nto voluntarily trigger the Status Effect for 30/25/20 seconds.\nRapid Response cannot be used to override an existing Exhausted Status Effect.","descriptionRu":"От этого зависит ваше выживание».\nВсякий раз, когда вы начинаете страдать от «Исчерпания»\nЭффект статуса, Быстрое реагирование запускает свой эффект:\nАура Убийцы открывается вам на 2 секунды.\nВыполните срочное действие, чтобы выйти из шкафчика.\nчтобы добровольно вызвать эффект статуса на 30/25/20 секунд.\nRapid Response нельзя использовать для отмены существующего эффекта состояния «Исчерпанность».","shortDescriptionRu":"От этого зависит ваше выживание». Всякий раз, когда вы начинаете страдать от «Исчерпания» Эффект статуса, Быстрое реагирование запускает свой эффект: Аура Убийцы открывается вам на 2 секунды. Выполните срочное действие, чтобы выйти из шкафчика.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_SalvationsCry.png":{"englishName":"Salvation's Cry","owner":"Aurora Stardotter","role":"survivor","descriptionEn":"When the Killer starts chasing you:\nYou see the auras of other Survivors for 1/2/3 seconds.\nSurvivors not being chased see your aura for 5 seconds\nSurvivors not being chased see the Killer's aura for 5 seconds","descriptionRu":"Когда Убийца начинает преследовать вас:\nВы видите ауры других Выживших в течение 1/2/3 секунды.\nВыжившие, которых не преследуют, видят вашу ауру в течение 5 секунд.\nВыжившие, которых не преследуют, видят ауру Убийцы в течение 5 секунд.","shortDescriptionRu":"Когда Убийца начинает преследовать вас: Вы видите ауры других Выживших в течение 3 секунды. Выжившие, которых не преследуют, видят вашу ауру в течение 5 секунд. Выжившие, которых не преследуют, видят ауру Убийцы в течение 5 секунд.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_ShoulderTheBurden.png":{"englishName":"Shoulder the Burden","owner":"Taurie Cain","role":"survivor","descriptionEn":"Once per Trial, and while you are not on Death Hook, press the Active Ability button while standing in front of a Hooked Survivor to unhook them and trigger the following effects:\nTrade 1 Hook Stage with the other Survivor to their benefit.\nCauses you to scream, become injured and suffer from the Broken\nStatus Effect for 160/140/120 seconds.\nShoulder the Burden is then deactivated for all Survivors.","descriptionRu":"Один раз за испытание, пока вы не находитесь на «Смертельном крюке», нажмите кнопку «Активная способность», стоя перед зацепившимся выжившим, чтобы отцепить его и активировать следующие эффекты:\nОбменяйте 1 этап крюка с другим выжившим в свою пользу.\nЗаставляет вас кричать, получать ранения и страдать от Сломанного.\nСтатусный эффект на 160/140/120 секунд.\nПосле этого функция «Взять бремя на плечи» деактивируется для всех Выживших.","shortDescriptionRu":"Один раз за испытание, пока вы не находитесь на «Смертельном крюке», нажмите кнопку «Активная способность», стоя перед зацепившимся выжившим, чтобы отцепить его и активировать следующие эффекты: Обменяйте 1 этап крюка с другим выжившим в свою пользу. Заставляет вас кричать, получать ранения и страдать от Сломанного. Статусный эффект на 120 секунд.","upcomingPatch":true},"assets/perks/T_UI_iconsPerks_TeamworkFullCircuit.png":{"englishName":"Teamwork: Full Circuit","owner":"Dustin Henderson","role":"survivor","descriptionEn":"For each Survivor repairing a generator with you, the size of the good Skill Check zone is increased by 15/20/25 %.\nWhile repairing with at least 1 other Survivor\n, you repair 5 % faster.","descriptionRu":"За каждого Выжившего, ремонтирующего вместе с вами генератор, размер хорошей зоны проверки навыков увеличивается на 15/20/25 %.\nВо время ремонта хотя бы с 1 другим выжившим.\n, вы ремонтируете на 5 % быстрее.","shortDescriptionRu":"За каждого Выжившего, ремонтирующего вместе с вами генератор, размер хорошей зоны проверки навыков увеличивается на 25%. Во время ремонта хотя бы с 1 другим выжившим., вы ремонтируете на 5% быстрее.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_TeamworkSoftSpoken.png":{"englishName":"Teamwork: Soft-Spoken","owner":"Eleven","role":"survivor","descriptionEn":"For each other Survivor\nrepairing a Generator\nwith you, the range at which the Generator's repair noise is heard is reduced by 15/20/25 %.\nWhile repairing with at least 1 other Survivor\n, you repair 5 % faster.","descriptionRu":"Друг для друга\nремонт генератора\nс вами дальность слышимости ремонтного шума Генератора снижается на 15/20/25 %.\nВо время ремонта хотя бы с 1 другим выжившим.\n, вы ремонтируете на 5 % быстрее.","shortDescriptionRu":"Друг для друга ремонт генератора с вами дальность слышимости ремонтного шума Генератора снижается на 25%. Во время ремонта хотя бы с 1 другим выжившим., вы ремонтируете на 5% быстрее.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_WeSeeYou.png":{"englishName":"We See You","owner":"Eleven","role":"survivor","descriptionEn":"Gain a token when the Killer\nreveals your Aura\n.\nWhen you have 4 tokens, they are all consumed, and the Killer\n's aura is revealed to you and all other Survivors for 10/12.5/15 seconds.\nThis perk has a 10-second cool-down when gaining a token.","descriptionRu":"Получите жетон, когда Убийца\nраскрывает вашу ауру\n.\nКогда у вас есть 4 жетона, они все израсходованы, и Убийца\nАура раскрывается вам и всем остальным Выжившим на 10/12,5/15 секунд.\nЭтот перк имеет 10-секундное время восстановления при получении жетона.","shortDescriptionRu":"Получите жетон, когда Убийца раскрывает вашу ауру. Когда у вас есть 4 жетона, они все израсходованы, и Убийца Аура раскрывается вам и всем остальным Выжившим на 15 секунд. Этот перк имеет 10-секундное время восстановления при получении жетона.","upcomingPatch":false},"assets/perks/T_UI_iconsPerks_WideOpenThrottle.png":{"englishName":"Wide Open Throttle","owner":"Shane Wiigwaas","role":"survivor","descriptionEn":"Fast-vaulting a Pallet\ntriggers the following effects:\nGain 10/12.5/15 % Haste\nStatus Effect for 3 seconds.\nThe Pallet is immediately reset, blocked by the Entity and revealed to all Survivors for 60 seconds.\nThis perk then goes on a 60 second cool-down.","descriptionRu":"Быстрое перемещение поддона\nвызывает следующие эффекты:\nПолучите 10/12,5/15 % скорости.\nСтатусный эффект на 3 секунды.\nПоддон немедленно сбрасывается, блокируется Сущностью и открывается всем Выжившим на 60 секунд.\nЗатем этот перк восстанавливается в течение 60 секунд.","shortDescriptionRu":"Быстрое перемещение поддона вызывает следующие эффекты: Получите 15% скорости. Статусный эффект на 3 секунды. Поддон немедленно сбрасывается, блокируется Сущностью и открывается всем Выжившим на 60 секунд.","upcomingPatch":false}};

// Only verified perks can be drawn, and every perk stays in its verified role.
for (const [category, role] of [["killerGood","killer"],["killerBad","killer"],["survivorGood","survivor"],["survivorBad","survivor"]]) {
  PERK_CATEGORIES[category] = PERK_CATEGORIES[category].filter(perk => PERK_DETAILS[perk.image]?.role === role);
}
const roleCorrections = [
  ["Weave Attunement", "killerBad"]
];
for (const [englishName, category] of roleCorrections) {
  const perk = [...killerPerks, ...survivorPerks].find(item => item.englishName === englishName);
  if (perk && !PERK_CATEGORIES[category].some(item => item.image === perk.image)) PERK_CATEGORIES[category].push(perk);
}
const correctedRussianNames = {
  "assets/perks/iconPerks_Hatred.png": "Злоба",
  "assets/perks/T_UI_iconsPerks_ToyWithThem.png": "Пусть подождут",
  "assets/perks/T_UI_iconsPerks_DesperateFocus.png": "До последнего"
};
for (const perk of [...killerPerks, ...survivorPerks, ...Object.values(PERK_CATEGORIES).flat()]) {
  const details = PERK_DETAILS[perk.image];
  if (details) {
    perk.englishName = details.englishName;
    perk.name = correctedRussianNames[perk.image] || perk.name;
    perk.desc = details.owner === "Общий" ? `Общий для ${details.role === "killer" ? "убийц" : "выживших"}` : `Персонаж: ${details.owner}`;
  }
}
